/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20061020-4","meetingId":"h18-c-settlement","date":"2006年10月20日","dateIso":"2006-10-20","committee":"決算特別委員会","time":"午前１０時０３分～午後５時４７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を157件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０３分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成１７年度品川区一般会計歳入歳出決算","agenda":"○午前１０時０３分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成１７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"１４５ページ、プラン２１関連事業で小中一貫教育に関して質問をします。１８日に安倍内閣の諮問機関である教育再生会議、これがスタートいたしました。小中一貫校が順調に進められ、予定どおりいくのかということをまたお聞きしたいということで、よろしくお願いします。","respondent":"濱野区長、吉村小中一貫教育担当課長","answer":"その際に、要するに今ある学校の地域の事情というものをよくお聞きしながら物事を進めていく必要がある、教育委員会あるいは区長部局で単純に進めるのではなくて、地域の実情というものをよく伺いながら物事を進めていきたい。中学校の先生は１人の子どもが何か課題があると、みんなでそれを対応しようとする、小学校には今までなかった文化だということを言っております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"築舘委員","kind":"質問・要望","question":"私立学校におきましても、そういった意味では私立学校は高いお金を払っても、行く人は行くわけです。それはなぜかというと、やっぱり特色あるいいところがあるから、生徒を安心して任せようとするわけです。私立学校ですから、生徒が来なければつぶれてしまうわけです。それと同時に、統合ですから、学校の跡地利用というものもしっかりと考えていかなきゃいけない。","respondent":"若月教育長","answer":"さまざまな状況が、八潮特有の地域的な状況というのがある中で、学校も頑張る中で、１つの保護者の声としてそういった結果が出てきた。それを真摯に受けとめて、子どもたちのためによりよい教育環境をさらにつくっていきたい、さように考えて、これからも進めていく所存です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"築舘委員","kind":"質問・要望","question":"本当に地域のことだけではなく、その活性化だけではないわけですが、教育というものを柱にして、やはり次の世代に対する希望を持たせる、希望がある、そういった改革をしっかりとしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"成果報告書の１４５ページのプラン２１関連事業に関連しての質問をします。いわゆる学力テスト、このプラン２１の柱となる施策のうちの１つと挙げられておりますので、この学力テストについてちょっとお尋ねしたいんですが、いわゆる学力テストの結果の公開というのが２００３年８月から行われたわけですけれども、その目的について改めて見解をお伺いします。","respondent":"河野指導課長","answer":"それに対して実際にどれだけ学力が定着したのかということをきちんとあらわすということは、これは学校の説明責任であると私どもは考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"学力テストというのは、品川区が言っているのは学力定着度調査ということなんですけれども、その結果の公開というのは、学力定着度調査という名前のとおり、学力の定着がどれぐらい身についたのかということで、今、伺ったんですが、学力のアップのためなのでしょうか。学力テストの結果の公開というのは、学力のアップという目的も含まれているのでしょうか。","respondent":"河野指導課長","answer":"それぞれ学校が目指している目標について教育実践をしていく、その結果がどうであったのかということをまた踏まえて、学校としてはさらなる授業改善、指導法の工夫改善に結びつけていくと、そういう点では最終的には子どもたちの学力向上につながっていくと考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"広い意味でつながっているということだったんですが、となりますと、学力テストの公開によって子どもの学力は向上したと品川区はお考えでしょうか。お伺いします。","respondent":"河野指導課長","answer":"１つ具体的な例を申し上げますと、学力の定着度、前年度に比べて、いわゆる正答率、そういうものが向上したというような例はたくさんあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"漢字の読み書きに関して分析をしているということだったんですが、学力向上したという、その根拠をもう一歩踏み込んで具体的に教えていただけないでしょうか。","respondent":"河野指導課長","answer":"例えば学力がどういうところで向上したのかですが、もう一度ちょっと確認しますが、公開によって学力がアップしたのではなくて、その結果を受けて、学校がさらなる指導方法の工夫改善を進めて、その結果がまた次の年に反映させられると、そういう形態のものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"意見","question":"公開によって学力が向上したというわけでは現実にはない、公開ではなくて実施していることによってということだったと思うんですが、繰り返しになっちゃうかもしれないんですが、要するに公開することの意義といいますか、理由といいますかをもう一度ちょっとわかりやすくお願いしたいんですが。","respondent":"河野指導課長","answer":"その目標の中に子どもたちに対する基礎的、基本的な学力の確実なる定着、そういうことを掲げているわけですので、実際に子どもたちにどの程度の学力が定着しているのかということを公開するということは、１つは学校の説明責任として大事な役割であると考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"教師の側の指導力を上げる効果もあるということのお答えだったと思うんですが、それは僕も実は過去の議事録などでちょっと読んだところ、切磋琢磨によって教師の指導力が向上していくというような考えがあるということを見たんですが、その指導力の向上という効果は出ているんでしょうか。効果があるとすれば、具体的に教えていただけるとありがたいんですが。","respondent":"吉村小中一貫教育担当課長","answer":"ですからそういうことのために学校は、今の自分たちの学校の子どもたちには算数のこういうところに課題があります、ですからこの課題を克服するためにこういう指導法にこれからは変えていきますということを保護者にきちんと伝えていこうと、そしてその結果。","voiceIndex":23,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"それで、実際に指導力の向上は出たのかということと、具体的に出たというならば、どういうところにあらわれているかというのをお伺いしたいんです。","respondent":"河野指導課長","answer":"例えば、今年の２月に実施をした区の学力定着度調査の前年度との比較、一例として申し上げますと、漢字の書きについて前回習熟基準を超えたのは１０問中７問であったが、今回は１０問中９問に向上しているというような具体的な結果も出ております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"すいません、子どもの学力アップということですけれども、指導する側の教師の側の指導力の向上につながっているのかどうかということを伺いたいんですが。","respondent":"河野指導課長","answer":"指導力の向上をはかる物差しの１つが、子どもの学力の定着度です。","voiceIndex":27,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"子どもの学力が上がったということが出ているので、教師の指導力が上がっているということでよろしいでしょうか。","respondent":"河野指導課長","answer":"そのとおりです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"そうなりますと、非常にこの学力テストの公開というのは、もう子どもにとっても教師にとってもかなり効果を上げていて、非常にバラ色な結果を出しているという認識だと思うんですが、私はそうとも言えないんじゃないかなと思っておりまして、さまざまな過去の指摘もありますけれども、例えば過去で言いますと、これも以前、共産党からも提示したと思うんですが。","respondent":"河野指導課長","answer":"そうやって弱いところを確実に力をつけてあげるということは、これは学校の使命です。私たちはどの子どもたちにも必要最低限度の学力の定着を目指すということでやっているわけで、詰め込み教育というのとはちょっと意味が違うと考えております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"といいますのは、品川のこの結果として点数競争を激化させる教育というのは、教育基本法にありますけれども、第１条の教育の目的の部分でどういうために教育をやっているのかということを教育基本法では書いてありますけれども、そこで人格の完成を目指すと書いてありまして、具体的に言いますと、どういう人格なのかということ等を書いていますけれども、「真理と正義を愛し、個人の価値をたつとび。","respondent":"河野指導課長","answer":"先ほど来、話題になっておりましたのが学力ということでしたので、そのことを中心にお話をさせていただきましたが、四則計算ができるとかできないとか、そういうことも含めて、できるようにしてあげるということは、これは個人の価値を尊重しているからです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"それで、品川区としては教育の目的に関してはどのように認識しているのでしょうか。","respondent":"河野指導課長","answer":"教育の目的というのは、簡単に言えば生きる力をはぐくむということで、一人ひとりの子どもがみずから考え、判断し、行動できる、そういう人間を育てることととらえております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"みずから考え行動する人間像、それが生きる力だと、そういう人間像は僕も目指したいところなんですが、この学力テストの公開というのが点数偏重を起こして、ある教育内容を上から押しつけるということで、自分の頭で考えるということの弊害になると思うんですけれども、私はそのことを考えざるを得ないということで指摘して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"私は１４４ページの生徒指導対策費、１４５ページの小中一貫教育、この辺のところでお聞きしたいと思います。いじめの問題ということが新聞をにぎわせておりまして、北海道、福岡とありました。そういった中で、いじめは昔からあります。最近顕著になってきていますが、こうしたことを、今、市民科等でやっていかれる心の教育等、どのような形で取り組まれているかというのを教えていただきたいと思います。","respondent":"吉村小中一貫教育担当課長","answer":"領域で言いますと、人間関係形成領域というものを５つの領域の中の１つに設けているわけですけれども、この領域の中で、低学年であれば、まずあいさつであるとか、そういう部分から人とのかかわり方で大切な部分は一体何なのか、中学年から高学年になってくれば。","voiceIndex":39,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"ところで、こうしたいじめですとか、また、児童が児童を殺傷するような事件がこの間、起きてきていますけれども、そうしたときに、例えばその都度やるかどうかは別として、市民科の中でそうしたものを題材というか、取り上げて、それで生徒たちに、例えば感想とか、皆さんどう思いますかという中で、例えば生徒を誘導して指導していく、そうしたやり方というのは行われていますでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"１年生から４年生ぐらいまではちょっと難しいんですが、５年生以降、特に６、７、８、９年生あたりは現代の社会で起きている事象、今回のいじめの問題、こういったものも課題として取り上げながら、生徒に考えさせる、これは市民科の中でも非常に重視しています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"大変申しわけないけれども、ゲームをやったりしますので、その中で死んじゃったというような、そういう言葉も平気で、ゲームですから、使うんです。軽い気持ちなんです。私たち親の責任として、もっと反応していかなきゃいけないし、それをしっかり教えていかなきゃいけない、そう思っているんですけれども、そういう思いで、どのように取り組まれていかれるのか、また、いられるのか、教えていただきたい。","respondent":"河野指導課長","answer":"学校でいじめ、あるいはいじめられているというふうな連絡、相談を受けた場合には、何はさておいても、まずそのいじめられているという、被害を受けている子どもの安全確保、これが第一番です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"そういうことを学校の先生が聞いてあげてほしいんです。どういう思いなのか。それは子どもによっては、いや、これはいじめられているほうも悪いんだよと言う子もいるかもしれません。それで、絶対にいじめた側が１００％悪いんだと、どんな理由をつけてもいじめていい理由はないんだということをぜひ１００％これは徹底していただきたいなと思うんですけれども、いかがでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"今、委員がおっしゃったいじめる側が１００％悪いんだと、こういうことを教師が毅然として子どもに、１年生から９年生まで言っていく、言い続けていく、これが非常に大事なことなのかなと考えています。","voiceIndex":45,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、何か学校で起きたことだから、学校の先生に全部任せればいいんだと、学校の先生は何をやっているんだというようなことになってしまいがちで、親にももちろん、親が一番子どものことをわかっていなきゃいけないわけですから、そういう意味で、親にもそういう機会というか、もちろん教師と親と地域の連携ということが叫ばれていますけれども、どうしてもお互い連携する中で。","respondent":"河野指導課長","answer":"学校と保護者と地域社会、この３者がお互いに共通理解を深めて、連携を強めて、一人ひとりの子どもたちにかかわっていく、それが大原則でありますので、今後ともそういう努力を各学校に求めていく、指導していくという所存です。","voiceIndex":47,"id":"exchange-021"},{"speaker":"大西委員","kind":"質問・要望","question":"この間聞いてびっくりしたんですけれども、知らないんですかと、よその学校はもう６校もスキー教室に行っていますよ、知りません、そうですか、それで、今回は１０月５日に校長会があったということで、私はこの内容のことが当然教育委員会から報告されている、ここに書いてありますが、言われたとおり、何々議員からこういう質問があったので。","respondent":"市川庶務課長","answer":"それに加えて、各校長にはイントラの上で、質問の趣旨、答弁の趣旨を記したものを登載していますので、それを見るようにということで指示をしています。","voiceIndex":50,"id":"exchange-022"},{"speaker":"大西委員","kind":"質問","question":"そういう形のことをおっしゃっていますけれども、教育次長が答弁したのは、何々議員からこういう質問があって、私どもはこういうふうに答えましたということを十分に周知いたしますと、十分な周知をそれじゃなしていないわけです。私の質問に対して。それ自体はどうなんですか、次長。","respondent":"長田教育次長","answer":"そういった意味も含めまして、ただいま庶務課長がお答えをしたように、イントラを通じまして、質問の内容、それから答弁の内容、こういったものを学校に送って周知を図ったです。","voiceIndex":52,"id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"どうも私が一般質問のときに受けた印象とは違う形に受けます。民泊のことを、民泊の「み」の字も校長会ではみんなが関心を持ってないということは事実なんです。この件はこれで終わります。ただ、文部科学省はここ過去５年、１０年間でいじめによる自殺者がゼロだと出しておりますけれども、それじゃ、品川で例えばこの５年１０年の間に小学生、中学生で自殺をされた方はおられますか。","respondent":"河野指導課長","answer":"過去５年間にわたっては、品川区内で自殺をした子どもというのはおりません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"大西委員","kind":"質問","question":"幸いなことだと思います。これは以前から私はずっと本会議並びに予算、決算特別委員会で申し上げているんですけれども、たしか小学校３年生を対象におやりになられたかと思いますけれども、その後どういう形で推移をしているかということと、ちなみに現行において、学校側から小学校および中学校でのいじめの報告というのはどのようになっているかを教えてください。","respondent":"河野指導課長","answer":"最初にお尋ねのＣＡＰの件ですが、現在でも全小学校の３年生と５年生を対象に実施をしています。それから２番目にお尋ねのいじめの問題ですが、平成１７年度、学校から報告の上がった件数は小学校が１件、中学校が３件ということで報告をいただいております。","voiceIndex":56,"id":"exchange-025"},{"speaker":"大西委員","kind":"質問","question":"ただ、もっとたくさんあるという部分については、報告がない部分としてたくさん潜在的に起こっているという認識はどこでとらえられたのかということと、それと１件、３件があったということですけれども、これに対しては教育委員会としての、そこの時点で当然何らかの対処をなされていると思うんですけれども、具体的な教育委員会としてのそのときのサジェスチョンというんですか。","respondent":"河野指導課長","answer":"７年生、８年生ぐらいになりますと、かなり子どもたちも理解力が高まってまいりますので、それぞれの具体的な場面に触れて指導をしていくということのほうが適切なのかなと考えているところです。","voiceIndex":58,"id":"exchange-026"},{"speaker":"大西委員","kind":"質問","question":"今、おのおの学校での解決ということでしたけれども、私はこれはおよそ教員の資質といいますか、担任教諭であったり、校長の資質によって問題解決能力のあるなしが随分あろうかと思うんですけれども、その部分については、例えば教員は今、都から品川区は受け入れているという認識を私は持っているんですけれども、そういう状況の中で、少し今の教員に対して私は非常に不信感というんですか、どうなのかな。","respondent":"河野指導課長","answer":"いじめ等の発生時におけるスクールカウンセラーの役割ですが、保護者の相談に乗ったり、あるいはそのいじめを受けている子どもの直接の相談に乗ったりというようなことで対応する一方。","voiceIndex":60,"id":"exchange-027"},{"speaker":"大西委員","kind":"質問","question":"これは特段重要かどうかはちょっとわからないんですけれども、子どもたちが相談しやすいという観点からお尋ねしますが、スクールカウンセラーというのは、今、品川区に何名いて、それは男性、女性がどういう状態になっているかということをお尋ねしたいのと、あまり時間がないのでそれの人数を聞いて、それから後に、あと指導課長はおよそ中央区から学校の校長からこっちに来られたと思うんですけれども。","respondent":"河野指導課長","answer":"当時、私の勤務している区で教育改革について研究しようということで、そのプラン２１を取り寄せて、いろいろ検討させていただいたという思いがあります。","voiceIndex":62,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"成果報告書の１４４ページ、義務教育施設整備基金積立金と１５０ページの学校施設建設費についてお伺いしますが、まず義務教育施設整備基金積立金の目的をお伺いします。","respondent":"日下部企画財政課長","answer":"義務教育施設整備基金積立金の目的ですけれども、これはもう申し上げるまでもございませんけれども、小中学校の改築でありますとか、小中一貫校の建設、その辺のところに多額の経費がかかりますので、そのための備えということで基金を積み立てているものです。","voiceIndex":65,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"９９ページの教育債で３億８,５００万円計上もしております。そして、さらに特別区債も計上していると思うんですけれども、何でこう非常に難しい予算のやりくりをしたのかなという思いが私はあるんですけれども、そこがまず１点と、それとこの辺の基金の出し入れの額の決め方が２点目、そしてもう１つは、３番目として特別区債を含めたこういう考え方をなぜするのか、３点についてお伺いします。","respondent":"日下部企画財政課長","answer":"それから額の決め方でありますけれども、これは最終的に、今、冒頭で例えば実際の積立金の額でありますとか、繰り入れの関係とか、いろいろご指摘がございましたけれども、これは当該年度、やはり最終段階になりまして、どうしても例えば財源的な余裕。","voiceIndex":67,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"今後、学校の耐震工事や小中一貫校でまた多額な工事費がかかっていくと思うんですけれども、今、今後の財源の組み立て方の基本的なお考えというのはお伺いしましたけれども、その多額にかかっていく財源の組み立て方についての基本的な考えというのをもう一度ご答弁いただけますか。","respondent":"日下部企画財政課長","answer":"ですから、そういった中長期の財政見通しといいますか、実際にどのくらいこれが費用がかかっていくのか、それに対しまして、今、申し上げましたような財源構成の中で、どの程度の資金の確保をあらかじめきちんとしておく必要があるのか、単年度だけでこれを見ても。","voiceIndex":69,"id":"exchange-031"},{"speaker":"三村委員","kind":"質問・要望","question":"こういったことで、先ほど武内委員から、子どもたちに対しては市民科の授業の中でそういったいじめの問題、またＣＡＰでもいじめのこと、いじめというか、そういういじめに対応する力をつけるということで、子どもたちに対してはいろいろ取り組みをされているかと思うんですけれども、先生に対しては、こういったいじめの問題を起こさないための取り組みというのはどういったことがされているのでしょうか。","respondent":"河野指導課長","answer":"そういうときには、もうこれは当然しかるわけですけれども、しかった後のフォローというようなことについても十分配慮しているです。","voiceIndex":72,"id":"exchange-032"},{"speaker":"三村委員","kind":"質問","question":"先生に対する研修などもされているということなんですけれども、他の自治体などでは第三者機関、先ほど大西委員からカウンセラーというようなお話もあったんですけれども、直接学校と関係のない第三者が間に立って、こういったいじめなどの問題が起きた場合、きちんと調査活動を行って、先生に対するアドバイス、また学校。","respondent":"河野指導課長","answer":"他の自治体でいじめ等が発生したときに、学校外ですか、そういうお話ですが、具体的には、私どもはまだそういうような情報をキャッチしておりません。内容等を確認をして、できるかどうかを含めて検討させていただきたいと思います。","voiceIndex":74,"id":"exchange-033"},{"speaker":"三村委員","kind":"質問","question":"先日、キッザニアという施設がオープンして大変人気があるということで、今、話題になっているんですけれども、こういった取り組みに先立ちまして、品川区でも子どもたちに対する労働についての積極的な学習の機会の場を提供しているということで評価されるものだと思うんですけれども、具体的にどういった取り組みがされているのかをお伺いいたします。","respondent":"吉村小中一貫教育担当課長","answer":"例えば住宅にお金をかけたいという子は住宅に重点をかけるでしょうし、住宅は質素にして、私は車を買いたいんだという子どもがいれば車のほうにかけるだろうし、そういう形で自分の将来設計を考えていくというプログラムです。","voiceIndex":76,"id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"具体的に将来像を規定をして、子どもたちに対してそういった場合の将来像というのを具体的に見せていくということだったんですけれども、今、どうしても企業のリストラなどによって若年の労働者の二極化というのが大変進んでいまして、正規、非正規ということで格差が広がっておりますけれども、そういった違いについてもきちんと具体的にそういった教育の中で伝えられているのかどうか。","respondent":"吉村小中一貫教育担当課長","answer":"今、委員がおっしゃったようなことについては社会科の中で出てくる材料でもありますし、また、義務教育の中で必ずしもすべてを学ぶ必要はないわけで、段階的にこの後の学校教育の中で学ぶこともあろうかと、そんなふうに考えております。","voiceIndex":78,"id":"exchange-035"},{"speaker":"三村委員","kind":"質問","question":"当然、直接就職にかかわる直前の時期というのは大変その時期も重要かと思うんですけれども、『１３歳のハローワーク』というものがあるように、小さいときからの本が売れているように、やはり小さいときからの意識づけ、労働者の権利が正規と非正規で保障のされぐあいがどれだけ違うのか、きちんとそういったことについても教えていく必要があるかと思いますので、ぜひこの点についても。","respondent":"吉村小中一貫教育担当課長","answer":"先ほども申し上げましたように、社会科は特に公民という学習の領域の中でそういったことについては当然触れていく内容ですので、ファイナンス・パークで学ぶときには社会科との関連で勉強するわけですので、そういうことを意識させることはこれからもしてまいりたいと思います。","voiceIndex":80,"id":"exchange-036"},{"speaker":"三村委員","kind":"質問","question":"１４５ページのすまいるスクールについてお伺いいたします。先日、別のところでも触れさせていただいたんですけれども、すまいるスクールは子どもたちの受け入れというのは６時までということになっておりますけれども、受け入れを延長してほしいといった声などは教育委員会に届いているかどうか、その点についてお伺いいたします。","respondent":"市川庶務課長","answer":"すまいるスクールの開設時間の延長に関する保護者からの要望につきましては、学年初め、４月の当初に数件電話、それからメール、こういったものでの要望が寄せられた経緯があります。","voiceIndex":82,"id":"exchange-037"},{"speaker":"三村委員","kind":"意見","question":"当然、全員が全員そういった夜間の受け入れが必要かということではないんですけれども、私自身も小学校低学年からかぎっ子で育っていて、家で１人でお留守番ということもしていたんですけれども、なかなか今の社会情勢だと、子どもを対象にした犯罪でありますとか、子どもが被害者になる事件がいろいろ多発している中で、なかなか子どもを１人で家の中には置いておけないといった声も実際にありますので。","respondent":"新美企画部長","answer":"そういった意味では、例えばファミリー・サポート事業ですとか、いろいろ受け皿を多様化して、できるだけ安心してできる、で、子育てが家庭でできる体制の支援というのは、今後検討してまいりたいと考えております。","voiceIndex":84,"id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"すまいるスクールのことでもう１点、今、入札制度で選定業者、委託されているところがあるかと思うんですけれども、その入札のときに金額以外の項目で入札、選定業者が決まるのかどうか、今、保育の質ということで、保育園の民間委託に関しては、その委託先をどうやって質を確保するかという取り組みがほかの自治体でも始まっているかと思うんですけれども。","respondent":"市川庶務課長","answer":"ただし、入札に付する私どもの契約条件と申しましょうか、業務仕様、その中でできる限り、いわば直営で提供しているレベル、そこの維持向上、こういったものについては具体的に示していますし、今後もそういうところは心がけてまいりたいと思ってあります。","voiceIndex":86,"id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"業務仕様書の中身というところでそういった保証をしていこうというふうなお答えだったんですけれども、具体的にはその中身はどういった項目があるのかを具体的にお伺いできますでしょうか。","respondent":"市川庶務課長","answer":"１つは委託業務の具体的な内容、スポーツ、遊びの指導、子どもへの生活全般にわたる対応、それからそれらの業務に当たる基本的な配置基準、こういったものについて示しています。","voiceIndex":88,"id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"そういった中で、子どもに携わる職員の経験の有無でありますとか、研修の制度といった部分についてはどういった基準が設けられているのでしょうか。","respondent":"市川庶務課長","answer":"具体的なスタッフの選定にあたりましては、極力児童指導の経験を持つ、あるいは教職経験、あるいは教員免許を保有する、こういったことを求めているところです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"三村委員","kind":"質問","question":"児童指導の経験というのは教師というような、そういったものも含まれる、教員免許があるといった点でということでしょうか。そういった実際に子どもに携わる業務にきちんとついていたのかどうか、そういった経験があるのかどうか、そういったところについてはその基準の中に含まれているものかどうかを伺いたいと思います。","respondent":"市川庶務課長","answer":"児童指導というのは何も教員としての指導だけではなくて、例えば福祉施設での指導、そういう方も含めてのものです。","voiceIndex":92,"id":"exchange-042"},{"speaker":"三村委員","kind":"質問・要望","question":"全員が全員そういった免許ですとか、経験があるべきということではないんですけれども、やっぱり核となる人はきちんとしたそういう経験でありますとか、子どもたちへの対応、問題が起こった場合の対応でありますとか、長時間子どもたちの受け入れの場になっているということも考えて、生活面も含めた、そういった目配りのできる人がやっぱり配置をされるということが求められるかと思うんですけれども。","respondent":"市川庶務課長","answer":"複数のスタッフのうち、おっしゃるとおり、いわばチームリーダーにあたるスタッフについては、先ほど来申し上げている免許はもちろんのこと、経験、これを積んでいないと、実際現場のスタッフの指導ができませんので。","voiceIndex":94,"id":"exchange-043"},{"speaker":"三村委員","kind":"質問・要望","question":"なかなか仕組みの上で入札ということで選定業者を選んでいるので、そこの壁はあるかと思うんですけれども、子どもたちを受け入れる先を価格競争だけで選ぶというようなところではなくて、質の競争、いかに質の高い業者に委託できるか、そこで競ってもらえるような仕組みづくりを今後ぜひ考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-044"},{"speaker":"山内委員","kind":"質問・要望","question":"特色ある学校づくり整備なんですけれども、先ごろ大崎中学校がバレーボール全国大会３位になりまして、これは本当に品川区民にとってはまさに誇りであり、やはりこういうアピールをできる、まさに品川の中学校ここにありというような、そういうアピールができるのではないかと思っているんですが、ちょっと教えていただきたいんですけれども。","respondent":"河野指導課長","answer":"その相談を受けまして、品川区内に地域スポーツ指導者と連携した地域一体型の部活動をモデル的につくってみてはどうかということで検討をさせていただきました。","voiceIndex":98,"id":"exchange-045"},{"speaker":"山内委員","kind":"質問","question":"今回はバレーボールの話なんですけれども、この先は、例えば野球を強化していく中学校とか、サッカーを強化していく中学校とか、そういう種類別にそのような形で進めていく方針はあるんでしょうか。","respondent":"河野指導課長","answer":"現在、構想ですが、平成２０年度に開校する予定の八潮地区の小中一貫校については、非常に広々としたそういうグラウンド等もありますので、野球ですとかサッカー、そのあたりを中心とした地域連携型の部活動ができるといいなと考えているところです。","voiceIndex":100,"id":"exchange-046"},{"speaker":"山内委員","kind":"質問","question":"そのような費用が大変にかかるという話を何かどこかで聞いたんですけれども、このようなお金の問題が絡んでくると思うんですが、区としては例えば強化していく部活の中学に対して助成をしていくという方針はあるのでしょうか。","respondent":"古里学務課長","answer":"このような例は初めてですので、今後の計画ということですが、学校におけるそうした活動を見ながら、企画財政課と相談をしながら、その措置について検討してまいりたいと思います。","voiceIndex":102,"id":"exchange-047"},{"speaker":"山内委員","kind":"質問","question":"わかりました。そうするとやはり学校内での、チーム内でのまず競争心というものが低下をする危惧があるかと思うんです。それと、結局、大崎中学校にはバレーボールは勝てないというほかの学校の意識というものもあると思うんです。その辺の競争心の低下を防ぐというか、そのようなお考えというのはあるんでしょうか。","respondent":"河野指導課長","answer":"先ほどの例にありましたように、レベル差を感じてこのまま続けられないのではないかと悩む子どもに対しては、選択肢として、やめてほかに行くというのも１つの方法ですが、教員としては、もし私が担任の立場であれば、頑張ってごらんと励ますだろうなと思います。","voiceIndex":104,"id":"exchange-048"},{"speaker":"山内委員","kind":"質問・要望","question":"その辺をしっかりと品川区もこれから見守っていただきたいなと考えています。やはりあいさつというものを私はもっともっと品川区というものに浸透させていきたいという願いがございまして、今、品川区としてはどのようなあいさつに対してのお考えというか、またどういう形で皆様に広めているのかとか、そういうことをちょっとお伺いしたいんですけれども。","respondent":"吉村小中一貫教育担当課長","answer":"今、委員がおっしゃったように、あいさつというのは基本的な生活習慣、それから人と人をつなぐ上で一番大事なことかと我々も認識しております。あいさつということ、例えば、つい先だってある中学校へ行ったんですけれども、非常に子どもがよくあいさつをするんです。","voiceIndex":106,"id":"exchange-049"},{"speaker":"山内委員","kind":"質問","question":"わかりました。これはまさに会話をする上での本当にきっかけというか、あいさつというのはもともとはしつけの部分で考えられていたことが、今、防犯的な部分で考えられる１つの本当に抑止力になると思いますので、私も街角でしっかりとあいさつをして、それで子どもたちに教えていけたらなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"私は習熟度別学習について、親の立場というか、伺いたいと思います。私は学習だとか、さまざまな交流を通して育ち合い、友情をはぐくめる場だと思うんですけれども、多分、教育の学校の先生方もそうあるべきだということで努力をしていただいていると思いますけれども、その中でどんなご苦労があるのかをちょっとご紹介していただきたいと思います。","respondent":"河野指導課長","answer":"その中では、一方の人はこうしてほしいということに対して、また全然違う要求もされるというようなことで、学校がとまどうというような場面も最近では増えてきております。","voiceIndex":110,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"もう１つ、私は学校というものがどういう場になっているのかというふうに思うわけですけれども、学びの場であることは確かでありますけれども、その学びを通して競争を強いられる、そういう場になっているのではないかなというふうな気がして、それがバックヤードとしてあって、子どもたちのいじめだとか、自殺だとか、そういう状況があるのではないかというふうに思いますけれども。","respondent":"河野指導課長","answer":"一方で、じゃあ、すべて競争の場だけなのかなというと、必ずしもそうではなくて、お互いに協力をしたり、役割分担をしたりして学習を進める場というものもあります。","voiceIndex":112,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"そういう点で、やっぱり品川区としては、どういうふうに、今、実施されている習熟度別学習というものが、やっぱり４人グループでも、何人グループでもいいですけれども、しかし、少人数のグループ編成の中でお互いに学び合える教育の内容になっているのかどうかということを私はちょっと確かめておきたいというふうに思うんです。","respondent":"吉村小中一貫教育担当課長","answer":"今お尋ねの習熟度別学習についてのことですけれども、その習熟度別学習、品川区は５年生以上でやりますよということでやっておりますが、実際では、じゃあ、習熟度別学習の時間というのが全体の中でどれぐらいなのか。","voiceIndex":114,"id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"それが決して、いわゆる進んでいる学力のあるグループではなくて、そうじゃないグループだということで紹介されたというんですね。それがある程度の学力が低いレベルに抑えて、そこの中でわかるようにする、その努力そのものは否定はしないですけれども、しかし、そういうこと自体が子どもを伸びるという、そういう気持ちをそいでしまうことになると思うんですけれども、その辺の見解はどうですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"少なくとも教育を志し、教育の実践をされてきた方であれば、私は子どものそういう仲よくしていたあの子があっちのクラスで、自分はこっちのクラスだと、そしてまた逆の場合もあると思うんですけれども、友情がそこで私は断ち切られてしまうぐらいに子どもは衝撃が大きいものだと思うので、常に教育者として心を寄せなければいけない立場は、弱い者たちに心を寄せる。","respondent":"河野指導課長","answer":"それが一斉授業の中で、例えば中間のレベルに合わせた授業をやったときには、できる子はあきてしまう、できない子はついていけない、これではすべての子どもたちの学ぶ意欲を育むことはできません。","voiceIndex":119,"id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"もういいかげんに日本は一斉教育、１つの大きな教室で数十人の子どもを１つの黒板に向かわせて一斉授業というそうですけれども、そういう教育のやり方はやめるべきだと、これはもう世界の流れだし、そこに固執していたのがアジアの何カ国があるそうですけれども、そこでも韓国だとか、中国だとか、そういうところでもやめる傾向になってきているというふうに指摘されていますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-056"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、１４６ページの学校教育費の中に入ると思いますが、特別支援教育につきましてお聞かせをいただきたいと思います。同じ教育ですので、その目標、目的とするところは同じ地点になる、ゴールというふうに思うんですけれども、この２つの教育は、アプローチの仕方が違うのでしょうか。それとも全くその２つの教育というのは異質なものなのでしょうか。そこら辺の品川区としてのご所見を伺いたいと思います。","respondent":"河野指導課長","answer":"特別支援教育のほうは、いわゆる障害を持たれている児童生徒に対して個々に支援をして、それぞれの能力、個性をいかに伸ばすかということで、対象となる児童生徒、障害があるかないかという違いはありますが、どちらも一人ひとりの子どもを大切にして、その能力。","voiceIndex":124,"id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"この例えが適当かどうかはわかりませんけれども、花や緑に例えれば、伸びようとする苗というものに一生懸命先生が肥料を与え、その子どもたちの学習の能力、学力の向上等々を伸ばそうとすることを小中一貫教育というならば、特別支援教育というのは、自分がこれからどういう花になっていくのだろう、自分はどういうふうに輝いていくのだろう。","respondent":"河野指導課長","answer":"もう少し具体的に申しますと、例えば、さまざまな障害の影響によりまして、人間関係がうまく構築できないであるとか、あるいは特定の領域になかなか理解をすることができないというようなのが障害の特徴として挙げられるわけですが、通常の授業の中では。","voiceIndex":126,"id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"そこで、あとは具体的な施策の展開、計画の策定に当たっては、これは文科省からは、一昨年度でしょうか、いわゆるガイドライン、試案なるものが当然区の教育委員会にも出されて受けていると思います。こういうものを踏まえまして、本区としては、特別支援教育の具体的な施策の展開、計画の策定については、例えば要綱ですとか、規則ですとか、そういう文章になっているものがあるのでしょうか。","respondent":"河野指導課長","answer":"本区としての特別支援教育に関する要綱、規則等があるかというお尋ねですが、現在、そういうものを策定している最中です。","voiceIndex":128,"id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"じゃあ、今の要綱、規則を策定中ですが、いつごろのスケジュールになるのか、後ほどお答えいただきたいと思います。そこで、現在の庁内体制や、また学校現場におけます特別支援教育の体制をお聞かせいただきたいと思います。あわせまして、この来年度に向けた今後の課題、どのようにとらえておられるか、お聞かせをいただきたいと思います。","respondent":"河野指導課長","answer":"庁内における準備ですが、特別支援教育検討委員会というものを立ち上げまして、そのメンバーの中に、教育委員会だけでなく、区長部局の関係の課長にもご同席いただいたり、それから福祉関係の方、あるいは障害児を持つお子さんの保護者の方々の団体の代表の方。","voiceIndex":130,"id":"exchange-060"},{"speaker":"若林委員","kind":"質問・要望","question":"庁内体制、わかりました。学校現場における体制、どこまで進んでおられるか、具体的に校内組織、またコーディネーター等、そこら辺の設置の状況をお聞かせいただきたいと思います。","respondent":"河野指導課長","answer":"そういう体制整備の点ですが、現在、ほぼ校内委員会、あるいはコーディネーターの任命１００％というところまで進んでおります。","voiceIndex":132,"id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、今後の課題につきまして、まず１点に、各学校、これは小中になりますか、いわゆる発達障害児への支援を行える経験や知識を持った教員の方が現状どういうふうに現場にいらっしゃるのかをお聞かせいただきたいと思います。それとともに、今後の加配の見込みというのはあるのでしょうか。お聞かせ願います。","respondent":"河野指導課長","answer":"ただ、特別支援教育の場合には、今後さらなる具体的な支援ということになるわけですが、そのことについては、まだまだいろいろな手法について勉強をしなければならないこともありますし、それから、一人ひとりの子ども、単に軽度発達障害といいましても。","voiceIndex":134,"id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"今、教員のそういう経験を持った方はたくさんいらっしゃるということで大変心強いのですが、たくさんと言っても、それはまた一部の方でしょうから、そこで、前々から教員に対する校長先生はじめ先生たちの研修、スキルアップということを私も党としても訴えてまいりましたが、今年度、特別支援教育研修会というものを全５回にわたりまして行っているというふうに伺いました。","respondent":"河野指導課長","answer":"そのうち既に４回の実施が終わっているわけですが、この４回の研修会で、延べおよそ３２０名程度の教員が参加しております。研修の内容といたしましては、「特別支援教育とこれからの学校教育の課題」というテーマで、筑波大学の先生をお願いして実施しております。","voiceIndex":136,"id":"exchange-063"},{"speaker":"若林委員","kind":"質問・要望","question":"研修が３２０名の方が今年度これまで受けられて成果を上げられているということで、また引き続き優秀な講師を呼んでいただいて、毎年度続けていただきたいなというふうに要望します。１つ、この研修なんかもいわゆる通常の学級を担当する教師への支援ということで大変に重要な１つと思います。この考え方をお知らせいただきたいというふうに思います。","respondent":"河野指導課長","answer":"介助員の件ですが、現在、こちらのほうも介助員検討委員会を立ち上げまして、これからの特別支援に関連する軽度発達障害を持っている子どもたちのどういう体制を組んでいくのか、あるいは介助員の資質をどう向上させるかというようなことについて、現在、検討している最中です。","voiceIndex":138,"id":"exchange-064"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、１４７ページ、特色ある学校づくりに入るのかなと考えています。それから、教員のことについてちょっとお聞きをしたいなと考えています。自民党では、ずっと教員、品川区で採用をという採用権の話をしてまいりました。その制度が変わるのを待つという形で行くのか、そうではなく、区の費用で教員を採用していこうとされているのか。そこら辺をちょっと教えていただきたいと思います。","respondent":"長田教育次長","answer":"これは１つは財政の問題もそうですけれども、それから制度の問題、それから、そういったものについてもさまざまな部分での検討が必要かというようなことがありまして、すぐ来年度というわけにはいかないような状況になってあります。","voiceIndex":141,"id":"exchange-065"},{"speaker":"石田委員","kind":"質問・要望","question":"もう一度ちょっと教えていただきたいんですが、今、障害という話と制度の話が出ました。杉並の例を出すわけではないけれども、やろうと思えばそんなに大変なことなのかなと今思っているんだけれども、そんなにいろいろさまざま障害があるのであれば、何が障害なのか教えてください。","respondent":"濱野区長","answer":"私もそういうことでお話をしてまいりました。その考えは変わっておりませんし、前向きに進めていきたいと。ただ、このことを実施するには、さっき障害という言葉を使いましたけれども、準備しなければならない事柄が幾つかある。","voiceIndex":143,"id":"exchange-066"},{"speaker":"石田委員","kind":"質問・要望","question":"うちの学校はこういう形の子どもの育て方をしますよというのが、義務教育なのでどうしても押しなべて、今、教育改革全体で、市民科もやられているけれども、全体でやろうということではなく、そういう特色のある学校をつくってもいいのだろうと思うんですが、そこら辺の５歳児と今のお話の考え方を教えてください。","respondent":"河野指導課長、若月教育長","answer":"５歳児との小学校交流事業については、現在、検討を進めている最中です。しかし、自信を持ってそこら辺を学校色をしっかり出せということは日ごろからも指導しておりますし、これからも私はそういう点で特色を出すべきだと、このように考えているところです。","voiceIndex":145,"id":"exchange-067"},{"speaker":"石田委員","kind":"意見","question":"それを真剣に取り組んでいると、ちょっとやんちゃな中学生がいて、はっきり言えば不良がいて、だけど、そういう子がクラスの中で、子ども同士の中で、しっかりと、おまえ、そういうことするなよ、おまえのためにこれで２位になったらどうするんだ、３位になったらどうするんだ、ちゃんとこういうことはやれよ、それがすごく子ども同士の中でやれている。方向的には。","respondent":"若月教育長","answer":"したがいまして、まず私が全校長に言って現実に変わったことは、この前たまたま小学校の連合体育大会がありました。集団行動をもっとビシッとしてほしい。だらだらだらだらおじぎ１つできないのは困る。ここをまず徹底してくれ。どの学校もやってほしいということは言いました。","voiceIndex":148,"id":"exchange-068"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひそれは進めていただきたいなと思いますし、先ほどのボランティア活動とか、これは主に中学生になってくるのでしょうか、職場体験、例えば、行ってお客さんとして迎えられて帰ってくる職場体験が非常に多いわけですけれども、もうちょっと突っ込んでやってあげると、例えば業界の中で決まり事、決め事、例えばあるホテルの規律の中には、ホテルマンはひげは生やしてはだめだよとか。","respondent":"河野指導課長","answer":"委員のおっしゃるとおりです。現在、区内の中学校全校で職場体験は実施しておるところですが、日数についてもかなりばらつきもあります。","voiceIndex":150,"id":"exchange-069"},{"speaker":"阿部委員","kind":"質問・要望","question":"私も、先ほどのご質問でも少し話題になっておりましたが、品川区の特別支援教育体制について、まずはお伺いしたいと考えています。","respondent":"河野指導課長","answer":"区内の学校に特別支援が必要であるのではないかといういわゆる軽度発達障害の可能性のある子どもがどのくらい在籍しているのかですが、正確にこの子が軽度発達障害であるという断定がなかなかできませんので、その可能性があるということで。","voiceIndex":153,"id":"exchange-070"},{"speaker":"阿部委員","kind":"質問","question":"最初のお答えについてなんですが、心障学級経費の中にこの通常学級に在籍する特別な支援を必要とする子どもたちに対する事業も含まれているということでしょうか。ということは、何か独立した事業があるのであれば、その名称を教えてください。","respondent":"河野指導課長","answer":"心障学級経費の中に具体的にどのような項目が含まれているのかというお尋ねですが、平成１７年度の予算の中に、介助員の経費、それから巡回相談、これは専門家チームによる巡回相談にかかわる経費、それから特別支援教育検討委員会の実施に関する経費。","voiceIndex":155,"id":"exchange-071"},{"speaker":"阿部委員","kind":"質問","question":"この１.１％という数字が現場の実感とずれがないのかどうか、また今後とも区内の学校を見ていく中で見ていきたいと考えています。ところで、その心障学級経費の中の巡回相談なんですが、これはモデル校事業であったと思うのですが、これは何校ぐらいで行われているのでしょうか。そしてまた、専門家チームが巡回していない学校については、どのようなフォローが行われているか教えてください。","respondent":"河野指導課長","answer":"そのスクールカウンセラーと我々のほうと連絡をとりながら、モデル校に該当にならなかった学校については支援をさせていただいているという状況です。","voiceIndex":157,"id":"exchange-072"},{"speaker":"阿部委員","kind":"質問","question":"そのスクールカウンセラー、多分、先ほどいじめなどの質問の中でも出てきたスクールカウンセラーと同じ制度を使われているかと思うんですが、このスクールカウンセラーの方は、いじめですとか、いわゆる臨床心理の本流の部分だけではなくて、発達障害ですとか、そういった部門にも明るい方が派遣されていると考えてよろしいですか。","respondent":"河野指導課長","answer":"本区で採用しておりますカウンセラーですが、心理に関する資格を持っているということが大前提になるわけですが、実際の面接の際に、軽度発達障害に対する理解であるとか、あるいは今までのかかわりであるとか。","voiceIndex":159,"id":"exchange-073"},{"speaker":"阿部委員","kind":"質問","question":"といいますのは、お隣の港区では、ＮＰＯで学習支援員というような形の方を養成して学校に派遣される、本年度からの事業というふうにちょっとそのＮＰＯの方に伺ったんですけれども、実際には緊急性があるケースについては昨年度からも学校に入れていらして、それなりの成果をおさめているというふうに伺ったものですから、ですから、学校も人手が足りなくて大変だと思いますし。","respondent":"河野指導課長","answer":"来年度から本格実施される特別支援教育に関しましては、従来のような単なる介助員制度では対応し切れないであろうというふうに私どもも判断しておりまして、どういう介助員制度にすべきなのかということについて、現在、介助員制度検討委員会を設けて、介助員の雇用制度。","voiceIndex":161,"id":"exchange-074"},{"speaker":"阿部委員","kind":"提案","question":"１つ、先ほども出ておりました通級学級なんですが、これ、品川区では小学校の通級、軽度発達障害の子どもたちを対象にしたものは小学校１校だけだというふうに思っているのですが、間違いないでしょうか、１校だけだと思うんですが、これ、さすがに品川区がどれだけ交通の便がいいと言っても、やはり通級で１校だけというのでは実際に通えない子どもも出てきてしまうのではないかと思いますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-075"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、成果報告書の教育全般と、小中一貫校、１４５ページについてお聞きしたいと思います。ちょっと見解を先に述べします。こういうようなことでいいんでしょうか。本来なら、小学生、中学生も伸び伸びと外でやはり遊ばせてやるという環境が大事だと思うんですが、それについて何か工夫改善ができるでしょうか。このような状況に対してどのようなご見解を持っているか、お聞かせください。","respondent":"吉村小中一貫教育担当課長","answer":"通常、我々が見ていますと、例えば剣道とバレーがその３つのうちの２つを使って、残り１つはすまいるスクールが使うということで、私は実際に見ておりますので、そういった工夫をしているのかなというふうに思っております。","voiceIndex":165,"id":"exchange-076"},{"speaker":"須貝委員","kind":"質問","question":"教育環境というのは、やはりどこの場所にあっても子どもたちが伸び伸びと、運動なり、遊びなり、勉強なりできる、させられるような環境をつくっていくということがやはり大切なのではないでしょうか。その人たちはどうしていたかというと、近くの小学校、またはサッカーとか野球チームは、近くの中学校を借りて、子どもたちを健全育成していたわけですね。この辺についてちょっとご見解をお聞かせください。","respondent":"吉村小中一貫教育担当課長","answer":"日野学園の運動会の件ですが、１年生から９年生までが一緒に取り組んだということで、確かに９時から３時ということで運動会をとり行いました。運動会についてはさまざまありますけれども、確かに１年生の体力的な面というものがどうなのかということがございました。","voiceIndex":167,"id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"私は、１４５ページ、小中一貫教育と、１４７ページの校庭整備についてお伺いをします。最初に、ずっともう今まで出ている質問だと思いますけれども、私は初めて質問させてもらうわけですけれども、なぜ校庭を緑化できないのか教えてください。なぜ校庭を芝生にすることができないのではなくて困難なのかということの主たる理由をちょっと教えていただければと思います。","respondent":"市川庶務課長","answer":"ご案内のとおり、校庭につきましては、休み時間ごとに子どもたちが使うわけでして、それも四季折々すべてその使用に耐えなくてはいけない。こういった意味で、芝生の耐性の面で採用が困難であるです。","voiceIndex":170,"id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"それはちょっと自分自身でもそんなことかなとは思ったんですけれども、日々芝生も改良されているということで聞いておりますけれども、その改良された芝生でもなお耐えられないということの理由で今のご発言があったと思うんですけれども、全部芝生化ではなくて、今、校舎を改築した場合、または新しく小中一貫校をつくる場合に、屋上の緑化ということをやっているわけですけれども、校庭。","respondent":"市川庶務課長","answer":"この間進めてあります校舎の改築事業の中では、子どもたちがあまり踏まない部分、例えば校庭のコーナーの部分ですね、こういったところに積極的に芝生を採用しています。","voiceIndex":172,"id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に移らせていただきます。後に関しては、それが軌道に乗ったからということで整理整とんという項目は載っていないんですけれども、ふだん子どもたちが何気なくやっている清掃なんですけれども、これに関して教育的意義があると思いますけれども、どのような意義があるというふうにお考えになりますでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"清掃ですけれども、これは市民科の中にもありますけれども、要するに、基本的な生活習慣、自分たちが使ったところは自分たちで片づける、きれいにする、清潔にする、こういったことを子どものうちからしっかり身につけるという意味で。","voiceIndex":174,"id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"しかし、学校の中で、先ほどもいじめがあったりとか、子どもたちの他人を思いやる気持ちがあったりというような部分で、清掃は非常に課長がおっしゃったように大きなウエートを占めておりますが、何かないがしろとは言いませんが、それが当たり前のように通り過ぎているような気がしてならないんですけれども、そこのところはどういうふうにお考えですか。","respondent":"吉村小中一貫教育担当課長","answer":"その市民科というのは、４５分という授業の中だけのことではございませんので、その市民科で勉強したことが清掃の時間に生きているのかどうか、そういったことも教員が見ていくようにしています。","voiceIndex":176,"id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"パソコン、携帯電話等々のキーでやることに対しては非常に子どもたち、我々よりも上手になっておりますが、ことアナログの部分に関して、ほうきを使ったり、物を絞ったりということに関しては、非常に彼ら、彼女たちは不得手なことは言うに及びませんけれども、そこの部分で、アナログ対策として掃除を、先生方の裁量にはよるんでしょうけれども。","respondent":"吉村小中一貫教育担当課長","answer":"もう１つ、この清掃、今まさにぞうきんの絞り方であるとか、ほうきの使い方、こういった部分がなかなかできないということはあります。これは学校ではもちろん指導しますけれども、なかなか学校だけというものでは身につかない。","voiceIndex":178,"id":"exchange-082"},{"speaker":"大沢委員","kind":"提案","question":"その絞るというきずなが非常に大事になると思いますので、ぜひとも学校の先生方にご提案なりしていただきたいと思います。これ、もうちょっと先へ言うと、これ、是非がありますけれども、私はトイレの清掃ということで、もう１個踏み込んでちょっとお話しというか、お伺いしたいんですけれども、ふだん子どもたち、普通の廊下、教室はしております。","respondent":"吉村小中一貫教育担当課長","answer":"委員ご指摘のとおり、トイレの清掃については、子どもたちは今のところやっておりません。","voiceIndex":180,"id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"私は、私たちの年代、前に座っている理事者の方々もそういうご記憶はあると思いますけれども、なぜやめてしまったんですか。","respondent":"吉村小中一貫教育担当課長","answer":"小学校については、これは確かに学校の指導の問題で改善できることではあると思うんですけれども、品川でやってこなかった経緯というものは、やはり衛生上の問題として、子どもたち、小学生の子どもたちにやらせるにはいろいろ課題があるだろうということで。","voiceIndex":182,"id":"exchange-084"},{"speaker":"大沢委員","kind":"意見","question":"きちっとした衛生対策をとれば、子どもたち、ある程度の抵抗力、免疫力ができると思うんですけれども、そこまではやはりきちっと、病気が起こるのは困ったことですけれども、やはりそういうことというのは、人の嫌がるところをやるという部分で必要な情緒的な作業というか、情緒的な訓練と言ってはおかしいんですけれども、大事なことだと思うんですが、どのようにお考えになりますか。","respondent":"吉村小中一貫教育担当課長","answer":"ですから、これは、学校であるとか、指導改善の問題等々を改善することによって、小学生においてもトイレ掃除ができるですので、今後１つの課題として検討させていただきたいと思います。","voiceIndex":184,"id":"exchange-085"},{"speaker":"大沢委員","kind":"意見","question":"トイレの掃除、今、非常に自分の嫌なことをやる子どもたち、避けて通ろうということが非常に多い風潮にありますので、ぜひとも子ども、最初に社会生活、学校という社会に入って最初に自分が嫌なものに出くわして、それをどういうふうにぶち当たっていくかという最初の大事なハードルだと思いますので、ぜひともよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"プラン２１の関連事業について、学校選択制についてお伺いをさせていただきたいと思います。それで、お聞きしたいのは、学校選択制を６年間やってきてどうだったのか、区としてどう考えているのか、子どもたちにとって学力向上や人格形成の面でよくなっているのか、このことについてお聞かせください。","respondent":"吉村小中一貫教育担当課長","answer":"ですから、まず学校選択制の６年、７年の成果ということで言うと、まずもって管理職、まずは学校を変えるということにおける管理職の物の考え方、これが非常に抽象的なものから具体的に考えるようになった。","voiceIndex":188,"id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、今、この学校選択の問題については、マスコミの中でかなりたくさんのところで取り上げられていますけれども、『中央公論』の１１月号では、「ルポ・品川区教育改革の今親子の本音が招く、人気校への雪崩現象」ということで特集がされているんですけれども、私もこれも見せていただいて、本当に改めてこんなふうに品川区の小学校。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私の質問に答えていただきたいし、答弁は私の質問に対してだけ簡潔にお答えいただきたいと思います。それで、私が聞いた人気校と不人気校が固定化していることに対してどう思うかということに対しての肝心の答弁がありませんでしたのでお願いします。","respondent":"吉村小中一貫教育担当課長","answer":"大事なことは、そういった状況になったとき、ましてや数の上だけで学校を評価しているわけでは全くございませんけれども、そういった状況があったときに、その学校の努力と、学校だけの努力ではなかなかできないこと。","voiceIndex":193,"id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これが本音ですというのが人気校を選んでいる人はこういうふうなことを言っているというふうなことが書かれていまして、不人気校のほうは、わざわざ交通費を払ってまで人気校には通わせられない、経済的な余裕もないし云々というふうなことで書かれているんですけれども、こういうところで、所得格差が学校の格差につながっているんじゃないかと。","respondent":"吉村小中一貫教育担当課長","answer":"ですから、ここに書いてあること、出ていますけれども、私たちは私たちで保護者の方の意見をきちんと踏まえながら学校選択を続けているわけですので、ここに書いてあることでもって何かどうということではないというふうに我々は思っております。","voiceIndex":195,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは取材が品川の区民の声をとらえてやっているわけですから、実際に人気校、不人気校、こういうふうな形で数の問題で固定化しているということに対しては、それでは品川区はこの固定化に対しては、それはやむを得ないと、仕方がないことなんだと、そういうふうにとらえているのかというふうなことが１つ教えていただきたいのと、それともう１つ、これは『東洋経済』ですけれども。","respondent":"吉村小中一貫教育担当課長","answer":"認識しております。それから、重点支援校についてですけれども、重点支援校というのは、さまざまその重点支援校に指定する理由がさまざまあるんですけれども、一番大きいのは、やはり学校の経営力というふうに我々は考えております。","voiceIndex":197,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"学校の経営力というのがちょっと意味が全くよくわからないんですけれども、これは、じゃあ、選ばれなかった学校とか、生徒数が少なくなってしまった学校だとか、それから、そういういろいろな不登校だとか、学級崩壊というようなのが、どういう状況になっているかわからないですけれども、そういう困難を抱えるというふうなことではなくて。","respondent":"吉村小中一貫教育担当課長","answer":"学校の経営力といったもの、それは何かということなんですけれども、学校の経営力の中身として、１つは、校長先生のリーダーシップ、これは経営力の１つとして非常に大きいと思います。","voiceIndex":199,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"責任ということであれば、そのクラスの子どもや親に対してだけ知らせればいいことであって、それをなぜインターネットで公表するかというふうなところでは、不特定多数に品川区民に対して公表するというところでは、それは学校の選択の基準として考えてくださいということで公表するということではないんですか。そのことについてお聞かせください。","respondent":"吉村小中一貫教育担当課長、河野指導課長","answer":"最初の前半の部分ですけれども、私の説明の仕方が悪かったのかもしれません。地域の学校ということで、地域の人に広くその学校の実態を見てもらいたい、そういう気持ちを込めて公開をしているです。","voiceIndex":201,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、そういうふうなことであれば、やっぱり選ばれるために点数を上げていくという、そういうふうな教育になっていくと思うんですね。それはもう本当に日本がこれからモデルにしていこうとしているイギリスで、はっきりと失敗だというふうなことでイギリスのほうも方向転換しようとしている中身ですから、このことに対しては競争教育というふうなことで改めて見直しをしてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-094"},{"speaker":"木下委員","kind":"質問・要望","question":"だけど、国からの上からの改革というと、決められれば否応なく導入するような立場になってしまうのではないかなと思うんですけれども、その教育再生会議というのは、何か３つの分科会を設置して、約３カ月で中間報告を出して、１年後に最終報告を出すということで、通常は何か中間報告を出すまでに１年ぐらいかけて議論をして、それから出すらしいんですけれども。","respondent":"河野指導課長","answer":"外部評価、学校選択制等については、品川区でももう既に実施をしています。","voiceIndex":206,"id":"exchange-095"},{"speaker":"木下委員","kind":"質問","question":"教師は友達口調で子どもに接し、子どもの善悪を理解させず、あいまいな態度をとることが多いということらしいんですけれども、私もあるイベントで、小学生の子どもが、何々何々と言っていて、ふっと振り向くと先生に対して何々何々というような、ため口というんですか、そういうので、先生も怒らずにそれに接していたのを見て。","respondent":"河野指導課長","answer":"区内においても残念ながら学級が落ち着かない状態になるというようなことは毎年何件かずつ報告をいただいておるところですが、そのほとんどが多動性の子どもが複数いたり、あるいは新採の教員が初めて教壇に立って。","voiceIndex":208,"id":"exchange-096"},{"speaker":"木下委員","kind":"質問","question":"ですから、今、そういうなれ合い型の学級崩壊に対する対策として、学級集団アセスメント、Ｑ－Ｕですか、全児童生徒を対象にした心理テストを実施して学級崩壊の予防策についてアドバイスしてくれる、そういうのもあるというのも書いてあったんですが、こういうのを一応検討というか、導入ですとか、将来に対してご検討されたりなんかはしておられるのでしょうか。","respondent":"河野指導課長","answer":"現在のところ、教育委員会の中で具体的にそういうテストを導入するのかどうかということについては、正直申し上げて検討しておりませんが、今後もいろいろな課題が子どもたちの中に生じてきている実態もありますので、さまざまな視点で幅広く適するのか。","voiceIndex":210,"id":"exchange-097"},{"speaker":"木下委員","kind":"質問","question":"もう１点、経済活動体験学習経費、これはスチューデント・シティのことでよろしいのでしょうか。前回、予算特別委員会のときにスチューデント・シティとたしか書いてあったかなと思ったんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"本当にすばらしいですね。その歴史ですが、歴史、伝統、文化も深まるようなところもすごく感じたんですけれども、例えば、この平成１７年度で文化財の調査で、江戸の里神楽、品川間宮社中ですか、平成１７年度で調査をして、平成１８年度で実施をするという、そういったこともこの市民科の教科書なんかがかなり活用されていくんじゃないかなと思うんですが、その辺を教えてください。","respondent":"河野指導課長、吉村小中一貫教育担当課長","answer":"実施回数トータルといたしましては、２２１回開催しておりますが、参加者数のほうが延べ８３５名ということで、１回当たりの平均が約４名程度ということで。今の子どもたちにどういう部分が不足しているのか、その部分を補うためにはこういう学習が必要だということで、３年間かけて検討してきたものです。それから、公開授業です。","voiceIndex":214,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"学校公開ですとか、公開授業、保護者に限らず地域の方も来ていただくということで、本当にどんどん地域に開かれた学校で行ってほしいと思います。本当に母親から父親にもっと本当に学校をしっかり同じように見てよというような、一般論ですけれどもあると思うので、その辺のところ、状況がわかれば教えていただきたいと思います。","respondent":"河野指導課長","answer":"ただ、残念ながら、通常の保護者会あるいは授業参観等において、父親の参加が実態としてはまだまだ少ないというふうに考えておりますが、それぞれの学校では、少しでも多く父親の参加を増やすということで、例えば父親の会、おやじの会というような組織をつくって学校教育に参加。","voiceIndex":217,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"次へ行きますが、１４６ページのクラブ活動のところで、先ほども出ておりましたけれども、当然、児童生徒がクラブ活動、切磋琢磨をしてどんどん能力を向上していただきたいと思うんですけれども、それで、教職員でもスポーツ大会といいますか、スポーツの学校間、学校対抗ですか、教職員の学校対抗のスポーツ大会なのかよくわかりませんが、その辺はされていると思うんですけれども。","respondent":"河野指導課長","answer":"教職員のスポーツですが、品川区教職員互助会というのがございまして、その取り組みの中で、バレーボール、あるいはバドミントン、テニス、バスケットボールというようなスポーツ大会といいますか、対抗試合みたいなことはやっております。","voiceIndex":219,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、スポーツのところで、今度、運動会のことをちょっと聞かせていただきますが、運動会で、組み体操とかをする場合は、はだしとかになって、そういう競技をされると思うんですけれども、ふだんの徒競走ですとか、数校しか私も見ていないんですけれども、上履きで走っている傾向が多いと思うんですけれども、かなり走っているときに上履きが脱げてしまうようなケースをかなり見かけるんですが、できれば。","respondent":"河野指導課長","answer":"ただ、これは親御さんの考え方というのもあるのかもしれませんが、子どもがどんどん足が大きくなっていってしまうということもありますので、実際のサイズよりもやや大きめのものを買い与えるというようなこともありますので、運動会等については。","voiceIndex":221,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問","question":"それと、その取り組みについてどう考えるのか、スポレク等も含めて、その辺のところを教えてください。","respondent":"富田生涯学習課長","answer":"特に八潮のスポレクでは、フットサルのそういった競技の大会等が行われて、スポレクの内部でという話を聞いております。","voiceIndex":223,"id":"exchange-103"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから３点お尋ねをします。以上３点、時間の範囲の中でお尋ねをさせていただきたいと思います。１４４ページの教育指導費でいいんだろうと思うんですが、今日も何人かの方からお話が出ておりましたけれども、いじめの件につきまして、ダブる点があるかもしれませんが、質問を用意いたしましたので進めさせていただきたいと思います。","respondent":"河野指導課長","answer":"報告の中身ですが、いつごろから、どのようないじめを受けていたのか、それに対して学校としてどう対応して、どういう結果になったのか、その主に４点ですが報告を出していただいているです。","voiceIndex":227,"id":"exchange-104"},{"speaker":"堺委員","kind":"確認","question":"こういう中にあって、学校と、あるいは教育委員会が守るべきこととして、いじめの事実を隠すな、こういうこともこの中で指摘されておりますけれども、したがって、いろいろな報告の中身についても、今、ご報告をいただきましたけれども、あるこの会議に出た方は、市町村からの件数だけを聞くのではなくて、その中身や事実を精査する作業が必要なんだということが言われておりますから。","respondent":"河野指導課長","answer":"最終的にその件がいじめなのかどうかということは、これは後々指導が済んでから分析しても間に合うということで、私どもはそういう対応をさせていただいているところです。","voiceIndex":229,"id":"exchange-105"},{"speaker":"堺委員","kind":"質問","question":"今も課長からお話がございましたように、子どもの安全の確保とおっしゃっていただいた。ですから、こういうことについては、間を置かずに即対処するということが子どもの安全を守るということにつながってくるんだということを改めて理解ができたわけです。こういうこともその記者会見の中で指摘をしておりましたけれども、この辺、もう１回改めてご所見を伺っておきたいと思います。","respondent":"河野指導課長","answer":"いじめですが、本当に今回の９月の福岡の事件といい、それから１年前に起こった北海道での自殺の件といい、子どもたちにとってこういうことがあってはならないというふうに私どもも改めて認識をしています。","voiceIndex":231,"id":"exchange-106"},{"speaker":"堺委員","kind":"質問","question":"大変痛ましい事件です。こういうことが品川区に起きないでほしいと願っております。さっき２つの例にかかわったということで申し上げましたけれども、非常に担任の先生の対応というんでしょうか、非常に大事だなということを感じたわけです。そういうことも含めまして、教育長に、このいじめ問題に対する品川区の取り組みの姿勢について、決意のほどをちょっと伺っておきたいと思うんです。","respondent":"若月教育長","answer":"今後もこうしたことを教員には訴えていきたいと、こんなふうに考えております。","voiceIndex":233,"id":"exchange-107"},{"speaker":"堺委員","kind":"提案","question":"平成１６年の第４回定例会の際に、私どもの武内委員が、１４歳の職業体験ということで、いわゆる引きこもりやニートの予防対策として、ぜひ導入をしていただきたいという提案をしておりますが、この件について、実は今回の国会におきましても、私どもの代表になりました太田代表が、若者の雇用問題という件について、第１は、フリーター２００万人、ニート６０万人とも言われている若年層の雇用問題だと。","respondent":"河野指導課長","answer":"職場体験を実施するに当たって、現場として今一番困っているのは、なかなか中学生を受け入れてくれる、そういう企業、商店等がないということが悩みですので、こちらのほうもあわせて学校と教育委員会とが協力しながら。","voiceIndex":235,"id":"exchange-108"},{"speaker":"堺委員","kind":"質問","question":"今のご報告によりますと、各学校によっていろいろな取り組みに差があるように聞こえたんですが、これは学校の自主性というんですか、独自性に任せているという理解なんですか。この件については教育委員会はタッチしていないんだと、その辺はどうなんでしょうか。","respondent":"河野指導課長","answer":"職場体験については、実施規模等については、それぞれの学校が教育課程を編成する前にその中の位置づけによって日数というものが変わってまいりますので、そういう意味においては学校の独自性ということになりますが、この職場体験のほかに、例えば中学校で言うと。","voiceIndex":237,"id":"exchange-109"},{"speaker":"堺委員","kind":"質問・要望","question":"そういうことがいわゆる将来のニートとかフリーターを予防するということにもつながっていくだろうと、こういう意味で、ぜひ品川区としても、教育委員会としても積極的に取り組んでいただきたい、こう思うわけです。この件について、速やかに全校で実施していただきたい、こう思うんですが、この辺についてはいかがでしょうか。","respondent":"工藤品川図書館長","answer":"今後の展開です。現在、２１校を整備しています。残りの学校に関しましては順次拡大したいというふうに思っております。","voiceIndex":239,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"私からは、何回も議論がありました１４５ページ、学力定着度調査について、１４６ページ、学校ＩＴ化について質問いたします。つまりＰＤＣＡサイクルと聞いていますけど、そういうところまで完結することで、はじめて公教育の向上に結びつけていくことが目的であると思うんですが、いかがでしょうか、確認をお願いいたします。","respondent":"河野指導課長","answer":"ただいま委員がおっしゃるとおりです。","voiceIndex":242,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしたら今度は、具体的にそういう得られた改善点、つまり各学校が、例えば小学校で算数が不得意であるとかが出てくるわけでありまして、問題は、ではそこを具体的にどういうふうに改善する計画を立てて、それを実行して、学力がアップしたかという実例があると思うんですけれども、そのことを二、三教えていただきたいのと、それから、私も平成１５年の海外調査に参加をしまして。","respondent":"河野指導課長","answer":"年次を限って対処する方針はですが、今年度、小中一貫教育全面展開ということの中で、ステップアップ学習というのを入れてあります。","voiceIndex":244,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"もう少し踏み込んで確認したいのが、非常に貴重なデータだと思いますね、この学力定着度調査で得られたデータというのは。ですから、その小中一貫教育の中での同じ意味で、指導方法の研究とか、教材開発等は行われてきたんでしょうか、お聞かせください。","respondent":"吉村小中一貫教育担当課長","answer":"その検討委員会の中にかけて、算数・数学の指導法についてどうしたらいいのかというのは、そのカリキュラム検討委員会の中で検討していくです。","voiceIndex":246,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問","question":"先ほど本多委員の質問の中で、市民科というすばらしい教科書をつくってくださったと評価がありましたね。それだけの力があるんです、皆様方には。ですから、この定着度調査のデータをもとに、そこまで具体的な授業方法とか、教材の展示とか指導法まで展開していきませんと、大きな意味でこの目的が達成されないと思いますので、もう少しこのことについての答弁をいただければと思います。","respondent":"吉村小中一貫教育担当課長","answer":"１つは、先ほどカリキュラム検討委員会という話をしたんですが、今現在、算数・数学については副教科書というものを品川区でつくっているわけですけれども、例えばこの分数の足し算・引き算というものについて、これまでの過去の学力定着度調査の状況を見て分析をして。","voiceIndex":248,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"学校ＩＴ化のほうですけど、これは既に品川区の学校職員すべてに１人１台のパソコンは配付済みであります。ですから、そのことについてはやっぱり大切なことは、教員がこのパソコンを最大限利用して、現行の学校経営とか授業の中で活用していくというところまで話を進めていきませんと、この配付した目的は達成されないと思いますので、そのことについての答弁をお願いいたします。","respondent":"古里学務課長","answer":"これも１人１台パソコンを配備したことにより、日常的にこれを使用するということから、スキルが格段に上がっていると思います。今後、これをさらに活用することよって、さまざまなソフトを駆使できるような個人の能力、ツールを身につけていきたいと考えています。","voiceIndex":250,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"プロジェクターですか。ですから、私たち自民党が何回も言っていますのは、こういうハード整備は進めてください。そのことについて再度答弁をお願いしたいのと、それから、これから学校整備、小中一貫校がつくられていく中で、そういう電子黒板といいましょうか、そういうＩＴ化に対応するための教室の整備についてはどう取り組んでいくのかということをお聞かせください。お願いいたします。","respondent":"古里学務課長","answer":"もちろんＩＴはあくまでも道具ですから、教員の授業力ということを生かすためのＩＴです。それと今後の展開ですけれども、改築校、小中一貫校の展開にあわせて、そのような各教室でＩＴ化の展開ができるような機器整備等は進めてまいりたいと考えています。","voiceIndex":252,"id":"exchange-116"},{"speaker":"伊藤委員","kind":"質問","question":"一言で特色ある学校教育といっても、いろいろな切り口があって千差万別ですけれども、せっかくこのＩＴ化については相当、品川区としてはすべての教員がパソコンを持っているし、それから施設整備も進んでいるわけですから、十分リンクできる仕組みはできているわけですから、ぜひそういうことについては検討して進めていってくださいということをお願いして終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"１４４ページの教育指導費に入るんでしょうか、スクールカウンセラーについてと、それから総合体育館について、すまいるスクールについて、時間があれば安全管理についてお尋ねします。そこで巡回相談が本格実施になっているわけですけれども、それを補完する意味でスクールカウンセラーの役割もあるんだというお話をちょっといただいたんですが、これはそうなんでしょうか。","respondent":"河野指導課長","answer":"学校に配置されておりますスクールカウンセラーが、いわゆる特別支援教育の専門家による巡回相談の補完をするものかどうかというお尋ねですが、発達障害を持つ子ども、いわゆる特別支援を要する子どもたちに一番学校として配慮しなければならないのは。","voiceIndex":256,"id":"exchange-118"},{"speaker":"西本委員","kind":"質問","question":"ですから、今のお答えになってしまうと、発達障害等々の特別支援教育に絡んでという形に限定されたような形を私は受けてしまうんですが、むしろそういう形であれば、先ほども答弁がありましたが、介助員の制度もいろいろ考えようというところがありますので、むしろ巡回相談等に対して介助員のあり方によってそちらのほうを発展させるべきであって、スクールカウンセラーというのはもうちょっと広い。","respondent":"河野指導課長","answer":"スクールカウンセラーの本来的な役割、今、特別支援教育との絡みということでご紹介させていただきました。","voiceIndex":258,"id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"ありがとうございました。安心いたしました。そういう形で発展させていただきたいと思います。今年から小学校のほうにはスクールカウンセラーを整備してきたというお話を聞いたんですが、スクールカウンセラーの相談室を設置している割合というのはどのくらいあるんでしょうか。","respondent":"河野指導課長","answer":"現在、相談室については準備、整備をしています。特に来年度から本格実施される特別支援教育に関連して、いわゆる特別支援教室ということで、特に個別対応をそれぞれの学校の中で行う場合には、通常教室とは違う個室が必要になってまいります。","voiceIndex":260,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。今、幾つかの学校では相談室を何とかやりくりをして捻出してつくっているところもあります。今、半分は扉を外してしまって、中に靴が入っているのが見えるようにしているような状況もあるんですが、いろいろ改善されているとお話は聞いているんですが、今、実態的にはどういう形になっているんでしょうか。","respondent":"富田生涯学習課長","answer":"音響につきまして残響調査も実施をいたしまして、必要な反響板をつける等の作業は、これから年度内には、できれば年内に終えたいと思いますが、工事をしていく予定にしております。","voiceIndex":262,"id":"exchange-121"},{"speaker":"西本委員","kind":"確認","question":"いろいろと改善をしていただいているというところで安心いたしましたが、心配するのが、来年度、開校になります大井地区の一貫校ですね。そこのところも区民の方たちが使えるように開放するという形で、体育館、プール等を建設しているところがあります。それをどのように生かしていただけるのか、確認はとっているのでしょうか。","respondent":"宍戸施設担当課長","answer":"大井一貫校につきましては現在、工事を進めているところですが、日野学園の設計あるいは工事中に際しましての使い勝手等の詰めの甘さというか、そういった点につきましても、あるいは工事完了してからの準備期間も短かったということもありますので、その辺の反省点を踏まえて今。","voiceIndex":264,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。デザイン的に非常に見た目がすてきだなと思う面、使い勝手がどうなのかといったときに、後で変えなきゃいけないというようなことにならないように、これからいろいろなところを改築して実際に使われているわけですから、その反省点はほかの改築している学校にぜひ生かしていただきたいと考えています。次に、すまいるスクールについてお尋ねいたします。","respondent":"市川庶務課長","answer":"それと、ご質問の中にもありました業務委託で現地にいるスタッフの評価、まず一時的な評価は私どもの指導員がきちんとできるような、まずそういう指導員の資質も養成していかなくちゃいけないと考えているところです。","voiceIndex":266,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"学童保育ではないですけれども、それを担うような事業になっておりますので、それにおいてはどういうニーズがあるのか、実際利用している子どもたち、親たちがどういう評価で見ているのか、期待しているのか、改善を求めているのか、それから、子どもたちの実態が今後、放課後事業をしていく中で、どういうふうにすまいるスクールを持っていっていいのかということは、そろそろ検証していく。","respondent":"市川庶務課長","answer":"ただ私どもは、すまいるスクールの事業の進め方の中で、勉強とスポーツ、遊びという柱を立てておりますけれども、こういったそれぞれのメニューは求められるから提供するというわけではございませんで、私どもが子どもたちの成長なり発達に応じて。","voiceIndex":268,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"ぜひとも今後の展開をしていく上では、じゃ、現時点はどうなのかというところ、それから、親に対しての問いかけも必要な部分はありますけれども、子どもにとってどうなのか。意外と保護者の感じ方と子どもたちの感じ方って違うところがあると思うんですね。そこは見ていかないと、親の要求はどんどん広がっていくと思うんですね。どういう方法で調査をされていくのかなというところはいかがでしょうか。","respondent":"市川庶務課長","answer":"だとすると親のニーズの受けとめ方ということになりますが、この辺については、この事業の現場でもあります学校サイドの意見もよく聞いて調整しながら、先ほど来申し上げているニーズの把握、どのような方向がよろしいかということを鋭意検討していきたいと思ってあります。","voiceIndex":270,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ発展のためによろしくお願いいたします。最後に簡単に安全管理について。昨日もしつこく通学路を聞きました。これをぜひ全校に勧めていただきたいと思います。学校側から保護者の方たち、ＰＴＡの方たちと一緒に通学路の見直しとか、近隣の安全管理についての議論を進めていきたいという希望がありますが、その件に関してご意見をお聞きして終わりたいと思います。","respondent":"河野指導課長","answer":"通学路につきましては、それぞれの学校がＰＴＡの皆さんとも相談の上、子どもたちに対して一番安全な道、危険のないところということで毎年考えて設定していると伺っております。","voiceIndex":272,"id":"exchange-126"},{"speaker":"土井委員","kind":"質問・要望","question":"最初に職員給与費の関係でお伺いしているのはなぜかということですか、この給与費の中の給与をお支払いしているのは、給食の関係とか、用務の関係とか、事務の関係の皆さんの部分だろうと思うんですね、ここに載っかっているのは。そうすると、これがこれからどう変わっていくのかという比較をしないと、決算の結果が見えないものですから、ちょっと伺わせていただきたいということであります。","respondent":"市川庶務課長、日下部企画財政課長、古里学務課長","answer":"成果報告書の１４６ページの職員給与費の給食調理の職員の関係ですけれども、ここにお示ししています小学校２２５人、中学校１０２人。教員の給与の表記の関係ですけれども、あくまでもこれは東京都の予算ということでありますので、その辺の掲載の仕方は難しい面がありますけれども。その後、自分が該当しそうだという方が申請をなさってまいります。その申請を一定の収入基準で審査をします。","voiceIndex":275,"id":"exchange-127"},{"speaker":"土井委員","kind":"質問・要望","question":"それで確認させてください。では、次の質問に入ります。それがすなわちこれからの建設費等の内容にかかわってくると思うんですが、前にお話ししたときは、まだそれはちょっといろいろというような感じだったんですが、あれから何も進展していないのかな、何か進展しているんじゃないかなという感じがするものですから、ちょっとお聞かせをいただきたいというのが１点。もう１点は幼保のところです。","respondent":"高橋幼保一元担当課長、市川庶務課長","answer":"幼保一元について、国のほうが一元化をつくると言っている中で、どのような管轄になるかですが、国のほうは厚生労働省、文部科学省を合わせた形の幼保連携室というところで、この認定子ども園についての受付を一体化で実施する。現在、平成１０年度に行った耐震診断を改めて今年度、フォローの診断として行いまして、今後、ハード的に耐震補強が必要とされる事業量の総量をまず把握することが先決問題ということで。","voiceIndex":279,"id":"exchange-128"},{"speaker":"土井委員","kind":"質問・要望","question":"うちのほうも連携なのか、窓口だけは１つにしたんだけれども、いずれにしろ保育園、幼稚園、新しい考えのも、これをどっちの方向に向いていくのか、そろそろきちんと整理をしないと、３本立てで３方向を向いて走り出しているという感じにならないようにしなければいけないと思うものですから、そこできちっと議論をしていただいて。","respondent":"高橋幼保一元担当課長、市川庶務課長","answer":"公立保育園におきましては、今後の様子を見るですけれども、国が出されている法律の中で、今、懸念している、とどまっているという部分につきましては、品川区には幼稚園条例がございまして。ただその具体的な検討を始めるにあたりましては、今後、近々予想されるハード事業の計画事業量の総量を把握した上で、６校構想、校舎改築といった事業を進めていく中で、まさにそれぞれの地域の事情、実情をよく伺いながら。","voiceIndex":282,"id":"exchange-129"},{"speaker":"土井委員","kind":"質問・要望","question":"もう時間がありませんから。ぜひやっていただきたいことと、地域の事情というと、いつもＰＴＡの皆さんなどを含めて、私の学校がなくなっちゃうという反対運動が必ず起こるんですけれども、千代田区だってそういう例で大変な目に遭っているわけですから、でもやらなきゃいかんことなんです。ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-130"},{"speaker":"林（宏）委員","kind":"質問","question":"広く浅くいろいろお聞きしたいので、端的に聞きますので、簡潔に答えてください。１４４ページの研修のところで、下から中堅教員研修５人というのは、対象がどういう先生なのか、端的に。園歌ができた。小学校から２けた九九をやる。１つの区切りが来たと考えるんですけど、そもそも品川で教育改革をスタートさせたときの考え方と現在で違いがあるのか、あるならその違いを教えてください。","respondent":"河野指導課長、吉村小中一貫教育担当課長","answer":"中堅教員研修ですが、平成１７年度５名が受講しております。産業能力大学の公開セミナーのほうに派遣という形で受講させております。それぞれの学校の中核をなす教員ということで、主幹であるとか副校長格が相当しております。日野学園の歌についてですけれども、公募については私どもは確認はしておりません。学校の検討の中で出た話かもしれません。私どもとしては確認しておりません。","voiceIndex":287,"id":"exchange-131"},{"speaker":"林（宏）委員","kind":"質問","question":"あるいは私立の幼稚園のお子さんも、多くが区立の小学校に上がる。そういうことによって上がってくる子どもたちも整えられた環境、あるいは迎える教師にとっても、どういうお子さんが来るのかというのが把握できているということは必要だろうと思うんだけど、そういう意味で、もう１度お答えください。だから、ぜひこれからも教育長の気合いを先生方に伝えてほしいなと思います。この意味を教えてくれますか。","respondent":"河野指導課長、吉村小中一貫教育担当課長","answer":"私のほうからは幼稚園、保育園と小学校の連携のことについてお答えします。平成１７年度に、すべての小学校が学区内の幼稚園、保育園と就学時連絡会という名称で情報交換等を行っております。教科によっては７年生まで一括して入れたものもありますけれども、そういうふうに順次移行しながら、３年間から４年間の移行をかけて、この小中一貫教育のカリキュラムの全校実施に入っていきますという意味での段階のことです。","voiceIndex":290,"id":"exchange-132"},{"speaker":"林（宏）委員","kind":"意見","question":"すると、今の６年生、それから中学生というか、７、８、９年生は、市民科や英語を除くと、従来の指導要領というか、教科書というか、そういうもとで勉強していると把握しておけばいいんですね。後で答えてください。もう１つ、各学校の実態や特色に合わせ、１つの中学校と１つの小学校、これは一体型です。それから、１つの中学校と複数の小学校などがありますという、これは小中一貫教育の形という。","respondent":"吉村小中一貫教育担当課長","answer":"７年生以下については、先ほど申し上げましたように、教科によってその段階を踏んで移行しているです。それから、２点目の小中連携の話ですけれども、確かに中学校１校と小学校２校が連携をしているということはあります。","voiceIndex":293,"id":"exchange-133"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そう願いたいし、そうあるべきだと思います。ただ、例えばスポーツ系と言っていいのかな。そういう学校に行っている。この教育改革というもとで言うと、いつも僕言うんですけれども、義務教育も生涯学習の中の９年間というとらえ方をすると、この改革は生涯学習の分野でというのかな、どこに見える、あるいはどこに意気込みを職員の方々は見出しているのか、その辺を聞かせてください。","respondent":"吉村小中一貫教育担当課長","answer":"小学校の５年生あるいは６年生段階にどういう進路指導をするのか。これは学校選択も絡めて、それから、先ほどの小中連携ということも始まっているわけですから、その中でこの進路指導でもって、先ほど委員がおっしゃったようなことについては対応してまいりたいと考えています。","voiceIndex":295,"id":"exchange-134"},{"speaker":"林（宏）委員","kind":"意見","question":"それは一番最初に聞いた、このプランを立ち上げスタートしたときから変わっていないというお話だった。もう１つ、いつも教育長がおっしゃっている。そういうところも改革をしていくべきだと僕は思う。よく言う学校と地域と一緒に子どもを育てる、見守るという中では、生涯学習というところにもしっかりと改革を入れていかないと、完成していかないんだろうと思いますので、お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":297,"id":"exchange-135"},{"speaker":"三上委員","kind":"質問・要望","question":"図書館の経費について。ここのところへ来て、ある方たちから、最近、８・３運動というのが少し意識が低下してきているんじゃないかとおっしゃる方がいらっしゃいまして、そういった点で、現場としてはその８・３運動等についてどういうふうに今、受けとめていらっしゃるのか、そしてまた、どういうふうにこの運動について支援をしていこうとしているのか、お伺いしたいと思います。","respondent":"若月教育長、市川庶務課長、富田生涯学習課長、工藤品川図書館長","answer":"ＴＰＯをわきまえ、きちんとした社会人としての服装を本来するべきであると考えております。成果報告書の１４４ページの被服貸与費の内容ですけれども、貸与の対象は栄養士、用務職員、調理職員の３者です。８・３運動についですが、昨年度末、今年の初めごろは防災無線を使用してですとか、そういった活動、支援をしてまいったところですけれども。こちらのほうの代金というのが、本を買った後、装備するわけですけれども、１冊当たり３０円から４０円ということになってあります。","voiceIndex":299,"id":"exchange-136"},{"speaker":"三上委員","kind":"質問","question":"教育長、ＴＰＯに合った立場でということは当然のことだなと思って、私も受けとめました。子どもに示す服装ということでありまして、そうしますと、この被服貸与ということについては、一般の教員に対してというのは何もないんでしょうか。そこのところを先にちょっと教えてください。","respondent":"市川庶務課長","answer":"これまで教員にはトレーニングウエアあるいはウインドブレーカーといったものを定期的に貸与してございましたけれども、私ども区の職員の被服貸与の見直しに合わせまして検討をして、その結果、廃止をしたという経緯があります。","voiceIndex":304,"id":"exchange-137"},{"speaker":"三上委員","kind":"確認","question":"こういったことについての指導徹底ということはどうされているのか、お伺いしたいと思います。ですから、こういった表装の部分についても、それはある意味ではボランティアの方に力を借りながらやるとかということもあるかわかりませんけれども、すべてどんな本にしてもこういう表装をするというのは、大事にするという観点からはいいかわかりませんけれども、本の内容によってはそこまで必要なのかどうか。","respondent":"河野指導課長、富田生涯学習課長、工藤品川図書館長","answer":"ただ残念ながら、外部評価者のさまざまな意見の中に、中には教員として服装はどうなのかというご意見をいただいているということもありますので。８・３運動は品川区から発信いたしまして、日本おやじの会でも取り上げられ、全国的な運動になっているところですが。ボランティアの活用という部分も、他自治体でもそのようなボランティアがいるという話も聞いておりますので。","voiceIndex":306,"id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"ボランティアの活動について、学校図書なんかは比較的協力をいただいている部分がありますよね。ですから、そういったところについてのいろいろな情報をいただきながら、そういった活用をする中で、冊数を増やすということのほうが私は大事なことだなと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-139"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１４５ページ、小中一貫校に関して質問します。最初に、午前中もちょっと論議になりましたけれども、今週、八潮南中が入学ゼロになり、２年生と３年生しかいない異常事態となりましたけれども、その原因はどこにあったと考えているか、お答え願いたいと思います。","respondent":"古里学務課長","answer":"当然学校選択制という要素もありますけれども、八潮団地の中の学校におけるさまざまな現象につきましては、団地特有の現象と考えています。","voiceIndex":312,"id":"exchange-140"},{"speaker":"沢田委員","kind":"質問","question":"お尋ねしますけれども、住民基本台帳上、中学１年生になる者は何名いたんでしょうか。それから、そのいた人数がどういう学校の選択をしたんでしょうか。","respondent":"古里学務課長","answer":"平成１８年度の住基上の中学校の八潮全体の人数は１０３名です。このうち４３名が八潮地区の学校に進学をし、それ以外の生徒につきましては、他地区あるいは私立へ進学したと把握しています。","voiceIndex":314,"id":"exchange-141"},{"speaker":"沢田委員","kind":"質問","question":"確かに八潮の子どもの減少状況というのはかなり大変だというのはわかりますけど、３４名いた子どもさんがゼロになっちゃったと。私立に２割から３割ぐらい行ったにしても、二十何名かは本来ならそこに残るはずだった。これが外に行っちゃったというのは、自動的に行ったんでしょうか。","respondent":"古里学務課長","answer":"自動的にという表現がどういうことを指すのかわかりませんけれども、学校選択をするということの結果、この３４名の通学区域にいる児童・生徒が、ほかの学校のほうを選択した結果、そういうことになったと理解しています。","voiceIndex":320,"id":"exchange-142"},{"speaker":"沢田委員","kind":"質問・要望","question":"「小中一貫校が近隣の小学校の統廃合に道を開くものではないかとのお尋ねですが、これにつきましても、これまで繰り返して申し上げておりますように、プラン２１の推進にあたりましては、学校の統廃合を前提としているものではございません」。だけど、結果は伝統ある学校が５つもなくなっちゃう。これまでの思いとねらいと違う方向に走ったことに対して、教育長の感想を聞かせていただきたい。","respondent":"長田教育次長","answer":"学校選択制につきましては、統廃合を目的としたものではないということ、それから、少数であっても、その学校を選んだ児童・生徒がいる限り、教育委員会は精いっぱいの支援をしていくと、こういうスタンスで進めてきたところです。","voiceIndex":322,"id":"exchange-143"},{"speaker":"沢田委員","kind":"質問","question":"母校がなくなっちゃうわけですから、いろいろな意見が出されています。そういう中で、多数の住民が賛成して一貫校１校に絞ってくれと言ったんですけど、問題はなぜ多数の地域の人たちやＰＴＡの関係の人たちが１校に絞ってくれと言ったか、その気持ちをどう理解しているかというのが大事だと思いますけれども、もう一度そこのところを聞かせてほしいと思います。","respondent":"古里学務課長","answer":"八潮の問題につきましては、八潮南中が希望申請の結果ゼロになったという１１月、１２月の段階から、品川区教育委員会として地域のＰＴＡの会長の皆さん、学校関係者の皆さん、それから、地域の皆さんと一緒に話し合いを進めてまいりました。","voiceIndex":324,"id":"exchange-144"},{"speaker":"沢田委員","kind":"質問","question":"学校選択で３４名いた子どもが、近隣の学校にみんな選択していなくなっちゃう。それを多数の父母が望んでいるからなんていう言い方でやるのは極めて不誠実と言わなければならないと思います。そうすると、第２、第３の八潮の状況があらわれないとも限らないけれども、区としてはそれをやむなしとするのか、統廃合とならないようにとにかく全力を尽くすという立場なのか、どちらなんでしょうか。","respondent":"長田教育次長","answer":"これから日野学園に続きまして大井の一貫校も開設をしますし、一貫校６校構想については、一貫教育を進める上での重要な施設になりますので、これは計画的に進めさせていただきたいと考えています。","voiceIndex":326,"id":"exchange-145"},{"speaker":"沢田委員","kind":"意見","question":"何をどう判断するのか。要するに統廃合はやむなしと、それは住民の声といろいろな反応に任せるのだという立場なのか、統廃合しないように区教委としては、一貫校を進めるというのはわかりましたよ。それを進めて統廃合になるような、八潮のような状況を繰り返さないような立場なのか、どっちなのかを聞いているんです。","respondent":"長田教育次長","answer":"先ほども申し上げましたけれども、私どもは小規模校であっても、そこを希望する児童・生徒がいる限りは、最大限の支援をしていくということで、決して選択制によって統廃合を積極的にしていこうという意思は全く持ってございません。","voiceIndex":328,"id":"exchange-146"},{"speaker":"沢田委員","kind":"質問","question":"７月２５日の文教委員会で、私は八潮の事態を内陸部に広げてはならないと。そういう立場で統廃合をこれ以上進めないためにどう思うのかと聞いたらば、次長が答えたのは、こういった傾向が内陸部のほうでも当然起こるだろうと思いますと答弁している。議事録がここにあります。どっちが本当なんでしょうか。","respondent":"長田教育次長","answer":"繰り返しになりますけれども、最大限支援をしていきます。それでも選択をしていただく方がいなくなった場合ですとか、地域の中で一緒にするべきだということがあれば、それは私ども真摯に耳を貸して検討しなければいけない内容だろうと思ってあります。","voiceIndex":330,"id":"exchange-147"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は１００年の歴史を持つ日野中学校が、３,５００の署名を集めて残してほしい。１校火を消しました。８年前には３６人いたのが徐々に減った。対立候補が得た票にはどんな思いが込められていたのか、濱野氏に区民一人ひとりの声に耳を傾け、一連の改革の功罪を検証しながら進めていく姿勢を求めたい。その点について新区長の濱野区長の見解をお尋ねしたいと思いますが、いかがでしょうか。","respondent":"濱野区長","answer":"小中一貫校は、冒頭の際にも申し上げましたように、公の教育に対する信頼の回復あるいは期待への対応だと考えておりますので、この計画を傾けるとか、やめるとか、おくらせるとか、そういう考え方はありません。","voiceIndex":332,"id":"exchange-148"},{"speaker":"沢田委員","kind":"意見","question":"学校の数と子どもの数のアンバランスがある。ある程度統廃合やむなしということがよく言われますけど、私は違うと思う。今、世界の流れというのは、２０人学級、２５人学級が滔々たる流れですよ。子どもの数が減った今こそ、学校のクラスもあるし、少人数学校にして、ＯＥＣＤなんかで、フィンランドなんか１６、１７人ですよ。私は競争教育じゃなくて、改めて学び合いの教育と少人数の教育、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":334,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問","question":"１４５ページ、プラン２１に関連しまして質問します。３校ともそうです。そのメンバーがそういった行動をしたということを、選択制が地域と密着していないということはないと思うんですが、そのあたりいかがですか。もう１つ伺います。その斎場はおかしいよ、建設反対だよ。これは地域がばらばらだったらそんな署名は来ないと思うんですが、このあたりの経過につきまして、教育委員会はいかがでしょうか。","respondent":"河野指導課長","answer":"品川区教育委員会として進めてまいりましたプラン２１に対して、ご評価の言葉をいただきました。どうもありがとうあります。","voiceIndex":336,"id":"exchange-150"},{"speaker":"須藤委員","kind":"質問・要望","question":"Ａクラスの人とＤクラスの人が一緒になって、そこでクラスをつくってくるという話になってこようかと思うので、私も柔道というのを教えているんですけれども、我々が教えているときに、できる子が、先生、ここがこうだよ、この子こういうのがわからないんだよというようなことをポンと言ってくれると、我々専門家の見ている目じゃない目で子どもが指導してくれるということがあるので。","respondent":"吉村小中一貫教育担当課長","answer":"学び合いは非常に重要なことです。そこは小中一貫教育の中でも推進していきたいと考えております。","voiceIndex":338,"id":"exchange-151"},{"speaker":"須藤委員","kind":"提案","question":"そうすると、こういった体験学習をいろいろやってくるけど、その前にボランティアで町会の人とか、商店街とか、みんなで一斉に清掃をやるというような形で、そのあたりから体を動かして、清掃なんかをやると、自分らも今度こんなところにごみを捨てるのはよそうという思いが必ず出てくると思うので、そういったことを、例えば５月３０日はゴミゼロデーというので、区商連でよくやっていたんですけれども。","respondent":"吉村小中一貫教育担当課長","answer":"さらにはほかの学校のＰＴＡにも広げていくといったような活動が、この夏にあったということをつかんでおります。こういったことがこれからは非常に重要になるのかなと考えています。","voiceIndex":340,"id":"exchange-152"},{"speaker":"須藤委員","kind":"質問","question":"考える力とか、いろいろやっていただいていると思います。雑誌等に書いてあったからこれはどうだというような、一読しただけでそれを丸飲みしてどうのこうのというんじゃなくて、その裏に何があるんだということをきちんとわかるような子どもに育ててもらいたいと思うんですが、その辺の教育はいかがでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"子どもたちに必要なのは、１つの事件、１つの事象が起きたときに、新聞によっては書き方が違う。今、子どもたちが必要なのは、何か１つのことをもってすべてだと考えるのではなくて、世の中にはいろいろな見方がある。","voiceIndex":342,"id":"exchange-153"},{"speaker":"須藤委員","kind":"質問","question":"前に聞いたんだけれども、学力定着度調査のときに、２こぶ現象、３こぶ現象という成績の山が２つほどになるよという話が聞かれるんだけれども、品川区ではいかがでしょうか。","respondent":"河野指導課長","answer":"品川区で行っている学力定着度調査の結果なんですが、それぞれの得点層で出しているのではなくて、それぞれの学校の子どもたちの定着度が何％かという出し方をしていますので、今の調査結果からは、二極化が起こっているのかどうかということについては、申しわけございませんが。","voiceIndex":344,"id":"exchange-154"},{"speaker":"須藤委員","kind":"質問","question":"先ほど来、いろいろありますけれども、改革をしてくるということは、いろいろな声が出てくる。それから、１５０ページの学校保健費のところで、災害共済掛金というのがあるんですけれども、これは健康会の費用なのか、ちょっと教えてください。","respondent":"古里学務課長","answer":"災害共済掛金につきましては、日本スポーツ振興センターの学校の事故等のときに給付するための共済の仕組みです。そのための費用を負担しているものです。","voiceIndex":346,"id":"exchange-155"},{"speaker":"須藤委員","kind":"質問","question":"これはその学校で事故の精算をしなければ、この掛金は少なくなるんですか。というのは、今、品川区は医療費無料化の制度をとっていますよね。そうすると、お子さんたちは外傷を受けたり何かしたときに、逆に医療費無料化の保険のほうを適用してくる。ここに１,０００万円ぐらい掛けていますよね。そのあたりの可能性はいかがでしょうか。","respondent":"古里学務課長","answer":"その後、すこやか医療費の助成制度を使うという形にしています。一義的に共済のほうを使うようにしています。","voiceIndex":348,"id":"exchange-156"},{"speaker":"須藤委員","kind":"質問","question":"時間がないんですけれども、先ほど、林宏委員もお尋ねしましたけれども、前にも学習のあり方が、シルバー大学なんかが高齢福祉課と連携をとってというのを民生委員のほうでやったんですけれども、同じように児童保健事業部、福祉高齢事業部と生涯学習がうまく連携をとって、品川区民全体の教育改革というもののあり方、それが区民の心の問題、それから。","respondent":"富田生涯学習課長","answer":"生涯学習というのは当課で実施している事業だけではございませんで、区ですとか、また地域等々で行っている事業を含めて大変大きな概念だと考えています。","voiceIndex":350,"id":"exchange-157"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":119116,"voices":352}},{"id":"h18-20061024-4","meetingId":"h18-c-settlement","date":"2006年10月24日","dateIso":"2006-10-24","committee":"決算特別委員会","time":"午前１０時０２分～午後６時２８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を124件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"各委員ならびに参加の委員がさまざまな意見を述べられ、また理事者の方と意見の交換、そして議論を重ねてまいりましたが、私は総括質疑という意味で、３点のことについてお伺いをしたいと思います。団塊の世代、これを区がどのように受け入れ、どのような体制をつくっていくのかということをお伺いします。３点目におきましては、いわゆるながら携帯使用についてお伺いをしたいと思います。","respondent":"山田区民生活事業部長","answer":"そうした地図の裏面を効率的に使いながら、マニュアル的に使えるような工夫をしてハンドブックを作成し、これはぜひ、全戸配布という形で周知を図ってまいりたいと考えています。","voiceIndex":2,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問・要望","question":"今のご答弁で、１点だけお願いをさせていただきたいと思うんですが、品川区は、内陸部と湾岸部で、震度５強と５弱ということでゆれが違ってまいります。その場合に、画一的な防災マップでいいのかどうかということ、まずそこを明記をして、地域色というのがあるわけですから、そこらのところに留意されておつくりいただけるのかどうか伺いたいと思います。","respondent":"山田区民生活事業部長","answer":"当然、品川区にあっては危険度マップ、火災であるとか、地震等について想定されているものが違ってまいります。ぜひそうしたものを加味した形での地図の作成、またマニュアル的にも配慮できたらと、これから検討に入りますので、参考にさせていただきたいと思います。","voiceIndex":4,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"次の質問に移らせていただきます。一時避難場所は何なのか、広域避難場所は何なのか、一つの例えですけれども、そこの部分が皆さん非常に、どこでどういうふうな拠点としての定義、確立、どのような位置を占めているのかというのが非常にあいまいな状態になっていると思います。その点について、どのように区民の方に周知をされていくのか、お考えをお伺いしたいと思います。","respondent":"山田区民生活事業部長","answer":"特に、それについては、日ごろからの学校と地域の皆さんとの連携事業が多い中で、親しみを感じている、それからだれでもがわかるというところで、学校というのはシンボルになっているのだということだと、私は思ってあります。","voiceIndex":6,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"シンボリックな学校の位置というのはわかるんですが、私がお伺いしたかったのは、シンボル的な存在ではなくて、もっと突き進んだ、シンボル以前の、実が伴っていないとは決して言いませんが、シンボライズされた学校の位置づけではなくて、実質的に「学校というのはこういうふうに使うんだよ」「こういうときにはこういうものを使いますよ」「子供たちの教育の現場として使うけれども。","respondent":"山田区民生活事業部長","answer":"当然学校現場ですから、校長、教員等の協力も得ながら実施をするわけなんですけれども、まずは備蓄倉庫ということで用意をさせていただいて、いわゆる食料の確保、それから中越地震での教訓を生かして、体育館でのシートであるとか、毛布であるとかという用具の準備です。","voiceIndex":8,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"次は、災害時要援護者についての質問なんですけれども、寝たきりや、１人暮らしの高齢者の方、災害が起きたときにどうするのかということが非常に大きな問題になっているんですけれども、その場合、訓練をする上において、先だって来問題になっています個人情報の保護というのが、非常に大きなハードルになって、地域の方たち、また町会長、自治会長をはじめ、関係者の方たちが個人情報、基本４情報ですか。","respondent":"山田区民生活事業部長","answer":"私どものほうは、各町会を含めて、いわゆる障害者、それと１人暮らしのお年寄りも含めて、ご自分がご希望される場合、本人の意思確認をした後、名簿を作成いたしまして、各町会の皆様方、消防署、警察等に名簿を提出しています。","voiceIndex":10,"id":"exchange-005","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問・要望","question":"次は、災害時の避難場所の生活用水の確保と、衛生面についてのお話を伺いたいと思うんですが、この地域防災計画にも給水体制等々については記述をされておりますけれども、どういうふうになっているのかお伺いしたいのと、また、前に一般質問でもお話をさせていただきました、衛生面、し尿の処理体制、そしてごみの衛生体制、そのような衛生管理の体制。","respondent":"山田区民生活事業部長","answer":"これは災害対策本部の中にそういったものがまず編成されます。特に、衛生班という形をとりまして、それぞれの学校を含めて消毒を実施するということになってあります。そのための訓練といたしまして、１１月に予定しております職員防災訓練の中でも、この訓練を実施する予定です。","voiceIndex":12,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"区で災害時の防災体制、区長をヘッドとする危機管理体制が設けられているということですが、これだけの町会・自治会を災害時に束ねていく、これは容易なことではないと思いますが、それについて所見といいますか、１００幾つある中で、非常に枝が多いわけですから、そこのところを一糸乱れぬ支援体制、そしてまた情報の提供体制をどのようにされていくのか、お考えをお聞かせください。","respondent":"山田区民生活事業部長","answer":"今後も、ＣＡＴＶを活用しながら、いかに防災情報を出せるか、今検討中ですので、それも含めてやってまいりたい。消防団の皆様方にも、今年度要請がありましたので、消防団長のほうには「防災伝言板」を配布させていただいたところです。","voiceIndex":14,"id":"exchange-007","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問・要望","question":"２点、お話の中から伺わせていただきますけれども、自民党の委員もほかの委員もお話しされているように、横の串の件なんですが、区は、災害時に指令情報部をはじめとして十六、七の部に分かれてくるわけですね。移動系と固定形については、さらに地域防災だけでは、災害ですから不十分だと私は考えますが、固定系、そして移動系についてはどのような整理をされていくのか伺いたいと思います。","respondent":"山田区民生活事業部長","answer":"今、一方通行でしかできない部分を双方向でできるような形で工夫をするなり、いろいろなところで、今、工夫を検討しています。","voiceIndex":16,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"それがだめな場合でも、２段、３段、今ご答弁になかったんですけれども、移動系、固定系、そして地域防災系、合わせてフル稼働できるような体制をとっていただいて、区民の方が、被災時に情報が不足することがないような形をとっていただきたいと思います。では、防災関係の質問はこれで終わらせていただきますが、次は団塊の世代についての質問をします。","respondent":"新美企画部長","answer":"団塊の世代の定年退職期に対して、自治体としてどのような対応をとるかというご質問ですが、私ども品川区といたしましても、ことし４月に従来のボランティア担当を地域連携推進担当ということで名称も変えまして。","voiceIndex":18,"id":"exchange-009"},{"speaker":"大沢委員","kind":"意見","question":"団塊の世代の方が６５歳以上になったときと、今の６５歳の方たち、その高齢者像というのがいろいろな面で様変わりをしてまいります。そういった場合に、教育や青少年育成にどのように、いわゆる元気な高齢者、団塊の世代の方たちは非常にパワーのある、今の日本の礎をつくった方たちの年代だと私は思います。その変わった像についてどのような対処の仕方をされていくのか、お聞かせください。","respondent":"新美企画部長","answer":"６５歳で一応高齢者ということですが、私どもも、明治生まれ、大正生まれ、昭和一桁生まれ、それから二桁生まれ、戦後生まれということになると、それぞれの方々、生まれ育った時期が違うということで、当然価値観、それから志向も違うということを十分認識をし。","voiceIndex":20,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"以上で、団塊の世代についての質問は終わります。次なんですが、ながら携帯電話について簡単に質問させていただきたいんですけれども、これの話になってしまうと、モラルよりルールということになってしまうんですけれども、近年、自転車に乗りながら携帯メールということで、非常に区民の皆さん、おっかない思いをしているし、事故も起こっているということです。","respondent":"福田まちづくり事業部長","answer":"このことにつきましては、交通安全上望ましいことではないと考えています。携帯電話というのは、今言いましたように、二つの目的を同時にかなえてくれる、大変便利な機器ですが、それだけに注意を喚起していく必要があるだろうと考えています。","voiceIndex":22,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"注意を喚起していただきたい。それで、広報等を通じて注意・啓発活動を、携帯が普及してから久しく十数年たっておりますけれども、特に、ながら携帯電話の使用は危ないですよというような内容のことで、広報に載せられて、また区民の方に周知された回数は今までどれぐらいあったんでしょうか。","respondent":"福田まちづくり事業部長","answer":"広報紙ということではございませんけれども、自転車と、それからドライバーなどに訴えましたリーフレットを作成いたしまして、町会・自治会、それから小中学校、そういうところに幅広く配付して、啓発活動を行ってまいりました。","voiceIndex":24,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"携帯電話のメールを使いながら歩くのは前方不注意ですけれども、そこの歩行者までを範ちゅうに入れてしまうと、個人の権利に対する行政権の介入ということになっちゃうんですけれども、こと、自転車を運転しながら携帯メールを打つということは、道路交通法上の片手運転の禁止ということに該当するとは思いますが、そこの部分でいかがお考えになりますでしょうか。","respondent":"福田まちづくり事業部長","answer":"道交法の７０条、今、委員ご指摘になりました片手運転の規定は、道交法の７０条にございまして、携帯電話を、器用な方は片手で打たれますが、そうしました場合でも、片手運転にならざるを得ないというものですので、道交法に抵触するものです。","voiceIndex":26,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問・要望","question":"道交法に抵触するということで、携帯メールを別にして、生活の用に供するもの、例えば今日のように雨のときに傘をさしたり、横で持つ、これは生活の用に供するものであるからいたしかたないと思いますけれども、なぜ自転車を運転しながらメールを打たなければいけないのかということで、非常に疑問を感じざるを得ませんので、そこの周知といいますか、何らかの枠組みをお考えになっていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-014"},{"speaker":"石田委員","kind":"提案","question":"大沢委員に引き続きまして総括質疑を行います。このような形で決算特別委員会が迎えられるというのは、品川区政史上初めてでもあり、濱野新区長を迎えて、我々を含め、区民にとっても確認したいことを伺ってまいりたいと考えています。品川自民党区議団では、２０４項目にわたります平成１９年度の予算編成に関する政策要望を区長に提出させていただきました。この内容につきましても確認をしたい。","respondent":"濱野区長","answer":"これは、地方自治法、大変に地味な改正のように思われておりますけれども、かなり行政体、あるいは自治体としては意味の重い改正だと考えています。そういった中で、条例上２人という体制が明記をされておりますので、その２人体制について視野に入れていきたいと考えています。","voiceIndex":30,"id":"exchange-015"},{"speaker":"石田委員","kind":"提案","question":"自治法の改正の話もありましたが、名前はもちろん聞くことはありませんが、今定例会で１名の方の提案をいただけるということで、我々もしっかり審議をして、またその考え方についてもしっかり議論していきたいと考えています。それはそれでしっかり体制の確立をしていただきたいと考えています。","respondent":"濱野区長","answer":"そのことをしっかり区民の皆様にもお知らせをするということが大事だと考えていますので、その点については十分配慮していきたいと考えています。","voiceIndex":32,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"今回は別に区長会の会長であるわけでもありませんし、本当の品川区の代表として、区長会と、２３区、他区の区長ともわたりあっていただきたいと思っておりまして、ここら辺の、我々品川区、我々議会も、２３区ですごいと思われるぐらい頑張ろうと思ってやっているわけでありますから、そこら辺の点も含めて、区長会等に出て行ったときの代表としての意気込みをまずお聞かせ願いたいと思います。","respondent":"濱野区長","answer":"その基本は、品川は自治権拡充に非常に熱心に取り組んできたという伝統といいますか、ものの考え方が定着をしている区でありますので、その区を代表する者として、特別区の権能が拡充をするような、そういう方向でさまざまな問題について発言をしていきたい。","voiceIndex":34,"id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"今、東京都という話がありました。区長会ではもちろん言っていっていただきたい。そういう意味合いの中で、今のあり方検討会を、まず、濱野区長としてどういうふうにとらえられているのか、どういう形の部分には切り込んでいかないとだめだと思われているのか、それから、あわせて平成１９年度の財調協議が始まってまいります。","respondent":"濱野区長","answer":"私は、この都区のあり方の検討会に直接参加する立場にはありませんけれども、先ほども申しましたけれども、特別区が本来やるべきことを東京都にお願いをしているんだということで財政制度が成り立っているわけでありますけれども、それでは。","voiceIndex":36,"id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"しっかり発言をしていただきたいなと考えています。今の点でもう一つだけ確認をさせてください。特別区が担ったらという、もちろんそのとおりで結構です。この水平調整のところで、高橋前区長はまとめ役でありましたから、そういうところは置いといて、今は濱野新体制でありますので、そこら辺の水平調整についてどうやって切り込んでいくかということだけ、もう一遍ちょっとお聞かせ願えますか。","respondent":"濱野区長","answer":"そういったことの積み重ねでもって、２３区の水平調整についても、先ほど申しました理念をしっかり持っていることと、この技術的なことを研究するということで可能になると私自身は考えてるところです。","voiceIndex":38,"id":"exchange-019"},{"speaker":"石田委員","kind":"質問・要望","question":"その部分は、２３区の水平調整がとれて、かつ、自治体が基礎的な自治体として独立できればいいと思いますが、あまりに、どこの地区とは言わないけれども、このままでいいだろうという地区は必ずあるわけですから、あまりにそこができないのであれば、品川は独立するぞ、それぐらいの気持ちで臨んでいただきたいなと考えていますし、私は。","respondent":"濱野区長","answer":"これが平成２２年までを終期とする計画で、ある項目によっては既に達成しているような部分もあるわけでありますので、こういったものの見直しが必要となるかどうなのか、こういったことも含めて組織の問題というのは考えていきたいと考えていますので。","voiceIndex":40,"id":"exchange-020"},{"speaker":"石田委員","kind":"意見","question":"ところが、やっぱり縦列が強くなったのかなと。事業部長同士も連携をとれるようになったのかなと。その次のところが非常に垣根が高くなってきていて、そこの部分の連携を一歩越えるのが、見ていると、何でこんなに垣根が高いのかなというような感覚があります。そこら辺の感覚というのは、私の感覚が間違っているのか、どういうふうにとらえられているのか、そこら辺をちょっとお聞かせ願いたい。","respondent":"濱野区長","answer":"第三次長期計画を見直すとは申し上げておりませんで、見直しが必要かどうかという検討をしなければならないと思っているところです。事業部制のお話が今、ありました。","voiceIndex":42,"id":"exchange-021"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう形で見ていくとなると、私は部長はやっぱりゼネラリストの感覚を持っていないと、事業部長がスペシャリストの感覚でいると、やはり今みたいに近くに頼ろう、助役に頼ろう、事業部間の、せっかく事業部長がしっかり頑張っていらっしゃるわけですから、そのゼネラリストの部分を持っていないと、私は今の横串がさっといかないのは、そこら辺だろうというような気を持っておりまして、これは助役時代。","respondent":"濱野区長","answer":"ただ、それをどういうふうに実行していくかについては、かなり慎重に物事を進めなければならないと考えていますが、そういう意味での適正規模のありよう、それから再配置といったことは重要な課題であるという認識をしているということで、お答えをしたいと思います。","voiceIndex":44,"id":"exchange-022"},{"speaker":"石田委員","kind":"意見","question":"我々ももちろん重要な課題だと考えています。そこの点の考え方について、実行の部分でありますけれども、濱野区長もどうお考えなのかというのをもう一点、お聞かせ願いたい。それであわせて、そのときに必ず小中一貫校の６校整備というのが出てまいります。２校はそれで済む。八潮は大体の感覚も出てきている。そこら辺の考え方について、あわせてお聞かせ願いたいと思います。","respondent":"濱野区長","answer":"このことは十分に認識しています。","voiceIndex":46,"id":"exchange-023"},{"speaker":"石田委員","kind":"意見","question":"公園もあった。隣には都営住宅もあった。ここにこういう施設を持っていったほうがいいだろうとか、そういう考えを持つべきだろうと思っています。この公園とどういうふうに連携をとるんだ。そういう部分を全部一体的に隣接地を含めて、計画を練っていくべきだろうと考えていますが、そういう意味の立地条件というのも含めて言っているつもりなんですが、そこら辺のお考えも含めてお聞かせ願いたい。","respondent":"濱野区長","answer":"個々具体の話になりますと、ここでなかなかお答えしにくくなりますけれども、今、委員がお話しのように、いろいろな要素を勘案する必要があるということも十分認識しています。一方で、どれもこれも考えていくと一向に進まないということもあります。ここは兼ね合いです。","voiceIndex":48,"id":"exchange-024"},{"speaker":"石田委員","kind":"質問・要望","question":"平米数も足りない。そういうところは民間だけに任せていくのか、まちづくりをしていく観点から行政がそういう部分でマンションのそういうところがまとまって、みんなとやりましょうと言ってきたときには、既存不適格であるわけですから、なかなかそれが進まないとするならば、区のほうもやっぱりそこら辺を継続的に支援をしていく制度があっていいと思いますが、そこら辺のご見解をお聞かせください。","respondent":"新美企画部長、岩田まちづくり事業部次長","answer":"しかしながら、行政需要の部分で、跡地になったものをどのように空けないで使っていくかということになったとき、あるいは学校跡地以外の公有地の跡ということになってまいりますと、この考え方を基本にしつつも。しかし、実質的には資産の建て替えになりますので、その費用の調達をどうするかとか、まだまだ実際課題が多くて、国もそれをどう支援していくかということをいろいろ検討しています。","voiceIndex":50,"id":"exchange-025"},{"speaker":"石田委員","kind":"確認","question":"どうぞ、よろしくお願いします。最後に１点だけ、これだけは確認したいと思います。文化・芸能・芸術に対する区長の考え方をお聞きしたいと思っておりまして、高橋区長もそうでありましたが、ぜひその点をお聞かせください。","respondent":"濱野区長","answer":"そういう意味では、行政として必要なものがどういうことにあるのかというようなことを見きわめながら、かかわってまいりたいと思っています。","voiceIndex":53,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"この問題について伺いたいと思います。質問の１点目は、改めて品川区は八潮南中学校の入学者０の原因をどう考えているのか。２点目は改めてプラン２１の実施の目的から、入学者０、５校統廃合、小中一貫校へ、この一連の区の政策の経過を説明していただきたいと思います。やむを得ない、仕方がないと考えているのか、どう考えているのかご説明いただきたいと思います。","respondent":"長田教育次長","answer":"その波が来たんだろうと思っているところが一番です。それから２点目の八潮地区の一貫校の問題ですけれども、私どもは小規模になったから、廃校にしようなんていうことは毛頭考えていないことは、今までの説明でも申し上げたとおりです。","voiceIndex":57,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"今の八潮南中学校の原因の説明がありましたけれども、入学者０、これは八潮特有の事情だと思っているのか、ほかに理由はないのか、もう少しお考えをきかせてください。もう一つ、八潮地域で起きた入学者０、そして５校が１つの一貫校に統廃合、この事態は八潮地域以外でも飛び火する可能性があるという認識はあるのかどうか、教えてください。","respondent":"長田教育次長","answer":"それとそのほかの理由はないのかですけれども、やはり小規模校では、本来学校教育として実施していくようなことの中に、集団の中での活動を通じて人間性の育成をというような目的があるわけですけれども。","voiceIndex":59,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区はどうしても八潮南中学校が入学者０になったことを、学校選択制の影響ということを認めたがらない。逆に伺いますが、今ご説明があった３４人は、なぜ入学者０になってしまったのか、その要因をどう考えているのか、教えていただきたい。それとこの３４人、来年、再来年、住民基本台帳上はどういうふうに推移しているのか、教えていただきたい。そこについてご答弁をお願いしたいと思います。","respondent":"長田教育次長","answer":"それから統廃合の不安ですけれども、私ども、日野学園に続く学校についての説明会に入ったときに、少なくとも統廃合に関する不安というようなこと、それから小中一貫校の建設について、これはやっちゃいかんというような話というのは聞いてございません。","voiceIndex":61,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"八潮南中学校の地域では、今年は新入生が３４人、それがほかの学校を選択した。つまり、学校選択制の影響があることをどうしても品川区は認めたがらない。しかしこれは事実です。つまり、このことは小中一貫校の建設によって、周辺校は統廃合やむなしという考えなのか、それともそうならないように、区はどういう対策を考えているのか、あわせてお考えを聞かせてください。","respondent":"長田教育次長","answer":"それから統廃合やむなしかですけれども、これも先ほど申し上げていますとおり、そこの学校を選択している児童・生徒がいる限り、教育委員会は最大の支援をしていくというようなことで、こういった部分については、八潮南中学校に対しても。","voiceIndex":63,"id":"exchange-030"},{"speaker":"中塚委員","kind":"意見","question":"品川区は区民の気持ちや、周辺の保護者の気持ちを一体どういうふうに理解しているのかなと、私は疑問です。例えば八潮地区での小中一貫校への統廃合の事態が、八潮地域以外の方々から、自分の学校が統廃合になるんじゃないかという不安の声が上がるのは、品川区はなぜだと思いますか。","respondent":"長田教育次長","answer":"区民の気持ちと、ほかの地域で統廃合の心配が既に上がっているということでの発言ですけれども、少なくとも私どものほうは、先ほどからも申し上げているとおり、圧倒的に期待のほうが多いわけですので。","voiceIndex":65,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"ということは、小中一貫校のためなら学校統廃合はやむを得ないと区民自身がそう思っているんですか。教えてください。","respondent":"長田教育次長","answer":"こういった部分については、教育委員会とさまざまな支援を通じまして、学校が存続をするように支援をしているというようなことは、先ほどからも申し上げているとおりです。","voiceIndex":67,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"私は小中一貫校を区内に合計６校つくる。品川区は統廃合しない、させないための具体的な手立てはどう考えているのか、そこを伺いたい。例えば八潮南中学校の例をとりますと、３４人の方がほかの学校を選択した。入学者数で見ると、３４人を下回っている学校は９校あるんですね。１００年を超える学校がたくさんある。私はそのシステム上の問題に欠陥があるのではないかと思いますけれども、いかがでしょうか。","respondent":"長田教育次長","answer":"先ほどの発言の中では、教育委員会が統廃合を進めるためにさまざまな手を打っているというように聞こえたようなご質問だったわけですけれども、これについても、先ほど来お答えしているとおり、一貫校については、教育上の必要性から出てきたものですから。","voiceIndex":69,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"私は、品川区が目的もねらいも学校統廃合を意図しているわけではないと。しかし、実態が学校統廃合へと進んでいるのではないかと。実際、それ自身は学務課長も教育次長も、答弁の中で認めているんですね。学務課長に至っては、日野学園の周辺のことを指しまして、周辺校への影響というのは日野学園でも起こっている。この欠陥についての答弁がありませんでしたので、改めて伺いたいと思います。","respondent":"長田教育次長","answer":"統廃合に対する心配がものすごく地域の中で吹いているような発言ですけれども、そういうことではございません。この間の教育委員会のさまざまな説明の中では、これから地域の学校をどうするかという部分については、地域の話をよく聞いてと。","voiceIndex":71,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから、地域の要望というお話が繰り返されていましたけれども、こうした仕組みをつくったのは、決して地域ではありません。地域の要望というのは、八潮に暮らしている方々の追い込まれた気持ちを無にした、結局は、品川区は自分の手を汚すことなく、世論やマスコミの学校統廃合への批判をかわすために、保護者にその責任を与えているのではないかと私は思います。保護者ではありません。だれですか。","respondent":"長田教育次長","answer":"少なくとも説明会ですとか、個別の相談の中で、あなたが選んだんでしょうというような言い方、責任を取りなさいというような言い方については、教育委員会としては今までも１回も言っていませんし、これからもそういうようなことを言うつもりは全くございません。","voiceIndex":75,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"品川区はこれまで繰り返し、学校選択制は目的ではなくて、手段だと話しておりました。学校を活性化させたい。私はその手段が今、間違っていたのではないか。私はなぜそこまでして学校選択制、小中一貫６校構想を強引なまでに進めていくのか、そこがどうしても理解できません。私は今こそ立ちどまって、見直すこと、検証する姿勢が品川区には必要ではないかと思いますけれども、いかがでしょうか。","respondent":"長田教育次長","answer":"それからこの一貫教育についての検証につきましては、もう既に学校選択制の部分につきましては、平成１６年に一定の検証を行っておりますし、それから今、小中一貫教育の全体像についても、昨年から検討を始めたわけですけれども、今年度は新たな検討組織を立ち上げまして、今。","voiceIndex":77,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中のどれも、批判的であったり、慎重論が出たり、今立ちどまって検証すべきでないかという声がたくさん上がっていると思います。濱野氏には区民一人一人の声に耳を傾け、一連の改革の功罪を検証しながら進めていく姿勢を求めたい」と結んでいるんです。濱野区長は就任のあいさつの中で、区民の声を聞くと述べたが、それは自分の意見と違う声も含めて、受けとめるという意味でよろしかったのでしょうか。","respondent":"濱野区長","answer":"これは款別で審査した内容とほとんど同じことのような気がいたしますが、なぜ総括でもう一度同じ質疑をやり直すのか、ちょっと合点がいきませんが、款別の審査でもお答えをいたしましたように、小中一貫教育をとめる気はございません。","voiceIndex":79,"id":"exchange-037","title":"町会・自治会支援"},{"speaker":"中塚委員","kind":"質問","question":"今、款別審査のお話がありましたけれども、款別審査の中で、学校適正配置の問題もあるとしながらも、それはこれからの課題だと。そのことと小中一貫校云々は切り離して考えたいと、答弁されたんですね。私はこの真意をもう一度伺いたい。新区長が自分らしい区政運営、ここで言う、「そういう方向へは導かない」とは何を意味しているのか、教えてください。","respondent":"濱野区長","answer":"款別審査でお尋ねになったことは、小中一貫校教育は学校統廃合への道具といいますか、そういう仕組みなのではないかというご質問でしたから、それは違いますとお答えした。款別審査でお答えしたとおりです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はこの八潮で起きたこと、そして日野学園に起きている事態、これは学校統廃合へとつながってしまう、そういう仕組みづくり、そこに改めて欠陥があるのではと、強く話したいと思います。学校は区長も言うとおり、区民の心であり、文化です。母なる学校はみんなの母校です。学校選択制や小中一貫構想、教育改革プラン２１の見直しを強く求めて、私の質問を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"私からは４点、財政効率について、あと高齢者福祉、そして障害者福祉、住宅施策についてお伺いします。社会格差と、そして貧困が広がる中、増税、そして年金や医療費の負担増に苦しむ区民の今の生活実態をどのように認識されていらっしゃるのでしょうか。国の政治が冷たい中、自治体の仕事は公共性、つまり区民の利益と、そして生活保障を第一にすべきと考えますが、まず区長に見解をお伺いいたします。","respondent":"新美企画部長","answer":"そういう意味で、私ども区民の生活実態ということにつきましては高齢者福祉、子育て支援、学校教育、産業振興、諸々の施策を最も住民に身近なところで実施しておりますので、それぞれの政策実施の中で、実態を把握させていただいているところです。","voiceIndex":85,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"私は区長にお伺いをしたんですけれども、今の区民の生活実態をどう認識されているのか、その点についてお伺いをしました。お答えください。","respondent":"新美企画部長","answer":"今、生活実態についてお答えをさせていただいたわけですが、すみません、１つ答弁が漏れておりました。","voiceIndex":87,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、区民に寄り添って、区民の痛みをしっかりと受けとめて施策を行っていただきたい。次に移ります。区が採用しています不安定雇用である非常勤、そして派遣職員は現在、何人でしょうか。数字を続けてお伺いします。この２０年間に削減をした正規職員の総数、そしてもう一つ、正規職員を非常勤や派遣職員に置き替えたことによる財政効率は幾らになったのか、教えてください。","respondent":"本間総務部長","answer":"数字のお尋ねです。平成１７年４月１日現在の正規の職員数は２,７６０人、非常勤職員が８８７人、人材派遣職員数が１３７人です。それから昭和５８年から行財政改革に取り組んでございまして、今年平成１８年までの正規職員の削減数ですが、これは合計で１,６０５人です。","voiceIndex":89,"id":"exchange-042","title":"町会・自治会支援"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、財政効率による効果、幾らになるのかとお伺いしたので、この点についてもお答えをください。先に行きます。この間、保育園、児童センター、図書館など多くの職場に非正規職員の採用が行われてきましたが、３時間、そして５時間非常勤職員の賃金と雇用保険、社会保険など、労働条件がどのようになっているか、お伺いをいたします。","respondent":"本間総務部長","answer":"ただいまお答えしましたとおり、品川区の行財政改革、さまざまな創意と工夫を図って、この間、職員の削減に努めてきておりますので、単純に正規職員を非常勤に置き替えての金額云々ということは、お答えできません。","voiceIndex":91,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"確認","question":"今、お答えをいただいたところですけれども、３時間、５時間、５時間の有資格者が１,５００円、その方は５時間働いて、２０日だと月に１５万円なんですね。この１５万円というのは、高校生の初任給以下なんですね。１５時間とか２５時間で働いている方はこの中に該当しないということをまず確認をさせてください。","respondent":"本間総務部長","answer":"ただいまお答え申し上げましたとおり、これはきちんとした法律の定めがございまして、その法律に準拠して適用できる職員につきましては適用しているです。","voiceIndex":93,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ３時間、５時間勤務の非常勤職員しか雇わないのでしょうか。財政効果を最優先にした選択であると思っています。このことを踏まえて、以下、３点の改善を求めます。非常勤の職員に対して、１、時間給の引き上げを求めます。２点目、社会保険そして雇用保険の適用を当てること、３点目は任用期間を希望者には１年以上とし、希望者にはまたその後、正規雇用の道を開くように求めますが、いかがでしょうか。","respondent":"本間総務部長","answer":"例えば保育園が時間延長でサービスをすると、区民サービスの向上のために、その部分につきまして、勤務の実態に合った時間帯に適応する職員を雇用するという形で、実施したということで、決して安易に非常勤職員に置き替えていることではないとご理解いただきたいと思います。","voiceIndex":95,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職員を削減して、不安定雇用を増やし、５００億円の基金を健全財政と、このように自慢できるのでしょうか。改めて品川区に働くすべての不安定雇用の皆さんの待遇改善を早急に行うことを求めまして、次の質問に移らせていただきます。特別養護老人ホームをつくってほしい、議会への請願も含めて、区民の強い願いがこの間届いております。特別養護老人ホーム建設を求め、質問をいたします。","respondent":"木下福祉高齢事業部長","answer":"あわせまして、私どものほうは在宅介護支援センターを通して、区民の方々のケアに対するニーズについては、的確に把握をしていると考えているところです。","voiceIndex":97,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"２３区の特別養護老人ホームの整備状況を調べてきました。２０００年５月から６年間に建設される特別養護老人ホームのベッド数の一覧表です。２０区で６４カ所建設をし、５,５１５ベッドが新たに増えました。１位の足立区、一番上です。７カ所建設、７０９ベッド増です。ニーズがとても高くて、整備がおくれています特別養護老人ホームをつくらない理由を、改めてお聞きしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"区内の特別養護老人ホームは多床室でありますけれども、ここでも前、申し上げましたけれども、職員体制は２.２対１ぐらいでないと、サービスが賄えない状況にあります。これが個室になりますと、多分２対１以上の職員体制をとらなければ、運営が非常に難しい。","voiceIndex":99,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も今の説明をお伺いして、特別養護老人ホームとケアホームの違いって一体何なんだろう、ちょっと詳しく知らせていただきたいと思っています。利用者にとっても、区がつくって運営するに当たっても、どう違うのか知りたい。利用料金をお伺いします。特別養護老人ホームとケアホームと、同じく要介護５の方で、それぞれの月額利用料を教えてください。建設費、運営費への補助への違いがあるのでしょうか。","respondent":"木下福祉高齢事業部長","answer":"ケアホームにつきましては、組み立てによって、あるいは大きさ等によっていろいろ違ってまいりますけれども、２０万円から２５万円前後ぐらいの数字が一般的ではないかと思っているところです。","voiceIndex":101,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"有料老人ホームをなぜ税金を投入してつくるのかという点もお答えいただきたいと思いますが、先に行きます。インターネットで、２３区有料老人ホームの建設状況を調べてみたんです。入居一時金２００万円前後。これも何か中心になっているようですが、有料老人ホームは民間に任せるべきではないでしょうか。私はこのような方、どうしたら救われるのでしょうか、ぜひお答えいただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では民間が進めている有料老人ホームと同じだというのは、誤解ではないかと思っているところです。ケアホームを今進めている理由ということにつきましては、先ほど運営上の問題、それから利用される方のニーズの問題等を含めてご説明いたしました。","voiceIndex":103,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"有料老人ホームは民間に任せるべきではないでしょうか。品川区内に住み続けたい願いにこたえる、区内にぜひ特別養護老人ホームの建設を求めて、次に行きたかったんですが、時間がなくなってしまいました。障害者の雇用のところを聞きたかったんですが、このところ障害者自立支援法によって、負担が増えていますが、この１割負担について、どうお考えでしょうか。","respondent":"木下福祉高齢事業部長","answer":"厳しい方については、いろいろな形での軽減措置をとっているところでございまして、この１０月からも、例えば品川児童学園につきましては、従前のご負担で行けるように、その相差を軽減する措置をさせていただいたところです。","voiceIndex":105,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は今の品川区政を見ていて、本当に福祉が遠のいていくなという感想を持ちます。ぜひ５００億円を使って、福祉充実をさせていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-051"},{"speaker":"山路委員","kind":"質問・要望","question":"質問に入ります。初めに区長が公約に掲げている子育て支援の拡充について、３点ほどお伺いいたします。質問の１点目は子育て家庭への経済的支援についてであります。区長は安心して子育てができ、健やかに子どもが育つ品川をつくるため、出産費用補助や児童手当の拡充などの子育て支援を拡充していくと話されていましたが、こうした子育て家庭への経済的支援についてのお考えをまずお伺いいたします。","respondent":"濱野区長","answer":"子育て支援には今、お尋ねの経済的な支援と、もう一つは保育の支援といった、幾つかの側面があろうかと考えています。経済的支援についても、国とか、あるいは東京都の動向をよく見定めつつ、財源の確保を含めて検討が必要だと考えているところです。","voiceIndex":109,"id":"exchange-052"},{"speaker":"山路委員","kind":"質問・要望","question":"出産費用の補助についてですが、既に国保では２３区においては３５万円まで助成されておりますが、我が党の強い主張により、国制度でも本年１０月より３５万円に引き上げられました。しかし、都市部にあっては３５万円ではまだ十分ではなく、５０万円までの引き上げが必要とも言われています。願わくば少子化に歯どめをかけるためには、さらなる拡充が求められますが、あわせてご所見をお伺いいたします。","respondent":"濱野区長","answer":"先ほど申しましたように、経済的な支援ということについての必要性ということを十分に認識しております。こういった問題については、財源の問題が非常に重要です。そういうことを踏まえて、国や東京都の動向を見定めつつ、前向きに検討していきたいと考えています。","voiceIndex":111,"id":"exchange-053"},{"speaker":"山路委員","kind":"提案","question":"先日の都議会、第３回定例会の代表質問で、長橋議員は、我が党は第１回定例会で子ども医療費助成を中学３年生までの引き上げを提案したことと、また６月には都議会公明党として、要望書を東京都へ提出した際の福祉保健局長は拡大すると述べたが、その後の検討状況についてどうなっているのかを質問しました。事実とすると、これまでの区の負担が一部軽減されます。","respondent":"濱野区長","answer":"東京都の方向については、近いうちに説明会があると聞いておりますので、東京都としてこういう方向で実施をするということは、間違いないと考えています。この医療費助成については、今、各区でいろいろな方法がとられております。","voiceIndex":113,"id":"exchange-054"},{"speaker":"山路委員","kind":"提案","question":"質問の２点目は保育事業の拡充についてお伺いいたします。小規模事業者では１社で保育所の設置は余裕がなく、難しいことは当然予想されますが、そこで区内の中小企業や働く方たちを対象に、保育のニーズ調査を行い、必要としている企業に対しては、保育の専門家を派遣し、場合によっては近くにある企業数社がまとまって保育施設を立ち上げる事業を提案いたします。それぞれご見解をお伺いいたします。","respondent":"濱野区長","answer":"そういった意味で、これからの一つの大きな動向というのは、企業による保育事業を支えていくといいますか、あるいは引っ張っていくと申しますか、そういう役割が出てくるのではないかと考えておりますので、こういった空き店舗活用のものも含めて、これは今。","voiceIndex":115,"id":"exchange-055"},{"speaker":"山路委員","kind":"質問","question":"質問の３点目は子育ての環境整備についてお伺いいたします。児童センターとの兼ね合いが大変気になるところでありますが、区長はどのように子育て環境整備をされていくのか、ご所見をお伺いいたします。","respondent":"濱野区長","answer":"片や児童センターにおいて、お母さんとお子さんが集っている。これを一つの場に融合、統合できないだろうかということを考えた次第です。例えばもちろん保育は保育士によって行われますけれども、隣の壁一つ隔てたところにはお母さんがいらっしゃるわけです。","voiceIndex":117,"id":"exchange-056"},{"speaker":"山路委員","kind":"質問・要望","question":"区長の子育て支援、大変期待をしております。未来につなげ、未来に満ちた、明るい未来をつくっていただくことを心から願っております。次に高齢者施策についてお伺いいたします。そこで、質問の第１点目は、これまでの各種元気高齢者支援施策がもたらした効果について、またしながわシニアネット開設の目的や事業内容と、これまでの各種施策との関連性、関係性についてもお知らせいただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"これが例えば荏原のほっとサロンなどの事業があります。このシニアネットはそういう意味では、この２つの側面を両方あわせ持つ事業というような形に位置づけられるのではないかと思っているところです。","voiceIndex":119,"id":"exchange-057"},{"speaker":"山路委員","kind":"質問","question":"公明党は高齢者人口に占める要介護者比率の３割減を目指した介護予防１０カ年戦略を策定しています。そこで質問の第２点目に入りますが、区長の高齢者施策の展望と、元気プラザ構想についてお伺いいたします。区長は超高齢化の時代に向け、さらに一歩踏み込んだ高齢者施策の展開の必要性を訴えてこられました。そこで今後の品川区における高齢者施策の展望について、区長のご見解をお伺いいたします。","respondent":"濱野区長","answer":"これはこれで生かしつつ、将来の施設の再配置に合わせて、こういったそれぞれ今点在して、展開しているような施設を、場所によっては、１カ所でさまざまな機能を盛り込んだ施設として展開できるという考えで、元気プラザというお話をさせていただきました。","voiceIndex":121,"id":"exchange-058"},{"speaker":"山路委員","kind":"提案","question":"これまで公明党としても介護予防拠点については、中学校区に１つは整備をと主張してまいりました。そこで質問の３点目は、品川区における現行の介護予防サービスの事業内容と、これまでの成果についてご説明願います。あわせて私どもが提案する、歩いていける身近な地域に介護予防拠点を整備することに関し、今後の事業展開の見通しについてもご見解をお聞かせください。","respondent":"木下福祉高齢事業部長","answer":"これまでの成果を踏まえながら、例えばシルバーセンターの整備等々の機会をとらえながら、介護予防拠点の整備については今後とも検討をしていきたいと思っているところです。","voiceIndex":123,"id":"exchange-059"},{"speaker":"山路委員","kind":"提案","question":"健康づくりが大切と言われる中で、脳卒中や糖尿病などの生活習慣病を引き起こすメタボリックシンドロームが大きな社会問題ともなっています。そこで次の提案として、いつでも身近で、そして気軽に健康の維持・増進を図ることができる施策の展開として、屋外でも健康器具を利用できるよう、公園の有効活用の方策を図ってはいかがでしょうか。ご所見をお伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"現在、２０カ所の公園に健康遊具が設置されているですので、今後とも健康づくり、あるいは介護予防の視点から、それらの施設について有効に使っていくように検討をしていきたいと思っているところです。","voiceIndex":125,"id":"exchange-060"},{"speaker":"山路委員","kind":"提案","question":"この件につきましては、昭和６３年第３回定例会の一般質問で、ひとり暮らしのお年寄りが火災で亡くなった事例を挙げ、寝たきりあるいはひとり暮らし老人世帯の生命を守るために、初期消火の面で効果がある住宅用消化装置としての住宅用のスプリンクラーの設置や、助成制度の創設について提案して以来、数回にわたり要望してまいりました。状況についてお伺いいたします。","respondent":"山田区民生活事業部長","answer":"高齢者の方々がそういうときに迷ったり、困ったり、また買ってしまった後、どうしたらいいかということにつきましては、私どもの消費者センターの相談員が丁寧に対応させていただいていると同時に、消費者団体と協力をしまして、消費者の日や消費生活展など、機会をとらえて。","voiceIndex":127,"id":"exchange-061"},{"speaker":"山路委員","kind":"提案","question":"先日、この住宅用火災警報器の設置義務化に伴う補助事業の創設についてご提案したところ、まちづくり事業部長のご答弁では、認知症、高齢者などを対象とした給付事業を実施していることなどから、今のところ考えていないとのことでしたが、この給付事業について、火災安全システムのことかと思いますが、事業の内容と昨年度の給付実績について教えていただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"この火災安全システムは火災発生時に消防庁のほうに自動通報すると同時に、屋外にかなり大きな音でベルを鳴らすというものでございまして、基本的に認知症高齢者の方で、ひとり暮らしの方について対応をしてきたという経過があります。","voiceIndex":129,"id":"exchange-062"},{"speaker":"山路委員","kind":"提案","question":"区長は区長選に臨むに当たり、掲げた政策の１つに、高齢者施策のさらなる拡充を挙げられております。住宅火災での逃げおくれにより、亡くなる高齢者が増加していく中、こうした高齢者の命を１人でも多く救うためにも、高齢者や障害者等の災害弱者の方や、所得により負担感の強い方を中心に住宅用火災警報器への補助を実施されますよう、改めて提案いたしますが、ご所見をお伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"どのような支援策が可能なのかという点について、今後検討をしていきたいと思っているところです。","voiceIndex":131,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"どうぞ、よろしくお願いいたします。昨年の平成１７年６月の第２回定例会で、我が党の同僚議員がシルバー人材センターの職種の拡充について要望したことを受け、今年度から高齢者を対象としたパソコンの出張相談とともに、新たな事業としてシルバー人材センターによる家具転倒防止器具の取付事業が行われておりますが、この事業の具体的な内容と、現在までの実績についてお伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"１回の作業時間が大体３時間程度かかりまして、３,２１０円になりますが、非課税世帯につきましては、この作業時間の費用を区の補助金の中で助成するという体制をとっているところです。現在までの利用の状況は２件あるです。","voiceIndex":133,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひ１人でも多くの方にご利用してもらえるように、広報しながわや、ケーブルテレビ等でさらに事業内容を周知徹底されますよう、要望いたしますが、ご所見をお伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"今後、周知方法についてはさらに検討する必要があろうかと思いますが、シルバー人材センターの実績あるいは成果、あるいはこの部分につきましては、関連する部門もありますので、全体的な調整をしながら、さらに検討をさせていただきたいと思っているところです。","voiceIndex":135,"id":"exchange-065"},{"speaker":"山路委員","kind":"提案","question":"今回の決算特別委員会でも取り上げましたが、品川区としての耐震改修促進計画を早急に策定するよう、１０月１９日、濱野新区長に対し、申し入れを行い、委員会でご答弁いただいたとおり、区も積極的に取り組まれるとのことでしたが、この家具転倒防止器具の設置については、本年の予算特別委員会の総括質疑で、同僚議員が住宅の耐震改修を促進させるための方法として実施するよう提案した際。","respondent":"木下福祉高齢事業部長","answer":"今後、この事業の成果を見ながら、区のほうとして、どのような具体的な支援策が必要なのかという点について、検討をさせていただきたいと思っているところです。","voiceIndex":137,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問","question":"最後に天王洲地区のまちづくりと、東品川海上公園を結ぶ、水と緑に親しめる施策についてお伺いいたします。天王洲地区においてお伺いをいたします。平成１７年６月に東京都は水の都、東京復活と位置づけ、運河ルネッサンス推進地区として指定いたしました。そこでお尋ねしますが、この推進地区を指定された背景と、どのようなプランなのか、また区としてのかかわりについてお伺いいたします。","respondent":"福田まちづくり事業部長","answer":"こうした認識につきましては、単に東京都や品川区、行政だけではなくて、民間の方たちにもそういう同じような認識がおありになるんだろうと、私どもは考えております。","voiceIndex":139,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問・要望","question":"インストラクターの教えで、カヌーやボートなど、水辺を生かした楽しみ方ができるよう、関係機関と協議していただきたいと思いますが、ご見解をお伺いいたします。","respondent":"福田まちづくり事業部長","answer":"したがいまして、今後、この運河ルネッサンスの趣旨を踏まえまして、地元との連携によりまして整備を進めていくべく、検討させていただきたいと考えています。","voiceIndex":143,"id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"次に東品川海上公園についてお伺いいたします。この公園は今年度をもって、すべての工事が完了し、区内でも広い公園の１つとして、その完成が望まれております。そこで区内には品川区民公園、品川中央公園、林試の森公園など、それぞれ特色のある大きな公園がありますが、この海上公園はどのような特色を持った公園となるのか、お伺いいたします。","respondent":"福田まちづくり事業部長","answer":"これは行政上の位置づけですが、水とみどりのネットワーク、今、新・水とみどりのネットワーク構想を練っているところですが、こうした構想における中核的な施設、特色と言えるかどうかわかりませんが、そういう位置づけを持った公園だと考えております。","voiceIndex":145,"id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"ありがとうございました。私はこれまで、この公園内に香りを楽しめる樹木を植えてもらいたいと要望し、区として今後植樹を何本ぐらい植えられようとされているのか、お伺いいたします。","respondent":"福田まちづくり事業部長","answer":"今年度の植栽の予定、今後の予定を含めて申し上げますと、中高木、中高木というのは高さが１ｍ半から３ｍぐらいの木です。それから低木が５０ｃｍから８０ｃｍぐらいです。","voiceIndex":147,"id":"exchange-070"},{"speaker":"山路委員","kind":"提案","question":"そこで、私の考えを提案させてもらいたいのでありますが、ただいまの答弁でもありましたように、目黒川や運河に接した水辺に親しむ水とみどりのネットワークの拠点でもあり、緑豊かな公園でもあることから、この公園をちびっ子が楽しめる公園として考えていったらどうかです。私の考えを申し上げますので、区の見解をまずいただきたいと思います。","respondent":"福田まちづくり事業部長","answer":"したがいまして、お子さんのことも視野に入れながら、この公園ができるだけにぎわって、集客施設にふさわしいものになるように考えたいと考えています。","voiceIndex":149,"id":"exchange-071"},{"speaker":"山路委員","kind":"提案","question":"この公園で季節のよいときに、品川わくわくちびっ子祭りを数日にわたり開催し、さまざまな樹木の名前を当ててもらうクイズや、オリエンテーリングなど、楽しい企画を立て、ちびっ子たちが大いに楽しめる、思い出に残る公園としてもらいたいのです。夏には都会で見られない夏の風物詩としてのホタルを早川町などの協力で見せてあげてはどうか。お考えをお伺いいたしまして、私の総括質問を終わります。","respondent":"福田まちづくり事業部長","answer":"公園の活用の観点から、私からお答えしますが、先ほど申しましたように、この公園は非常に大きな公園ですし、それからお子さんたちにも親しんでいただきたいという趣旨は、委員と私とは全く同じだろうと考えています。","voiceIndex":151,"id":"exchange-072"},{"speaker":"川西委員","kind":"質問","question":"最近の報道によりますと、杉並区を初め、４区ではプラスチック類のリサイクル品目を増やしたり、その積極的な姿勢が伺われております。そういうものについて、予算を割く必要があるのではないかということで、お考えをお伺いしたいと思います。この分別変更を機会に、その組織も改めて見直し、活発ではないとは言いません、１回しか出ていないんですから。とりあえず、それで１回終わらせていただきます。","respondent":"岩崎環境清掃事業部長","answer":"最初にモデル地区の中でいろいろと講習会を何回かやったわけですけれども、その中で出たご意見というのは、まず白色トレイは、今拠点でしか集めていないけれども、集積所で、今、集積所と言わないで、資源ステーションと言っていますけれども、この資源ステーションが１万カ所。","voiceIndex":155,"id":"exchange-073"},{"speaker":"川西委員","kind":"質問・要望","question":"発生抑制。２３区の一部清掃事務組合に出した資料。ですから、先ほど質問した中で、品目を増やしてほしいというのは、発生抑制というのは、常に区民の皆さんに広報等、その他のところでＰＲされているという努力はわかりますから、再生利用の推進ということです。なぜかといいますと、やはり資源が集まらない。それから教育機関等で、どういう分別変更についての教育をしていただけるか、お答えいただきたい。","respondent":"岩崎環境清掃事業部長","answer":"これを間違いますと、まだやってもいないのに、先にプラスチックを可燃ごみの中に入れちゃう人が出てきたりしますので、これは直前に改めて集中的にやるというようなことと、それから事前になぜ平成２０年度に本格実施であるのかという。","voiceIndex":157,"id":"exchange-074"},{"speaker":"川西委員","kind":"質問・要望","question":"次に残されたわずかな時間ですが、公園管理の委託契約について伺います。委託内容と、それからどういう区の組織との連携があるのかということを伺いたいと思います。あるいは登録制で、その中から小さい公園などは管理者を選んでしまうのかということについて伺います。いろいろご要望やご意見についてありましたら、ここへというふうに、区の道路公園課の電話番号ぐらい書いていただく。","respondent":"福田まちづくり事業部長","answer":"それから立看板の件ですが、考えてみたいと思います。思いますが、一方では公園に非常に看板が多いんじゃないか、公園に看板がやたらと目につき過ぎるんじゃないかというような意見もありますので、それとの兼ね合いを含めて考えさせていただきたいと思います。","voiceIndex":159,"id":"exchange-075"},{"speaker":"大西委員","kind":"質問","question":"私が今回、品川区教育委員会に１つお尋ねしたいのが、最近格差社会と言われて久しい状況ですけれども、こういう状況の中で小中一貫教育、施設一体型、例えば今般であれば日野学園が開校され、多くの方々が日野学園に注目し、私は一番競争率が高く、入りたいというお子さんが非常に多かったんではないかと想像しておりますけれども、品川区の日野学園においての小学校。","respondent":"長田教育次長","answer":"日野学園の倍率ですけれども、日野学園の定員に対しまして、結果的にですけれども、小学生のほうはちょうど希望した方がすべて入れたというような状況です。それから、中学生のほうについては、これはちょっと記憶ですけれども、まだ若干の枠はあるだろうと思っているところです。","voiceIndex":165,"id":"exchange-076"},{"speaker":"大西委員","kind":"質問","question":"中学校で３０％を超え、また小学校では二十八、九％になってきているものと考えています。そういう状況の中で、品川区が新たな切り口として、公立の小・中学校に公共交通機関を利用されている子どもさんに関しての通学費の助成を行っても、新たな切り口で子育て支援としてはよいのではないかなと考えるところもありますが、品川区教育委員会のお考えを少しお聞かせいただければと思います。","respondent":"長田教育次長","answer":"そういったことで、あと経済的理由というようなことでは、先ほどちょっと質問にも出ていました就学援助制度というものがあるわけですけれども、こういった部分については学校選択制によるケースというのは対象にならないですので。","voiceIndex":167,"id":"exchange-077"},{"speaker":"大西委員","kind":"質問","question":"私はこの学校選択制を敷いている限りにおいては、この部分の問題は多くの子を持つ親が直面している問題ではないかと思います。どの部分でちょっと難しいのか、具体的に教えていただければと思います。","respondent":"長田教育次長","answer":"実際には、先ほど申し上げましたけれども、経済的な部分での困難者、これは就学援助制度があるわけですけれども、これについては、それぞれの対象となる費目が決まってあります。ですから、少なくとも現状では就学援助費の中では対応ができない。","voiceIndex":169,"id":"exchange-078"},{"speaker":"大西委員","kind":"意見","question":"私はそこは見解が異なるところですが、私は子どもが行きたい、親が行かせたい学校、公教育であって、行かせることが、例えば、自分の近くの学校に行かせたいけれども１クラスしかない。これが６年間続くとなると、クラス替えがない。変化がない教育を望むか、それとも遠方であってもクラスが３クラスある。品川区は１５０万円、商工会議所のほうで１５０万円という金額を出してお配りしている。","respondent":"長田教育次長","answer":"これは小学生用と中学生用、これは両方をつくりまして、一緒に配付をしたところです。さらに、この時期においては校長連絡会の中で、この活動の趣旨を高めようというようなことで説明をいたしまして、さらに全小・中学校についてポスターの掲示もしたところです。","voiceIndex":171,"id":"exchange-079"},{"speaker":"大西委員","kind":"質問・要望","question":"そういう状況の中で一歩踏み込んでいくことも必要ではないかというふうに思いますので、そのようにお願いしたい。これに対して、子どもたちがこのことは考え方としてはどうかと。これは学校の中で当たり前に教育されているがために、そこの先生に伺ったところ、大学でその先生は違う中・高から来たらしいんですけど、この学校の卒業生は大学に入った時点からボランティア活動が当たり前だという認識だと。","respondent":"長田教育次長","answer":"プラン２１の中では学力を上げるということが大きな目的です。それから、社会に十分通用できる人間の育成、こういったものも同時に進めております。","voiceIndex":173,"id":"exchange-080"},{"speaker":"大西委員","kind":"提案","question":"プラン２１の中で学力の向上ということがありましたが、ちなみにこの学校も小中一貫校で、日野学園にも見学に来たと。そして、その部分のほかにはすべて家政婦形式で派遣所からの人を雇って１時間３,０００円とか３,５００円のお金を払ってのサービスはどうかと提案されているというところがあります。そういう現状を福祉高齢事業部のほうではどのようにとらえておられますでしょうか。","respondent":"木下福祉高齢事業部長","answer":"今回の介護保険制度改正の中でお尋ねがございました件は、言ってみれば、いわゆる要支援、新予防給付に該当する方の対応ということになります。","voiceIndex":175,"id":"exchange-081"},{"speaker":"大西委員","kind":"質問・要望","question":"これに関しましては、とあるケアマネージャーはプランはそのようにつくったと。９３歳と８９歳のおじいさん、おばあさんですけど。そうすると今度は１時間と１時間半のホームケアサービスが受けられるようになった。私はそのケアマネージャーとか業者によって大きな差が生じてくるということを品川区福祉高齢事業部はよく認知しておいていただきたいですが、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"現実的な対応というのが極めて重要だと思っておりまして、要支援の方の状態像の中で３０分のホームヘルプというのがなじむかどうかということについては、やはり要検討の要素があろうかと思います。","voiceIndex":177,"id":"exchange-082"},{"speaker":"大西委員","kind":"質問","question":"時間がわずかになりましたので、区長が八潮団地に伺って皆さんに応対されておりました。八潮団地も二十数年を経て、まさしく少子高齢社会となっております。今後どのような形で八潮団地の一団地計画をとらえておられるか。およそこのことに関しましては多くの八潮住民が感心を持たれておることだと承知しております。その点でのお考えを企画ならびに区長のご意見として賜りたいと思います。","respondent":"新美企画部長","answer":"現在は、当面まず取り組むべきこととして、平成２０年４月の八潮小と八潮中学校、隣接する既存の校舎を活用しての小中一貫校のためにどのような設備、施設の改修をすべきかということが１つと、もう１つは今申し上げました都市計画決定について、これは東京都の決定事項ですので。","voiceIndex":179,"id":"exchange-083"},{"speaker":"大西委員","kind":"質問","question":"ちょっと今のではなかなかわかりづらいとろがありましたが、区長のほうからどうでしょうか。","respondent":"濱野区長","answer":"その課題を乗り越えて、高齢社会に対応したまちづくりというものをやっていくし、また、若者がカムバックできるようなまちづくりというものに取り組んでいく。その手前の２つをこれから一生懸命チャレンジしていかなければならないと考えています。","voiceIndex":181,"id":"exchange-084"},{"speaker":"西本委員","kind":"提案","question":"私のほうからは２点ほど質問をいたします。１番目は大井埠頭青空野球場に関して。２点目は長時間保育における親子関係の影響について質問いたします。大井埠頭青空野球場の返還に伴う野球場の代替および設備整備について、提案を含め質問をいたします。初めに、東京都から無償で借りて青空野球場ができた経緯、それから都の契約はどのようなものだったのでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"青空野球場の件についてお答え申し上げます。","voiceIndex":185,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"かなり過去からいろいろな経緯があるようですけれども、区民の野球に対する思い、それから議員の皆様、諸先輩の方たちが野球場をつくるために尽力したということだと思います。そういう形ででき上がった青空野球場ですけれども、利用状況はどうだったのか、お聞きしたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"現在の青空野球場の平成１７年度で申し上げますと、ここは現在無償で使える無料の野球場だということを前提に、平日利用が約５７％、土日、祭日が９４％、平均で約７２％という利用状況です。","voiceIndex":187,"id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"平日で５７％、土日になりますと１００％弱という形で、ほぼ目いっぱい使われているという状況で、ここの野球場がどれだけ親しまれているのか、利用価値のあるところであったのかというのがわかりました。そのＡ面の返還の経緯はどういったものであったのか。品川区はどういう態度で交渉に至ったのかについて説明をお願いいたします。","respondent":"岩田まちづくり事業部次長","answer":"東京都もかなり驚きまして、いろいろ考えた結果、最終的には現区長が局長と最終交渉をしていただきまして、都から品川埠頭に持っている品川南埠頭公園という都の公園を区に無償で移管をするという代替案が引き出てまいりましたので、最終的にはそれでやむなしという経緯です。","voiceIndex":189,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"これはどうしてそうなのかということと、それから、もともとトンネル工事があって、トンネル工事終了後の先のお話もあるんですけれども、こちらサイドとしては、要望ですけれども、できれば品川区に移管して、野球場、それから野外キャンプ場、今はありますけれども、そういうものにできないだろうか。その可能性も含めて、いかがだったでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"この間の今後の予定ですけれども、先ほど申し上げました品川埠頭にあります品川南埠頭公園が来年の４月に区に移管になる予定になっております。区に移管になった後に、来年度中に区のほうで野球場として再整備をする予定になっております。","voiceIndex":191,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"国とか都がそもそも大井埠頭をどういうふうな形で、大井埠頭のコンテナ埠頭再整備事業などもかなり進められているようですけれども、当初の見込みではシャーシ置き場としてもともとＢ面、Ｃ面というのは考えていなかったと思うわけですけれども、それが急にこのような状況になってしまっているというのは、やはり国や都の、要は国や都の見込み違いというのはなかったのかどうか、その辺はいかがでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"施設配置やなんかはここで決めていくわけですけれども、ご案内のとおり、国際港として世界を相手に熾烈な競争をしている港湾行政ですので、東京湾と横浜港の再生に日本の発展がかかっているということで、港湾計画は大きく変更になってあります。","voiceIndex":193,"id":"exchange-089"},{"speaker":"西本委員","kind":"提案","question":"品川区の立場としては、品川区の中にあるわけですから、ぜひ安全面等々を強く主張していただきたいと考えています。その中で、次に野球場の拡充のために幾つか提案をしたいと考えています。そうすると、利用数というのは当然ながら低くなるわけですから、ナイターの施設等々を整備していただいて、深夜とか早朝とかの利用を図ってはいかがかなと思いますが、いかがでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"早朝につきましても、現在青空野球場も早朝６時からの開放をしておりますので、そのような開放。需要があればもっとその前からということも検討して、できるだけコマ数を増やすように考えてまいりたいと思います。","voiceIndex":195,"id":"exchange-090"},{"speaker":"西本委員","kind":"提案","question":"野球場がどうなるのかと非常に不安なところではありますが、もし、存続して野球場があるならば、品川区に開放していただくことはできないだろうかということと、それから、先ほどもちょっと出ましたけれども、大井埠頭中央海浜公園内の野球場６面ですけれども、これも都の所有ということになっておりますが、品川区に優先枠を設けることができないのか、交渉の枠がつくれないのか。","respondent":"岩田まちづくり事業部次長","answer":"現在一部使わせていただいている大井ポートグラウンドにつきましては、ここは今サッカーグラウンドが１面と野球場が２面あるんですが、既にサッカーグラウンドについてはシャーシ置き場に使われております。","voiceIndex":197,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、中央海浜公園ですけれども、確かにその経緯はわかりますが、何とか品川区の枠が優先的に使えないだろうかということは、今後継続して要望していただきたいと思っています。それと、品川区民公園内の野球場があります。ここをナイターの設置をしたり、それから、フェンスをちょっと高くするなど再整備を行って利用拡大を図ることはできないだろうかということで、お伺いをしたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"それよりまず、ご指摘の八潮北野球場につきましては、近隣には住宅は全くないところですので、南埠頭公園の開設時に合わせて、深夜・早朝枠については同じように考えてまいりたいと思います。","voiceIndex":199,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"マンションが２棟ぐらいあるわけです。ただ、向きによってはどうなのかなというところがありますので、いろいろな方法をまた考えていただきたいと、継続してお願いしたいと思います。次の質問に移りたいと思います。品川区は全国に先駆けて公立保育園において、平成１１年度からでしょうか。かねてから、特に夜間保育について、適正な利用になっているのかどうかということを質問してまいりました。","respondent":"古川児童保健事業部長","answer":"これが多いか少ないかということにとらえていきますと、大体週に１回ぐらい残業等による利用者がいらっしゃるととらえてあります。もちろん、安易に預けることのないようにということでは、保育園職員、園長も含めまして適正に対応をしていると考えています。","voiceIndex":201,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"これはどうだろうかというふうに、さらに実感しております。その上で、園児の状況についてお聞きしますけれども、保育園自体は家庭的な雰囲気で子どもたちが安心する保育環境になるよう努められていると思いますけれども、恒常的に長時間保育をしている場合、園児への影響はあるのか。なかなか見づらいところはあるかと思いますが、何か気がつく点等があればご指摘をお願いしたいと思います。","respondent":"古川児童保健事業部長","answer":"夜の１０時までということの是非論はさまざまあろうかと思いますけれども、やむを得ない就労等のために預けざるを得ない方々のための保育だと私は考えてあります。一般的に長時間保育が及ぼす子どもへの影響ということでは、２年前でしょうか。","voiceIndex":203,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"品川区の中では影響のないようにということで、かなり考慮されているのではないかなと。今のご答弁の中で質が大切なんだと。それで、利用対象の考え方ですけれども、どのような保護者に対して利用してほしいと区は考えているのか。それから、先ほどもちょっとご答弁いただいておりますけれども、保護者への指導、保護者へはどういうふうな形でご説明されているのかをお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"したがいまして、先ほど申し上げましたように、「開いている施設だから、どうぞ預けてください」と、こういうわけではなくて、あくまでも就労等の状況の中でのやむにやまれぬ親子関係の中に少しでも二重、三重保育を避けたいという思いがこの夜間保育に行ったわけですので。","voiceIndex":205,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、保護者の方たち自身も早く帰るという努力も必要ですし、それから企業側も早く帰れるようにという保証も必要ではないかなと思います。８時半までの延長保育も含めて利用実態を調査して、そろそろ見直すべき時期が来ているのではないか。さらに言いますと、親とのかかわりを希薄にしてしまう保育サービス事業であってはならないと考えますが、今後の考え方についてお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"保育士の資格が国家資格になったことによりまして、子どもの保育のみならず、親への支援、指導というものが明確にその中に記されてありますので、保育士、園長がみずから子どもの最大の利益を守るために親に対して言うべきことは言える環境づくりは必要であると考えています。","voiceIndex":207,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、見直しをして、本当に使用できるような、本当に必要な方に使用していただくような努力をしていただきたいと考えています。その保育園の夜間延長の影響なのか、すまいるスクールは現在６時までになっています。家庭あんしんセンターで実施しておりますトワイライトステイの利用が非常に多くなったと伺っておりますけれども、その利用傾向と実態はどのようになっているのか、お聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"トワイライトステイは家庭あんしんセンターの中で実施している事業ですが、平成１４年度からスタートした事業です。この４年間で少しずつ増加してございまして、昨年度の利用を実人員で申し上げますと、約５０名。","voiceIndex":209,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"このそもそもトワイライトステイの利用対象というのはどういう方に利用していただこうとしているのか。それから保護者に対しては先ほどの数値を見ても非常に多くなっているということでは、保護者の方、利用者の方にどういう説明をされているのかお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"それぞれのご家庭とセンターでの連携した取り組みによって、できるだけ子どもの自立を促しながらトワイライトステイの利用を少しでも減らしていけるような環境づくりを親と子で、そしてセンターもそれを支援していきながら実現したいと思ってあります。","voiceIndex":211,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"すまいるスクールですが、すまいるスクールでの延長保育についての考え方をお聞きしたいと思います。８月２９日の読売新聞の夕刊で文部科学省と厚生労働省が来年度から全国の公立小学校で放課後事業を実施するという報道がありました。非常にこれは後ほど信憑性に欠けるということがあったのですが、この品川区において７時までの延長保育に対する考え方を伺いたいと思います。","respondent":"長田教育次長","answer":"この事業の国や東京都からの説明につきましては、夜間の時間延長に対する要請はなかったということの中から、冒頭申し上げましたとおり、今のところ時間延長する予定はないです。","voiceIndex":213,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問・要望","question":"すまいるスクールの時間の延長については、私は慎重に考えていただきたいと思っています。ですから、働き方も見直しをしなきゃならない部分が当然あるのではないかなと考えています。特に、就労している保護者というのは地域にかかわるチャンスが非常に少ない状況ですので、それが保育園ＰＴＡという形で担っていただくように発展したいと希望しますが、その考え方についてお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"と同時に、さまざまな地域での団体、人々とのネットワークが今後ますます形づくられ、地域における子育てを温かく見守っていくようなコミュニティがまた育っていくように、私どもは子育てという観点からぜひ地域の方々に働きかけていきたいと考えております。","voiceIndex":215,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"ありがとうございました。親子のきずなを深めることというのが非常に大切なことだというふうに思っております。そのためには親子で過ごす時間を保つこと。そして、行政が積極的に発信すべきであるというふうに思っております。当たり前に子育てができる社会環境になるように、一層品川区としての取り組みをお願いしたいと思います。最後に、区としての考え方をお聞きして終わりたいと思います。","respondent":"古川児童保健事業部長","answer":"この両面からさまざまな施策を展開していきたいと考えています。","voiceIndex":217,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問","question":"まちづくりについて、教育行政について、改正介護保険制度について、３点お伺いをしたいと思います。１点は緑の基本計画についてです。区議会への請願の中にも広範な緑地の残る地域を自然のままの貴重な緑として環境教育や自然体験の場に残してほしいというものもありました。緑化政策をまちづくりの重要課題としてとらえているのかどうか、品川区の見解をお伺いしたいと思います。","respondent":"福田まちづくり事業部長","answer":"品川区のような都市には幾つかの要素が必要だと考えています。１つは利便性、それから安全性、それから快適性。緑はこの快適性の要素にとって不可欠ではないかと考えています。","voiceIndex":220,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"そういう都市化の進む品川区ですけれども、２２年前に緑の基本構想をつくり、それに基づいて１０年前の平成８年には緑化推進計画を策定しています。今後の緑被率拡大に向けては市民の理解と協力が必要です。市民とともに取り組むことのできる緑の基本計画の策定が必要となってきますけれども、今後どのようにしていくのか見解を伺います。","respondent":"福田まちづくり事業部長","answer":"このことは大変喜んでいるのでありますけれども、その次の目標がないという、これもまたおかしな話ですので、これまでの緑の伸び方、それから、これまで途中で行ってきたような、例えば屋上緑化の助成ですとか、それから指導要綱等における緑化の指導。","voiceIndex":222,"id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"この中で区長を本部長とするみどり３０推進本部を今年１月に庁内に設置し、組織的に取り組んでいます。緑の施策を全庁的に取り組んでいこうという意志を感じますけれども、品川区の体制を伺います。","respondent":"福田まちづくり事業部長","answer":"全庁的に取り組んでいく。当面はそういう方向でこの課題を追求してまいりたいと考えています。","voiceIndex":224,"id":"exchange-104"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ重要課題ということも含めて、全庁的に、あるいは事業部が率先して取り組んでいただきたいと思っています。この基金には区民が参加をするという仕組みがあるわけですけれども、品川区のみどりの基金は現在４億円ありまして、利息を運用するものであって、市民の参加ということの仕組みがありません。そこで、市民が参加できる基金制度をつくってはいかがかと思いますけれども、ご見解を伺います。","respondent":"福田まちづくり事業部長","answer":"区民の方の参加にはいろいろな方法があるだろうと思います。私どもではみどりと花のボランティアですね。そういうような施策を展開していたり、それはその都市、都市によってふさわしい方法が選択されているのではないかと、今後もそうあるべきだと考えております。","voiceIndex":226,"id":"exchange-105"},{"speaker":"井上委員","kind":"質問・要望","question":"２点目には、品川区のまちづくりについて伺います。品川区のまちは大きく変化をしています。このままでは品川区全体としてのまちの景観がどうなるのだろうかということで心配をしている区民もたくさんいます。取得を目指すということはこのガイドプランでも宣言をされていますけれども、景観行政団体取得は、いつまでにどのように取得をしていこうと考えられているのか、お伺いをいたします。","respondent":"福田まちづくり事業部長","answer":"何カ月後にどこまで行く。こういうような性格のものではございませんので、数字は目にすることができませんが、地域の皆さんと一緒に一生懸命頑張りたいと考えています。","voiceIndex":228,"id":"exchange-106"},{"speaker":"井上委員","kind":"質問","question":"まちづくりの意識を育てる種をまき、水をまいていくことこそ行政の仕事だと思いますけれども、こういったガイドプランを使いまして市民の方たちに広く働きかけていく必要があるかと思いますけれども、ご見解を伺います。","respondent":"福田まちづくり事業部長","answer":"総論的な啓発といたしましては、このガイドプランを策定した後で、そのことを広報しながわでお知らせしたり、現在も区のホームページでお知らせをしている。それから、昨年の１１月には、この策定を記念いたしまして、品川景観フォーラム２００５というのを開催しました。","voiceIndex":230,"id":"exchange-107"},{"speaker":"井上委員","kind":"確認","question":"次は、今マンション紛争がたくさん行われていまして、請願なんかもあるわけですけれども、建物の開発環境指導要綱に基づきまして、事業者は事前協議をして計画を策定することになっています。そして、紛争予防条例により、標識を設置し、１０日以内に住民説明会を実施、開催の報告を区に提出し、建築確認の申請をします。ここでいう事前協議とはどういうことをされているのか、教えてください。","respondent":"福田まちづくり事業部長","answer":"具体的に言いますと、近隣の区民に計画の事前公開と説明義務を求める。それから共用スペース、それから憩いの場の確保、緑化の推進云々とかなり長く続いていきます。そうしたことにつきまして、区と事前協議を行い、協定を締結。そういうものです。","voiceIndex":232,"id":"exchange-108"},{"speaker":"井上委員","kind":"質問・要望","question":"そして２項では、建築主と近隣関係住民は紛争が生じたときにはお互いが自主的に解決するよう求めなければならないという努力義務でしかありません。この条例は１９７８年につくられた条例であり、現在のように建築基準法が建築主に有利に緩和されている時代にはそぐわないのではないかと思われます。市民やまちを守る側に立った紛争を未然に防ぐ条例が必要だと思いますが、見解を伺います。","respondent":"福田まちづくり事業部長","answer":"一般的に条例ですとか要綱、こういうものは時代に即して改正されていくということだろうと思いますし、私どももそのように対応してまいったつもりです。","voiceIndex":234,"id":"exchange-109"},{"speaker":"井上委員","kind":"質問・要望","question":"完璧な計画を事業者は出すことができる。ですから、こういったところは今のような状況、大きな空き地があったり、工場跡であったり、道路の前であったりというところでは、総合設計だとかいろいろな建築基準の緩和がされ、用途地域の地図でははかり知れない２倍ぐらいの建物が建てられるという今の状況があるわけですから、そういったことも区民の声をぜひ聞いて取り組んでいただきたいと思います。","respondent":"長田教育次長","answer":"許可申請の内容、つまり旅館業法における業務内容の適否に踏み込んだ判断は困難だということを思っておりまして、営業許可に当たっては教育環境の保持ということに十分留意をしていただきたいという旨の意見を述べたところです。","voiceIndex":236,"id":"exchange-110"},{"speaker":"井上委員","kind":"質問","question":"そのような意見を述べていただいたということですけれども、今までの運動の過程の中で私が学校関係者に直接お聞きしましたら、「私たちは公務員であり、中立な立場でなければならない」とおっしゃっていました。しかし、公務員といっても、子どもの教育環境を第一義に守るべき役割の人の発言として適切なのかということを疑問に思いました。その点について、改めて見解を伺います。","respondent":"長田教育次長","answer":"スーパーホテルに関する校長を初めとする教員の対応ですけれども、校長、教員、これは他の公務員も同じですけれども、公正中立の姿勢を堅持することは、どのような場合でも求められることです。今回も例外ではございません。","voiceIndex":238,"id":"exchange-111"},{"speaker":"井上委員","kind":"質問","question":"その中で建築計画は近隣の方にしか情報が伝わらないということで、複数の学校に相談したところ、教育委員会から何らかの指導があったようで、協力を得られなかったという話も届いているんですけれども、その辺の真意のほどはいかがでしょうか。","respondent":"長田教育次長","answer":"教育委員会の指導ですけれども、私どもが聞かれれば、公正中立の部分に注意をして運動というか、かかわるようなことは申し上げますけれども、この件に関して教育委員会が、例えば署名云々だとか、そういうようなことをやってはいけないとか。","voiceIndex":240,"id":"exchange-112","title":"町会・自治会支援"},{"speaker":"井上委員","kind":"質問・要望","question":"問題が起こってから対応するのではなく、どんな問題が起こるかということをイメージして対応していくリスクマネジメントの考え方をぜひ品川区や教育委員会に強く求めたいと思っています。続いて、これまでの教育行政について伺います。子どもたちが地域で友達関係が築けなくなる。あるいは、町会や警察の方から伺った話ですけれども、通学距離が遠くなることで事故や犯罪の危険性が高まるというものです。","respondent":"長田教育次長","answer":"こういったような部分があります。こういった部分に対しまして、それぞれ学校経営等の専門分野の方４名の方に委員になっていただいて、そこの専門分野の中からそういった課題に対する検討をしていこうということで、これから始める予定です。","voiceIndex":242,"id":"exchange-113"},{"speaker":"井上委員","kind":"質問・要望","question":"学校に関する専門的な視点で評価をする専門外部評価委員ということで導入されたということですけれども、学校運営がだれのための学校運営なのかという視点が一番私たちは大切だと思っています。そのためには子ども自身が評価をする仕組みがここに求められるわけですけれども、子どもたちの評価を導入することについて、見解を伺いたいと思います。","respondent":"長田教育次長","answer":"子どもが評価をするというようなお尋ねですけれども、現在今申し上げましたとおり、校区の外部評価と、専門外部評価、これを実施しています。そういったことで、今現在においては子どもが評価をするという部分については想定をしてございません。","voiceIndex":244,"id":"exchange-114"},{"speaker":"井上委員","kind":"質問","question":"あるいは教師を見る目もちゃんと育っています。そういう意味では、子どもたちが自分たちの学校をどう評価しているのか、どうあってほしいのかということは絶対に欠かせない視点だと思います。改めて見解を伺います。","respondent":"長田教育次長","answer":"教育の内容につきましては、教育委員会が責任を持って実施をしていくということでご理解をいただきたいと思います。","voiceIndex":246,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問・要望","question":"生活者ネットワークにも日野学園、来年の大井地区の開校を機に、子どもたちの学びの場を検証することを求める声をたくさん聞いています。今まで日野学園、大井地区一貫校の開校、八潮の一貫校とアクセルを踏み続けてきましたけれども、ぜひ少し速度を緩めて、子どもたちの学びの場として検証する時期ではないかというふうに思いますけれども、見解を伺います。","respondent":"長田教育次長","answer":"小中一貫校あるいは小中一貫教育の検証につきましては、もう昨年度から始めてあります。今年度からは小中一貫教育推進検証委員会を立ち上げまして、これも文部科学省の新教育システム開発プログラム、こういった事業の委託を受けまして、３カ年をかけて実施する予定です。","voiceIndex":248,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問・要望","question":"最後に、濱野区長にお伺いをいたします。政策形成で地域の実情に合わせて市民の声を聞きながら取り組んでいかれるとあいさつをされていました。制度改革という大きな問題、さらに、市民の声に配慮して合意形成を図ることが今、新区長に求められていると思いますけれども、いかがでしょうか。","respondent":"濱野区長","answer":"もちろん、できることとできないことはありますけれども、やはり地域の声というのはしっかり聞く必要はあるだろうと考えています。したがって、決して急ぐことはありませんけれども、着実にこの小中一貫校の計画は進めてまいりたいと考えています。","voiceIndex":252,"id":"exchange-117"},{"speaker":"井上委員","kind":"質問・要望","question":"取り組みに向けては、ぜひ区民の合意形成を図りながら、品川区の学校がみんな同じレベルだということで取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-118"},{"speaker":"築舘委員","kind":"質問・要望","question":"品川自民党区議団を代表いたしまして、平成１７年度品川区一般会計、国民健康保険事業会計、老人保健医療特別会計、介護保険特別会計の各歳入歳出決算について、意見表明をいたします。決算特別委員会での我が会派からの総括、款別の質疑での意見、提言を前向きに検討され、今後の政策推進に生かしていただきますよう強く要望し、平成１７年度品川区各会計歳入歳出決算を認定いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-119"},{"speaker":"宮崎委員","kind":"提案","question":"こうした中、品川区には住民の命と暮らしを守る自治体としての役割が求められています。原っぱ公園用地の購入が議会に提案されたのは１９９３年の予算議会です。区の進めるプラン２１は立ちどまって検証を求めています。学校選択制、習熟度別学習のプラン２１の抜本的見直しを強く求めるものです。住民の意見を聞いて区政運営に当たるよう強く求めて２００５年度各会計決算に対する意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-120"},{"speaker":"三上委員","kind":"提案","question":"以下、その理由について、幾つかの要望を含めて申し上げます。安心・安全のまちづくりは目に見える８３運動の定着支援を強化するなど、子どもたちの安心・安全により区民との協同を推進されるよう求めます。最後に、我が党の委員が款別審査や総括質疑の中で求めた意見・提案については真摯に施策の展開に加えていただくよう要望いたしまして、品川区議会公明党の意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":261,"id":"exchange-121"},{"speaker":"土井委員","kind":"意見","question":"濱野新区長のもと、新議員を加えて行われた２００５年度決算審査を終え、品川区民連合は、一般会計、国民健康保険事業会計、老人保健医療特別会計および介護保険特別会計の４決算をすべて認定します。小中一貫校６校構想など、着実な教育改革の実現に向け踏み出した決算でした。８３運動など、子どもの安心・安全の施策が続けられるよう、バックアップと地域とのコミュニケーションを密にされたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":263,"id":"exchange-122"},{"speaker":"藤原委員","kind":"提案","question":"無所属の会を代表して意見表明を行います。以下、その理由と幾つかの意見・要望を申し上げます。平成１７年度の我が国の経済は踊り場状態を脱し、穏やかな回復基調の中で推移しました。今後とも引き続き行財政改革の徹底を図り、より一層区民本位、区民参画の行政運営を推進するとともに、我が会派委員が提案・要望した各項目について積極的に受けとめていただき、区政運営に生かしていただくことを願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":265,"id":"exchange-123"},{"speaker":"三村委員","kind":"質問・要望","question":"生活者ネットワーク・無所属は、２００５年度品川区一般会計決算および国民健康保険事業会計、老人保健医療特別会計、介護保険特別会計、用地特別会計の歳入歳出決算を認定することを表明し、以下、意見と要望を述べします。いじめはどこの学校にでも起こり得る問題です。その他、決算特別委員会での質疑を通して区に改善を求めた点について施策に反映されることを要望いたしまして、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-124"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1272#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":109239,"voices":273}},{"id":"h18-20061108-6","meetingId":"h18-cm11","date":"2006年11月8日","dateIso":"2006-11-08","committee":"区民委員会","time":"午後１時０３分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区民保養所の代替え施設","agenda":"区民保養所の代替え施設","exchanges":[{"speaker":"南委員","kind":"確認","question":"基本的に申込み等々についてはわかったんですけれども、要するに、本人の利用料金というのがここに書いてあるこの料金とは違うわけですよね。違うと思うので、ちょっとその辺を。この業者、旅行会社のプロポーザルで適切な説明はもちろんあったと思うけれども、そういう資料だけで決めたのかどうか、ちょっとその辺を確認したいと思います。","respondent":"鷹倉区民課長","answer":"現地調査の件ですが、各提案があったわけですけれども、その後、絞り込む形で現地調査をしています。なかなかそれぞれすばらしい施設だと。障害者対策のための部分とかが、しっかりした施設だなと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"私はあまり最近暖景苑を利用していないので、ちょっと金額的なことって、予算書の規模ではわかるけれども、具体的に１泊当たりどのくらいの料金なのかというのはちょっとよくわからないので、こことの関係で比較ができないんですけれども、若干高く設定されているのか、あるいは全くほとんど変わらないのか、その辺も教えていただきたいのと、それから。","respondent":"鷹倉区民課長","answer":"そういうところから、今回このように低い４０数％の金額でこのグレードで質の高いサービスを区民の方に提供できるのではないか。こういうところから、暖景苑は三十一年ぐらいたってありますけれども、１つの区切りかなということで終了というふうに判断させていただきました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"私、どうも議会の中でおっしゃるように、最近でこそ出ないけれども、ちょっと前までは、わりとこの暖景苑の利用について随分厳しい意見が出ていまして、区民の方々が利用されると必ず、私も直接聞いたりとか、委員長という立場にあったときも投書までいただいて、非常に私も苦労したことを覚えているんですけれども、そういう点では、ようやくここまで来たかという感じで受けとめているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"始まりはいいんですけど、終わりの絡みがちょっと心配なものですから、意見をちょっと。そういうときは、いわゆる赤字なのかということですね。終わりのほうは、一応１年契約ですけれども、これは当然１年ぽっきりですといくものなのかどうなのかということと、加えて区民の方も３月までということになれば、１月ぐらいに予約を受け付けたら終わっちゃうよという話になっちゃうわけですよね。","respondent":"鷹倉区民課長","answer":"入れかえれば、例えば３つのうち２つはすごい人気があるよと。１つ入れかえればいいと。で、旅行会社の受付についても、評判だということであれば、契約の年数は１年ですけれども、それをさらに継続ということも十分に可能。","voiceIndex":10,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"聞き忘れたので。３部屋というのは、固定のお部屋なんですか。それとも、このグレードのお部屋を３つ使うことを確保している使用権的な確保なのか、この部屋ということで確保なのか。","respondent":"鷹倉区民課長","answer":"その際も、風景の見えるところから山側に行っちゃうと、そういうことはない。風景が見えるところであれば、同じロケーションで少し移るということも全体の運営の中ではあり得ますけれども、いいところはとる。基本はこういう考え方で持っております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"林（和）副委員長","kind":"質問","question":"それぞれホテルを３室ずつ借上げをしているわけですけれども、大人１人が８,４００円とか７,７００円とかというふうにそれぞれのホテルによって金額が違い、大人、子どもと分かれておりますけれども、３室だけを借上げているわけだから、たまたま５人部屋で５人行けば一番満室でいいんですけれども、仮にご夫婦２人で行く場合だってあるわけですね。その点のところはどうなんですか。","respondent":"鷹倉区民課長","answer":"ただ、５名で使っていただければ、さらに旅館側はいいことだと。したがって、その辺をトータルで考えると、私どもの経済性、効率性、そして旅館側も全体の効率性というそこの接点の折り合いのついたところで、こういう運営は考えていかないといけないなと。","voiceIndex":14,"id":"exchange-006"},{"speaker":"林（和）副委員長","kind":"意見","question":"それでも業者側とすればやっぱり多いほうがいいわけだから、抽選というわけですけれども、公開抽選をするわけじゃないだろうし、その点はちょっとどうなんだろう。申込みが５人の人もいれば、２人の人もいれば３人の人もいると思うんですけれども、業者側からすれば、やはり５人のほうをとりたいなと思うわけだよね。","respondent":"鷹倉区民課長","answer":"できるだけ区も業務を軽減するために委託をしているわけですけれども、そういう公正さ厳正さですので、私どももチェックを入れるということで臨んでまいりたいと思います。抽選についての公正性を担保できるように、私どものほうはチェックしていくという形で臨みたいと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"林（和）副委員長","kind":"質問","question":"それと、今まで暖景苑と長年やってきたわけなんですけれども、暖景苑がもう来年の３月で切れるわけですね。暖景苑はその後をどう考えているんですか。これは心配するところなんですけれども。","respondent":"鷹倉区民課長","answer":"具体的な検討に入っているということは、もう既に４月、あるいはさらにその前から「今年度で終わりです」という話はしています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"私が今疑問に思ったのは、保証料というからには、最低の室料というか、この部屋を借りるのに出すよと、１日幾らよというのが決まっていて、５人入ったらもうかっちゃうなと。だけど、３人ばっかりだったらちょっととんとんだな。２人だったら損をするなと、何かこういう料金があるんじゃないかと思うんですよね。その部分に対しては黙って保証するということだろうと思うんですけど、それで具体的な金額は。","respondent":"鷹倉区民課長","answer":"これに区民の方が利用されるとすれば、この明細にあります、大滝ホテルですと通常８,４００円を支払う。ホテルニューアカオだったら通常７,７００円を払う。そして小松家八の坊だったら７,３５０円を払うという形で利用する。","voiceIndex":27,"id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"そういう仕組みだとすると、区の予算というのは、最初は室料をずっとお借りするスタイルで１年間借りるスタイルで予算化をしなきゃいけないんだからしようがない。だけども、満室で使っていくと、不用額が出てくるということになるのかな。それはもう渡しきりなんでしょう。そうすると、渡しきりだとすると、この歳入で入ったのは。","respondent":"鷹倉区民課長","answer":"歳入は入りません。借上げ保証料は契約が成立すると旅行会社に、近畿日本ツーリストにお支払いします。そしてそれから旅館に流れる。区民の支払額については旅館に直接行く。とにかく区のほうに対する歳入にはならない。","voiceIndex":29,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2474#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":11172,"voices":37}},{"id":"h18-20061108-7","meetingId":"h18-cm11","date":"2006年11月8日","dateIso":"2006-11-08","committee":"厚生委員会","time":"午後１時０３分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"社会福祉士を品川区の中で養成するということで、資格者がきちんと増員されていくということは評価できることだと思いますけれども、品川区で社会福祉士をどのようなところに、どの程度配置するという計画がありましたら、その点について教えてください。","respondent":"蓼沼高齢福祉課長","answer":"社会福祉士を養成して、今後区内にどのように配置していくのかというご質問です。今のところ、具体的にどこの施設にどのように配置していくという計画はございませんけれども、今求められていますのは介護保険の地域包括支援センターでの社会福祉士の設置です。","voiceIndex":9,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域包括支援センターが品川区の高齢福祉課に置かれていますけれども、各介護支援センターが委託という形になっていると思いますけれども、今の介護支援センターの中に既に社会福祉士はどの程度配置されているのでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"そのほか、各地区の在宅介護支援センターにも１０名以上、いるところいないところとありますけれども、今後順次資格を取る方が増えてくると考えていますが、今現在、地区センターでは十数名が社会福祉士の資格を所有しております。","voiceIndex":11,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろな介護施設の中でも、介護福祉士の方がある程度経験を積むとケアマネージャを取り、その後は社会福祉士の資格を取ろうということで、かなり意欲的にされているというこことを聞きましたので、ぜひ充実をさせていただきたいと思います。もう一つ、厚生労働省の認可がされるとなると、品川区の財源の部分はどのようになるのか教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"品川区の財政的な支援ですけれども、基本的には社会福祉協議会の自主事業ということで、自主的に取り組むです。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今回１,５００万円が入りますけれども、来年度以降は賄っていけるのかという疑問があります。１００人規模で、この金額の中で、１年間、２年間ならいいですけれども、先々長く考えていったときに運営状況はそれで行けるのですか。","respondent":"蓼沼高齢福祉課長","answer":"このパンフレットにもありますように、費用で入学金、授業料等の歳入が発生しますので、基本的にはこれで十分賄っていけると考えております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最初にそれを聞くつもりはなかったのですけれども、対象者としてまずどの程度の方を考えているのか、経験者が入学してくるのか、それとも全く新しく受ける方を対象に考えているのか、区が直接ではないので答えにくい部分かもしれないですけれども。","respondent":"蓼沼高齢福祉課長","answer":"対象者ですけれども、定員１００人規模で１都３県を対象にするということですけれども、基本的には区内で今現在もろもろの施設等で相談援助業務に携わっている方を中心に入学していただこう。その方たちに資格を取っていただこうというのが基本的な考え方です。","voiceIndex":17,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後に国家試験の受験対策というと、試験に受かることを目的にしているという思いがあったので、そちらよりも基本的には今やっていらっしゃる方の実力アップということで考えていいですか。もう１点、資格を取ることは目的ではあるけれども、資格を取ることだけで満足するのではなく、当然区内に活かしていただくということですね。","respondent":"蓼沼高齢福祉課長","answer":"近隣のところは情報がありませんが、聞いているところでは港区でも実施するということは聞いております。品川区の場合は社会福祉協議会が実施するということで、全国で初めてということになります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"合格率は３０％という、私が知っているのは専門学校に４年間行っていても、合格するのは非常に厳しいと聞いているし、見てきました。本当に土日の体制だけで、受験して合格できるだけの実力を高めていくことが本当にできるのかどうか、余計な心配だと言われればいいですけれども、その辺はどう考えていらっしゃるのか聞いておきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"そのほか実習が必要な方については９０時間の実習を履修していただく。スクーリングのお話が出ましたけれども、パンフレットのコース概要のところにも括弧書きにありますけれども、１年目が７日間（６～８月）、それから２年目が７日間（７月～９月）の土日に開講予定です。","voiceIndex":23,"id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"最初から心配するより、とにかくやってみなければわからないということであれば、非常に心配されることはそれなりにあると思いますので、先々の用心ということは大事なことでありますので、そういったこともきちんと考えた上で出発していただきたいと、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"３１人のうち区部が１７人ということについて、割り振りは具体的に明確に出されたのでしょうか。城南ブロックは城南ブロックの中から何人出しなさいという話になっているのか、その辺の選出の具体的な方法を教えていただけますか。","respondent":"冨岡高齢事業課長","answer":"合計３１人のうち区が１７人、市が１２人、町村２人の積算根拠の関係ですが、団体数割と後期高齢者数割を半々とするという考えで整理したと報告されております。","voiceIndex":31,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"推薦を受けてというのはどうなのか。あくまでも区長会で選出する話になってくるのでしょう。","respondent":"冨岡高齢事業課長","answer":"選挙権は議員にあるです。","voiceIndex":35,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、各区から仮に合計したら５０人ぐらいになった。５０人の中から１７人に絞るという選挙はどこでやるのですか。","respondent":"木下福祉高齢事業部長","answer":"現時点で私どもがわかっているのも、この規約の文言として、このような形で整理されたという内容でありまして、一定の方式を想像いたしますと、先ほど課長あるいは私から申し上げたような内容が考えられるのではないかというのが、現時点での状況です。","voiceIndex":41,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、選挙区は２３区、立候補者は各区から何十人でも出てきてもいい。そうすると、投票する際は、我々が一人ずつ投票用紙を渡されて、それを区政会館か何かに郵送するという方法で投票するという、具体的な話になるとそのような話になるのですか。そうなると、千代田区みたいな小さなところは不利になるとか、不合理だという意見は出てこなかったのですか。","respondent":"木下福祉高齢事業部長","answer":"今、三上委員がおっしゃったように、議員が少ないところはなかなか立てにくいではないかというご意見は当然ありまして、そのことを踏まえて議長会として、どのように今後整理していくかという形になってくるです。","voiceIndex":43,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今のところですけれども、今日配られた資料の第８条の選挙の方法の右のところに、「各区市町村の議会で１人ずつ選挙する」とあります。品川区の場合は４０票あるというわけではなくて、品川区として１票しかないという意味ですか。","respondent":"冨岡高齢事業課長","answer":"品川区は議員が４０人いれば、４０票あるということです。","voiceIndex":45,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"議会で１人ずつ選挙するというのは、ここですと８人がそれぞれ投票権を持っているという判断になるわけですか。","respondent":"冨岡高齢事業課長","answer":"申し訳ございません。薄くなっておりますが、括弧で括ってある部分がＢ案でございまして、説明不足で申し訳ございません。それ以降が案として出てきて、最後に追加案のところで枠が出ておりますので、そちらで決まったです。","voiceIndex":47,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、そこの部分がないですね。追加案の各区で立候補者は推薦するけれども、だれが投票するか全然見えない、決まっていないという意味ですか。推薦者はわかったけれども投票する人間が、三上委員がおっしゃったようにこの文章から理解できないですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう１点、前回もお聞きしたのですけれども、議員の任期がＡ案の２年に決まりました。２年以上やる方もいらっしゃる。そうすると議会の中で推薦が生きていくのかどうかという問題も絡んでくると思いますけれども、欠けたときにまた選挙が行われるのかという問題が、この前もそのつもりで聞いたのだけれども、この前ははっきりした答えが出なかったような気がしたので、もう１回確認をさせてください。","respondent":"冨岡高齢事業課長","answer":"議長に限らず２年間ですので、欠けたときには選挙ということになります。例えば、本人の事情でおやめになることもありますので、そのようなときには。","voiceIndex":52,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３１人というのが２３区ありながら区から１７人という本当に選びにくい数になっていると思いますけれども、先ほどの話では役員の話でというご説明だったのですけれども、なぜ３１人という少ない数、最低の案になったのか、その辺の理由について、わかっているところで教えていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"３１人になったですけれども、市と区との部分がございまして、４２人だと区は全部で代表を出せるけれども市は出せないというところで、最後まで意見の隔たりがあって、最終的に役員の間で６２人の半分の３１人になったと聞いております。","voiceIndex":54,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうことであれば、逆に６２人にして各自治体から全員が代表者として出られる数にして、できるだけ各自治体の声が反映できるような人数にすべきではないかと思うのに、逆に減ってしまうことになったのが理解できないですけれども。","respondent":"冨岡高齢事業課長","answer":"それから財政力の問題もあります。そういうところで６２人というのはすべての市町村が出せますけれども、そういった部分からいたしますと公平性の部分がありまして、そのようになったと聞いております。","voiceIndex":56,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"小さくとも一つの自治体になっているわけなので、本来であればそこの声が反映できる人数にすべきではないかと思いますけれども、一つの区から一人も出られないという広域連合のあり方になってしまったら、そういう中での区民の声というか、特に高齢者の声の反映はどのような形で保障されていくのでしょうか。","respondent":"冨岡高齢事業課長","answer":"例えば、議会ですと、団体の長が議員になるというケースがありますけれども、今回につきましては議員に各議会の議員になっていただいて、それぞれの団体が意見を言えるように協議機関を設けたという経緯があります。","voiceIndex":58,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば品川区から一人も代表者が出ない広域連合になったとします。品川区民の意見が反映されるというところで協議機関がつくられたということで考えるとしたら、協議機関というのはどのような制度で、どのような形で声の反映、意見の集約をされるのですか。","respondent":"冨岡高齢事業課長","answer":"今準備委員会で、具体的にどのような規模で人数はどのぐらいという形で進めているところであります。","voiceIndex":60,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まだはっきり決まっていない部分があるのかもしれないので、質問する側としても何をどのように質問したら見えてくるのかわかりにくい部分があります。その中で保険料も決められ、いろいろなものが決定されていくと思いますけれども、改めて広域連合の中で決定されること、また権限はどのようなものがあるのか教えていただけないでしょうか。","respondent":"木下福祉高齢事業部長","answer":"今回の医療制度改革の中で、後期高齢者７５歳については都道府県単位の広域連合をつくってやっていくという法律が通りまして、私どもといたしましても、都道府県単位ぐらいでなければ医療の部分というのは非常に財政力、その他いろいろな要因が絡みますから。","voiceIndex":62,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、お話のあった規約の第１７条の協議組織の部分は決定事項になると思いますけれども、９月２６日にいただいた資料の中の１９ページに協議組織が出ています。この協議組織は決まっているのですか。１９ページから２０ページにかけて、２０ページに横の図がありますけれども、協議組織の２年と人数も案になっていますけれども、ここは決定したのでしょうか。","respondent":"冨岡高齢事業課長","answer":"協議組織ということでイメージが出ておりますけれども、これはまだ決定しておりません。準備委員会で検討されているという段階です。","voiceIndex":64,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"確認","question":"２０ページの案の中に協議組織の人数が区は６人と出ています。これが決定したのかと思ったので、確認をしたかったのです。これはこれから詰めていくということでよろしいですか。","respondent":"冨岡高齢事業課長","answer":"これから最終的に詰めていくです。別の案が出ておりませんので、この枠内ということが当然あるかと思います。","voiceIndex":66,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者の家賃助成が平成１８年度末で廃止になると思いますけれども、品川区の福祉を見ると、平成１７年度は５１戸の方が利用されているということです。家賃助成がなくなるまでに高齢者住宅とか区営住宅の入居の対応を取る中で困らないようにしていきたいとずっと言われてきたわけですけれども、今、どのような実態になっているか教えてください。","respondent":"冨岡高齢事業課長","answer":"残りの方たちを都営住宅なり区営住宅、もちろん場所が合わなければあっせん制度とかいろいろありますので、そのようなものを利用しながら対応させていただきたいと思っているところです。","voiceIndex":73,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"考え方としてはわかりますけれども、募集期間が１２月１日から７日までということで、応募して実際に入居できるのは４月１日ということです。それから順番が決まって、それからまた１年間待つわけです。そのような制度になっているけれども、入れないというのであれば仕方がない部分があるかもわからないけれども、このようにしてずるずるいくというのは考えるべきだと思いますけれども、どうでしょうか。","respondent":"冨岡高齢事業課長","answer":"空き状況を見ながら、空いているところにどんどんお入りいただければよろしいのですが、空き状況を見ながらということで、私どもも本当に苦慮しているところですが、できるだけ相談をさせていただいて、できればあっせん制度も活用しながら。","voiceIndex":75,"id":"exchange-025"},{"speaker":"三上委員","kind":"意見","question":"あっせんはわかります。それはそれでいいのです。都営住宅にしても順番を決めたら、そのまま順番で入居資格審査しているわけです。必ずしも、入居資格まで全部調べた上で順番を決めるという、確かにそれはわかるけれども、それだったらもっと早めて、４カ月間も待ってから入居が始まりますという考え方は少しでも改善したほうがいいと思います。あっせんはあっせんでどんどんやればいいです。","respondent":"冨岡高齢事業課長","answer":"その間にどうしても移らなければならない方は、先ほど来申し上げて恐縮ですが、別の方法を併用させていただいて対応させていただきたいと考えているところです。","voiceIndex":77,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問・要望","question":"わかるけれども、調査期間をもう少し短くしなさいと言っているのです。何で４カ月も待たせなければならないのか。ずっと調べてきた人の調査もあるわけでしょう。それに変更がある部分を調べればいいだけです。その辺のスピード感というのが求められているはずです。来年度は、３月３１日までではなくて１２月３１日までの制度にします。入居は１月１日からの入居制度にしてもいいのではないですか。","respondent":"木下福祉高齢事業部長","answer":"そのことを踏まえながら、どのような形にすれば早目に結論が出せるかというのは、やはり待っている方のお気持ちもありますから、そのことについては今後検討をさせていただきたいと思います。","voiceIndex":79,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の三上委員の質問に関連しますけれども、今年は何人ぐらい登録して、現状は何番目ぐらいまで入っているのか、去年でもいいですけれども、実績が出れば教えていただけませんか。","respondent":"冨岡高齢事業課長","answer":"登録は大体４０人ぐらいでございまして、平成１７年度の実績は１８人です。平成１８年度は、まだ途中ですが１２人です。","voiceIndex":81,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前に登録したけれども、なかなか入れないという現実の中で、今４０人が登録というのは多すぎるのではないかと思いました。早急に立ち退かなければならない方は、あっせんという話もあるでしょうけれども、なかなかそれができない状況からすると、あまり期待を持たせすぎてはいけないのではないかという気がしますけれども、その辺はいかがでしょうか。","respondent":"冨岡高齢事業課長","answer":"あっせんの部分も当然出てくるかと思いますけれども、４０人という形にしています。","voiceIndex":83,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問","question":"登録順位の高いほうからというのは、もちろんそうだと思いますが、この辺の基準は明確にあるのでしょうか。それから、前年は１９番目で入れなかった人が、また次の年に新たに最初からスタートするのかどうか。それから、先ほどあっせんの方法もあるというところでは、全体の応募者数が何人ぐらいあるのか、あっせんで決まっていく方がどのぐらいいらっしゃるのか教えていただけたらと思います。","respondent":"冨岡高齢事業課長","answer":"は年齢を勘案しながら、順位をつけしています。それから、全体の申請ですけれども、平成１６年は１７５人、平成１７年が１６３人です。その中であっせんで解決した方は、あっせんだけ求めた方も含めまして今年は１０件です。","voiceIndex":85,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"結構、高齢者の住宅は難しいというので、数も大体知れているので、あきらめてしまって申請されない方もいらっしゃいます。あっせんとか、そのような部分で道があるのでしたら、その辺もぜひ説明をしていただきたいと思います。その辺で、明確な基準がきちんとあるのかどうか。それから、審査をする機関はどこなのか教えてください。","respondent":"冨岡高齢事業課長","answer":"明確な基準を点数化して審査会でやっております。それから、機関というのはだれが携わるかですが、民生委員に委員をお願いして、あとは内部の課長級、幹部職員です。","voiceIndex":87,"id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"順番が回ってきたにもかかわらずいろいろな理由があって断れる方がいらっしゃると思いますが、やはり自分の地元の地域ではなかったという理由が一番多いのですか、ほかの理由があるようでしたら教えていただければと思います。","respondent":"冨岡高齢事業課長","answer":"一例ですけれども、狭すぎるという理由も実際にあったと聞いております。６５歳以上の高齢者ですので、やはり住み慣れた地域がいいということがほとんどの理由です。","voiceIndex":89,"id":"exchange-032"},{"speaker":"三村委員","kind":"質問","question":"４０人の枠の中に入ったけれども入れなかったときの精神的なダメージを考えると、住宅を三つぐらいに分けて、その地域をメインに入居するのか、どこでもいいから入りたいということで、希望の仕方で地域を限定するなどの方法を取り入れ、実際に入れる人数と登録人数を近づけていくことは可能かどうか、その辺について伺います。","respondent":"冨岡高齢事業課長","answer":"各地域にありますので、その中で、例えば荏原地区が空いたら次の順番の方に入っていただきますが、「私は大井地区でなければだめです」とおっしゃったら、次の方に行くという仕組みになっていまして、全体的に地域を分けるというのは。","voiceIndex":91,"id":"exchange-033"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"三村委員","kind":"質問","question":"一番最後の自殺対策について、お伺いしたいと思います。自殺対策基本法の中では自殺未遂者の支援、自殺近親者の支援、それに並んで民間団体活動の支援という項目も入っているかと思いますけれども、品川区の今後の方向性のところにはそういったところが見えにくいのですけれども、どういった方向で考えていらっしゃるのか、その点についてお伺いできればと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"一般的なうつ対策ということでやってきたわけですけれども、自殺ということについて、特に力を入れてということでもない部分がございました。今後は、それをテーマとして取り上げていき、また共同の対策としまして検討できればと考えております。","voiceIndex":97,"id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"自治体の電話相談とか、昼間の時間だけとか、労働者にとっては利用できない時間帯であったりしますけれども、時間帯などについてはどのように設定されているのでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ただ、対応するべき主体が、区レベルで行うべきなのか、あるいは東京都レベル、民間の方々と協力して行うべきものかと、これは民間の方々のところで命の電話のようなことを既に行っているところもありますので、そのような状況を検討しながら。","voiceIndex":99,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"品川区の精神保健の現状と実績のところでお聞きしたいのですけれども、精神疾患を抱えた家族というのは、かなり悩みながら日常生活を送っていることが多いと思います。その中でも、なかなか病院に行けないという患者がいらっしゃると思います。そのような場合、ドクターが必要でれば家庭まで訪問してくれるということをお聞きしたのですけれども、その辺の状況がどうなっているのかお聞かせください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"３所におきまして、３回あるいは４回程度以上の実施をしておりまして、思春期の相談、高齢期の相談、アルコール相談、そして一般の精神保健相談が４回、このような形で実施しています。","voiceIndex":101,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は保健所の対応で本当に救われる方が多いのではないかと思います。知らないために利用できないことがないように、ぜひ広報はしすぎることはないと思いますので、お知らせをしていただきたいと思います。それともう一つ、精神の手帳保持者が９６０人ということですけれども、手帳を取ることによってどのようなメリットがあるか教えていただけないでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"都営交通の割引あるいは公共施設の入場料等の割引があります。","voiceIndex":103,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今回いただいた資料の中で、保健相談事業の中の心の健康相談の関係ですけれども、例えばこのような相談者というのは、基本的には大人の方が対象と考えていいのですか。児童・生徒は心の相談という意味では引っかかっていないのかというのが。","respondent":"倉橋品川区保健所保健サービス課長","answer":"何もついていない心の相談というのは、一応成人といいますか大人の方が対象ですけれども、専門医相談、そのほか含めまして、児童思春期の心の相談も各所で３回実施しておりますし、家族会・勉強会などでも思春期の対応をしております。","voiceIndex":106,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ああいう中で心の問題に引っかかってくるケースは絡まないというのが気になってこれを見させていただいていたのですけれども、本当に心配になってそういうところに電話してくる児童・生徒を考えたときに、その子どもはどうやって後先を見ていくのかというのは、その部分は保健所は絡まないのか、それとも何か連携を取っていらっしゃるのか、その辺の考え方が違うのか、もとが違っていたらごめんなさい。","respondent":"倉橋品川区保健所保健サービス課長","answer":"教育センターとは直接照会という形でのやり取りはございませんけれども、こちらのほうに保護者や本人から相談があれば対応しております。先ほども申しましたとおり、児童思春期の相談という形での専門相談、それから家庭訪問などが主な私どもの対処方法です。","voiceIndex":108,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"気になるのは、例えばそういうところへ電話した子どもがキレるとか自殺ということに結びついていなければいいですけれども、その中だけで対応仕切れているのか、教育センターの中で十分対応仕切れているからいいですよという話なのか、つながりを持たないでいいのか気になっているところですけれども。","respondent":"倉橋品川区保健所保健サービス課長、青山品川区保健所長","answer":"私どものほうで主に担当しているものは、やはり専門医ですので、精神的な疾患に基づいた症状が出ている場合、学習あるいは教育上の問題なのか、あるいはベースに精神疾患によるものなのかというのがなかなか判定しづらい。そのようなケースについては、今後教育センターと連携を強めまして、向こうから保護者の方にお薦めいただいて、保健所等に相談行くようにというつながりをつくっていただいたり。","voiceIndex":110,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"一昨年の厚生委員会で北九州市に行ったときに、児童相談所の中に電話を受けるところがありまして、そこでどのようにつながっているのか疑問を持っていたところがありました。それから、電話相談が１年間６,７２２件という数字が出ていますけれども、土日を外していくと１日に二十五、六件になると思います。この対応はどのようにやっているのかと、数字だけを見たときに思ったのですけれども。","respondent":"倉橋品川区保健所保健サービス課長","answer":"短いものでは数分で終わってしまうものもありますけれども、場合によっては３０分とか１時間程度対応しているものもあります。確かに、保健師としてはかなりの労力を取られているという実情です。","voiceIndex":113,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"変な言い方になって、対応仕切れているのですかという意味で、この件数でいくと非常につらいのではないかと思ったのです。現状は対応仕切れているのならいいですけれども、非常につらいのではないかと。","respondent":"倉橋品川区保健所保健サービス課長","answer":"大変、やりくりは難しいところですが、今後も十分に対応できるように配置等を工夫してやっていきたいと考えております。","voiceIndex":115,"id":"exchange-042"},{"speaker":"木下委員","kind":"質問","question":"私も自殺の件についてお聞きしたいと思います。私が気になるのは、意外と自殺というのは連鎖というわけではないですけれども、子どもたちがいじめられて自殺する。先ほどお話ししたように、連鎖反応をできるだけ防止するような部分もあって、今まで以上に、例えば心の問題を相談してくるようにとか、広報部分を大々的にやるつもりはあるのか、その辺を教えていただけますか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ただ、多くの委員にもご心配いただきましたとおり、なかなか量が増えたことに対する対応がやりくりしないといけないという状況ですので、日常の対応を大事にしながら、基本的な対応を損なわないように工夫してやっていきたいと考えております。","voiceIndex":117,"id":"exchange-043"},{"speaker":"木下委員","kind":"質問・要望","question":"ですから、次の広報紙に大々的に自殺に待ったをかけるようなものを載せたり、いろいろな相談場所を載せたり、例えば人数が対応できないのであれば、予算要望をすれば必要なところにはお金を回すのは当たり前のことですから、そのような形でやっていただきたいと思います。そのような形でのタイムリーな予防処置は考えているのでしょうか。","respondent":"谷田部健康課長","answer":"今、法律の制定を受けまして国が動き出し、また都道府県でも連絡会議をつくります。区といたしましても、国や都の状況を見ながら、住民に身近な区としてどういったことができるか、これから十分検討していきたいと思っているところです。","voiceIndex":119,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか教えていただきたいと思います。明らかに病院に通わなければいけないというのではなくて、その前段の人たちのほうがかなり大きい母数を持っているのではないかと思いますが、その辺の把握はどのようにされているのか聞きたいと思います。","respondent":"倉橋品川区保健所保健サービス課長、青山品川区保健所長","answer":"どのようにすれはうまくいくというのは、なかなかお答えしにくいところですけれども、やはりきちんと一つ一つ丁寧に対応していくというのが基本かと考えております。そういう点では、適切に対応されることによって精神疾患に陥いることを防ぐことは、十分可能であるだろうという考え方に基づいて、私どもは行政的な対応をやっていく必要があるのではないかと考えています。","voiceIndex":121,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"そう考えていくと、４ページの施策のイメージ図は、もう少し肉づけができるのではないかと思います。最終的に児童と書いてありますけれども、本当はお腹の中、もしかしたら親にも入ってくるかと思いますが、そこから高齢期、亡くなるまで長いライフスタイルのステージを全部考えたときに、例えば健康課がやらなければいけないというようなことも考えないともったいないと思いますがいかがでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"下に書いてあります民間機関との連携、それから教育委員会、それからこの図で確かに家庭という意味の部分が表しきれないために表現してございませんけれども、いろいろな要素が確かに絡んでくるというご指摘はそのとおりですので、今後。","voiceIndex":124,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"これからいろいろ肉づけをしていただきたいと思っています。今日は心の健康ということでご説明をいただきましたけれども、それ一つ取っても、一生をどのように考えていくかという視点でいろいろな事業が展開できる。要は全部つながっているというところが見えて、そうするとかかわる人たちもそのような視点でかかわれるようになってくるかと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-047"},{"speaker":"三上委員","kind":"質問・要望","question":"簡単におわかりになれば教えていただきたいと思います。２ページの区内精神科医療機関ということで、このような形で載っていますけれども、武蔵小山駅のそばの施設で、最近病棟から退所したという形でそこがなくなったのか、建て替えなのか、何らかの動きがあったのか、そのようにおっしゃる方がいたものですから、何か情報を聞いていらっしゃることはありますか。","respondent":"青山品川区保健所長","answer":"精神科病床ではなくても、必要な場合には、一般病床の中で入院等の対応をしていくということをお約束いただきました。そのような形で、今、各精神病床の維持が非常に難しくなっている状況があります。","voiceIndex":127,"id":"exchange-048"},{"speaker":"三村委員","kind":"意見","question":"そのような社会的に２４時間テレビが見れる状況が、本当に子どもたちにとっていいのか、２４時間お店が開いている状況が子どもたちにとっていいのか、区だけで取り組める問題ではないというのは重々承知していますけれども、できるところからでもいいので、社会的な状況を変えていくことも視野に置いて活動していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":41353,"voices":132}},{"id":"h18-20061108-8","meetingId":"h18-cm11","date":"2006年11月8日","dateIso":"2006-11-08","committee":"建設委員会","time":"午前１１時０４分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"では、(1)第１７回東京都道路整備事業推進大会","agenda":"では、(1)第１７回東京都道路整備事業推進大会","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"事前に大会の内容というのは配付していただけないものかと。改めて事前に大会の決議内容というのが知りたいと思いますので、それができないものかどうかというのを改めて確認したいんですけど。","respondent":"阿部都市計画課長","answer":"事前に決議案等とか、そういうものをお配りできないかということだと思いますけれども、これにつきましては午前中に、先ほど申しましたとおり午前中に役員会で決定して、それを午後の大会に諮るですので、事前に配付することは困難です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"この道路大会ですが、３環状線整備を掲げてきており、内容もそちらに重点を置いてきている。これは、我々の考え方と違っているんですね。議会運営委員会でも議論しましたが、委員会として参加するとなっていますが、住民との関係では難しい。ですので、今回は参加できません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤田委員","kind":"質問","question":"議会運営委員会で協議したということですが、その結果はどのようなものだったのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"藤田委員","kind":"質問・要望","question":"ご判断をお願いしたいですね。大会参加は、議会で決めたことなので、このことは尊重していただきたいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松澤委員","kind":"提案","question":"議会運営委員会で、提案はされましたが、まだ、決定していませんので、今回は参加するべきだと考えますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"確認","question":"議会運営委員会の確認については、結論は先延ばしになっている。昨年も道路大会後の委員会で議論しているんですね。その時の築館委員長からは、理由があれば事前に言ってもらえれば、という話しでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"確認","question":"全会一致が原則だと思うんですよね。議会運営委員会の結論が先送りされているので、昨年の委員長の確認に基づいている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"資料の事前配布についてなんですが、昨年もお願いしたんですけれど、区としては、働きかけはしたんでしょうか。委員が不参加の場合は、その足りない分の穴埋めは職員の方が行うのでしょうか。","respondent":"阿部都市計画課長","answer":"もう１点、動員の件ですけれども、一応、決議としては全体で行いますが、参加者の不足分については、こちらで補うかたちになります。","voiceIndex":15,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"基本的には委員会での参加についても協議していただきたいと思います。議会運営委員会にかけて、議論しましたが、委員会としても議論することをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"ほかに何かございませんでしょうか。ないようですから、私から一言、お願いをいたします。次回、定例会の会期中の委員会の中で、２日目の委員会終了後に行政視察の報告会を行います。その他を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":3424,"voices":22}},{"id":"h18-20061108-9","meetingId":"h18-cm11","date":"2006年11月8日","dateIso":"2006-11-08","committee":"文教委員会","time":"午後１時０４分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"大井地区小中一貫校の愛称","agenda":"大井地区小中一貫校の愛称","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"決まったことだから、もう議論するという話じゃないんですけれども、今の説明を聞いていると、関係者はＰＴＡ、同窓会、校長だけれども、原という名前が一つも出てこなかったんですけれども、原小学校の関係者は出ていたんでしょう。","respondent":"市川庶務課長","answer":"原にしても、伊藤にしても、ともに古い町名を冠した名称ですので、私としても、片方の名称が出るわりには、と思ったんですけれども、理由をしかと聞いたわけではございませんが、原というご提案は一つもございませんでした。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"まあ、決まったことに別にどうこう言うつもりはないんだけれども、これからまだできてくるわけで、八潮の場合は、もうほとんど決まるのかもしれないけれども、そういった意味で、関係者の方々は、原にもうちょっとこだわってほしかったなと。別に、原のほうがいいとか、伊藤のほうが悪いとかいう話ではないんだけれども、そういう印象を持ちました。","respondent":"市川庶務課長","answer":"ただいまいただいたご意見に関連することといたしまして、この関係者の方々は、一つは学校の名前なので、子どもたちに親しみやすく、呼びやすい名前、それから地域の人が自然に受け入れられる名前。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと、僕も途中から文教委員ということなので、以前の日野学園のときの経緯が、不勉強なものでちょっとわからないんですけれども、現行法では、正式に小中一貫校というのは認められていないので、愛称ということになると思うんですけれども、具体的には、今回決まった名前はどういうときに使われて、愛称とは別の名前とのすみ分けというか、具体的にどのように行われるのかということがわからないので。","respondent":"市川庶務課長","answer":"ですから、原則と例外という言葉づかいは厳密ではないかもしれませんけれども、私どもは、原則として愛称名を取り扱っていくという考え方です。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"の平成１８年特別区人事委員会勧告の概要","agenda":"の平成１８年特別区人事委員会勧告の概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"これまでの人事委員会、あるいは人事院を含めて、比較企業規模をもっと小さいものにしろと、ひところ言われて、今回、１００人から５０人になったんですけれども、今回の見直しで、全体としては、民間との較差が０.４１％あるというんですけれども、事業規模を縮小したことがどう影響したかというのは出されているんですか。","respondent":"市川庶務課長","answer":"ただいまご質問いただいたことに対するストレートな答え、説明というのはされてございません。ただし、こういう言い方がされております。今回、企業規模を１００人から５０人に下げて、従来と同じような実態調査、民間給与との比較の調査がきちんとできたと。","voiceIndex":16,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、０.４１％ですから、ドラスティックな変化はなかったというのはよくわかるんですけれども、そこら辺ははっきりしていないけれども、そこそこの結論が出たと、わかったような、わからないようなあれですけれども。それから、労使交渉の結果は最終的にどんな状況なのか、わかっていたら教えてもらえますか。","respondent":"市川庶務課長","answer":"最終的に、結論が出ましてから、各区での条例提案ということで流れていくわけですけれども、現在のところ、例年の例に合わせて、私ども区側としては、第４回定例会の会期中に条例提案をさせていただいて、しかるべきご審議をいただくということで、今、準備を進めているです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"労使の話し合いのほうはどうかということなんです。","respondent":"市川庶務課長","answer":"準備を進めているということは、労使交渉が行われている最中だです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"５０人を超えているという幼稚園は、品川区内にはないと思うんですね。都内でも、総合的に大学の付属の幼稚園とか、そういうことから言うと、全体の職員の数で言えば５０人を超えているという付属、継続というのはあるんでしょうけれども。それについては、何とも言えないかな。","respondent":"市川庶務課長","answer":"その一方で、公立幼稚園の給与体系につきましては、小中学生の教員給与体系に準じてというような考え方があります。その意味で、東京都の場合、東京都の公立小中学生の教員給与の体系の中に準じたもので、ひとつは考えられている。","voiceIndex":24,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"教育長は、あまり民間の校長というのは歓迎されていないと漏れ伺っていますけれども、校長に限らず、今、品川区ではまちの人から学ぶ授業とか、そういうのをやっているわけで、公務員として雇うということ以外にも、これは入れていくべきだと思うんですけれども、これは公務員の話になるんですけれども、そういう点については、どう考えていらっしゃいますか。","respondent":"河野指導課長","answer":"教員採用に関しては、現在、人事権は東京都ですので、直接我々が関与しているわけではございませんが、いわゆる社会人枠という枠を設けて、特例選考を実施しております。","voiceIndex":26,"id":"exchange-008"},{"speaker":"築舘委員","kind":"意見","question":"何となくわかった感じはしますけれども。それが週刊誌に出ていたんですよね。そうすると、それはどういうことでそうなのか。ある意味では、いいことなんでしょうけれども、先生の数が多いということは、ある意味では、効率的ではないということにもなるかもしれないんですが、その辺の経緯というか、見解というか。","respondent":"河野指導課長","answer":"したがいまして、教員一人当たりの児童生徒数というのは、その区にある学校に勤務している教員で、その区の児童生徒数を割ったという数字になるわけですが、実態としては、それぞれの各学級の児童生徒数が少ないから、たまたまそういう数値が出るのであって。","voiceIndex":30,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"その他でやることか、どうかあれなんですけれども、いじめによる自殺の問題がものすごい勢いで広がっているんですが、この問題での取り組みと、品川区での実態があったら、教えてもらえるとありがたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"多分区側も、文部科学省がゼロだから、この間、ゼロで報告がいっているんじゃないかと思うんですけれども、この問題に対して、いじめの件数が問題というよりも、こうした場合にどう対応していくのかというのが、今大事な問題だと思うので、５件にわたって、今取り組んでいるということで、何となくほっとはするんですが、そこら辺については、いかがなんでしょうか。","respondent":"河野指導課長","answer":"私ども、今、手元の資料では、平成１２年度から平成１７年度にかけての、いわゆる文部科学省が実施しております問題行動調査の中のいじめという部分で、区が報告として上げた件数ですが、平成１２年度が１６件、平成１３年度が１７件、平成１４年度が１３件、平成１５年度が９件。","voiceIndex":40,"id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"深くはやるつもりはないんです、アウトラインだけちょっと。今の点は、私が勘違いしていたので、失礼した点があったと思います。東京新聞で、都内の中学校のある女性教師の発言として紹介されていたんですけれども、その中では、「最近は、いじめを教師に相談できない雰囲気になっている」と。これは品川区のことを言っているわけではないんです。これを聞いて終わりにします、長くなって申しわけありません。","respondent":"河野指導課長","answer":"その辺の考えていることで、私の私見になりますが、私は、学校のほんとうの信頼というのは、いわゆる問題行動であるとか、いじめ、いじめもどきも含めて、そういうことがあったということを隠して、件数が少ないからいい学校ですよということをアピールすることではなくて。","voiceIndex":43,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ちょっと一つ、二つ、質問じゃなく、要望だけさせておいてください。１０日に研修会をやるということだから、校長に、絶対に校長は自殺するなと。ある意味、連鎖反応的な部分はあるし、大人は範を垂れるべきだから、研修会の折には、何があっても校長は自殺するなと、そこだけは伝えてほしい。それを教育委員会も検討を加えてほしいと思いますので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":15143,"voices":47}},{"id":"h18-20061108-5","meetingId":"h18-cm11","date":"2006年11月8日","dateIso":"2006-11-08","committee":"総務委員会","time":"午後１時０３分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"済みません、勉強不足なので教えていただきたいんですが、コンピテンシー手法による面接というものが私はよくわからないんですが。","respondent":"榎本人事課長","answer":"過去の具体的な行動実績に基づいて、その人の能力や資質を人材を選抜するときに使おうというもので、そういうもので面接をしていこうという形で、実際に特別区のＩ類の選考についても、そういう点が入って面接をしているというものです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"そうすると、品川区でももうある程度実施されているということでしょうか。","respondent":"榎本人事課長","answer":"品川区についても、それを参考に、過去の行動を掘り下げながら質問していくという形で取り入れております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"山村委員","kind":"質問","question":"過去の行動を掘り下げるというところがよくわからないんですが、どういう質問をするのでしょうか。","respondent":"榎本人事課長","answer":"例えば運動部とか、文化部とか、何でもいいですけれども、そういう組織のもの、ゼミに属しているもの、そういうものに対して自分がどうしてそういう活動を始めて、どういう成果を上げて、何を得たのかという形をわりと深く聞いていくという形で。","voiceIndex":12,"id":"exchange-003"},{"speaker":"山村委員","kind":"質問","question":"これでちょっと気になったんですけど、いわゆる圧迫面接と言われるようなことはやられていないんですか。","respondent":"榎本人事課長","answer":"圧迫面接というのはどの辺の圧迫かというのはあるんですけれども、特にそういう形ではやっておりません。もちろん受けられて区の職員になる方もいますし、採用されないで落ちる方もいますので、落ちた方のイメージが悪くなるような形での面接は行っておりません。","voiceIndex":16,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"私も初めてこういう報告を受けるもので、基本的なところがよくわからないので教えていただきたいんですけれども、１つは特別区人事委員会からの勧告ということですから、組合に対するこういう方向ですよと指し示して話し合いをするという体制になっているのかどうか、その辺の基本的な、組合との関係でいったときの流れを教えていただきたいのと、それからもう１つ。","respondent":"榎本人事課長","answer":"その後、組合のほうに対しましては、特区連および清掃労組に対して同じように説明をして、それについての意見要望等がありますので、その段階で出てくるという形です。","voiceIndex":18,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問・要望","question":"組合との関係なんですけれども、さっきお話しされたのは特別区人事委員会、いわゆる大きな枠組みの中での流れだったんですけれども、これが品川区におりてきて、区のほうは区の職員労働組合とも論議そのものがあるのかどうか。あるのであれば、現状としてどういうものがあるのか、教えていただきたいんですけれども。","respondent":"榎本人事課長","answer":"この人事委員会の勧告そのものを説明するというものではありませんけれども、これからの実施にあたっての賃金要求活動という中での要請等を受けて、その中でやりとりをしていくという思いでやっております。","voiceIndex":20,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"下げたことによって昨年までの統計とは当然違いが出てくるものが、さっき言っていた０.４１％、１,７８８円の差ですか。このことなのか、１００人規模で調べたときと、５０人規模に落としたときのこの差をどういうふうにとらえるのか、ちょっとそこだけ教えていただけますか。","respondent":"榎本人事課長","answer":"今、このマイナス０.４１％というのは、５０人規模に落としたときの公民較差という形でございまして、従来どおりの１００人規模でやった場合につきましてはプラス０.４％、ボーナスにつきましてはプラス０.０５％という形で、人事委員会のほうから報告を受けております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"菊地委員","kind":"意見","question":"１００人規模だとプラスになるということなんですね。組合との、直接的に働く皆さんとの話し合いはこれから進んでいくんだということですけれども、実際にこの間、サラリーマン等であったり、それぞれの民間企業に働いていても、行政で働いていても同じことなんですけれども、かなり厳しいということにあわれていることも含めて、働く皆さんとの話し合いのところをしっかりやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはり優秀な人材を確保しなければいけませんし、給与ばかりじゃなくて、いろいろな待遇を含めて、どういうふうに職を求める人からは評価されているのかということが１つと、それから、雇用する側も相当の条件に入っているわけですから、やはりここはいい職場だよということをしっかりとお知らせしていくという仕事はどのような仕事をしているのか。","respondent":"榎本人事課長","answer":"やはりその区の説明者の人物を見て品川に来たいと思ったというのが多くて、その場というのはすごく大事にしていきたいと思いますし、今後そういう機会を設けてきちんとＰＲしていきたいと考えていますので、それから、ホームページを見てというのもかなり多くありまして。","voiceIndex":25,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"公ですから限度があるでしょうけれども、そういうことをしないとなかなかいい人が集まらないということがあるのではないかということが１点と、それから、ネット等で、あるいは新聞から始まって、さっきおっしゃったとおり、品川区の魅力があるということは今のところアドバンテージがあるわけですけれども、それをすぐ対応して、本当にいいんだよという受け入れ側がケアしないと。","respondent":"榎本人事課長","answer":"２３区でやっているものについても、時間が足りないとか、もう少し説明を聞きたいとかという意見もアンケート等で出ておりますので、その辺を少し拾いながら、今後も検討をしていきたいと思います。","voiceIndex":27,"id":"exchange-010"},{"speaker":"塚本委員","kind":"意見","question":"インターンシップということ、もう少し枠を広げれば、品川区のやっている催し物にも積極的に参加してもらう。そのためにはまずこういうことをやっていますよということを知らせなければいけませんので、求人活動という意識でもってそういう広報の知らせも必要な時期に来ているのではないかということをお話して、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"今回、特別区人事委員会勧告ということで今、お話を聞いたんですけど、単純な疑問なんですけど、企業規模５０人以上でということで、今まで１００人以上ということですよね。そしてもしちゃんと出すなら、本当に企業対象ということ、民間事業所ということならば、実際に毎年変わっているのかどうか。毎年そういうふうに企業の選定に対して変わっているのかどうか、その辺をちょっとお聞かせください。","respondent":"榎本人事課長","answer":"その中で民間企業関係資料ということで、実態調査のさらに概要版が載っておりまして、今回の事例でいきますと、全部で７４９事業所が調査対象という形になっておりますけれども、この中で企業規模でいきますと、１,０００人以上の企業が２５８社。","voiceIndex":30,"id":"exchange-012"},{"speaker":"須貝委員","kind":"確認","question":"再度確認なんですけど、そうすると、一般的な皆さんが思うなら、例えば５０人以上ならば５０人規模が最低ラインで何社かあって、あと例えば１００人、２００人、３００人、４００人というふうにかなりきめ細かく出ているのか、今みたいにかなりその範囲が広い状況で出ているのか、その辺をちょっと。","respondent":"榎本人事課長","answer":"このリストの中では３区分だけということで、１,０００人以上と、１００人未満とその間という３区分で出ております。それが産業ごとに、例えば製造業ですとか、電気・ガス供給、運輸業ですとか、小売業だとか、それの似たような仕事をしているところという形で出ております。","voiceIndex":32,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの質問で、例えば前年度、人事委員会勧告が出るときに、業種とか会社が変わっているんですよね。","respondent":"榎本人事課長","answer":"失礼しました。抽出の場合、無作為抽出ということでかけておりますので、まず無作為に抽出をして実地調査という形になりますので、同じところもあるかもしれませんけれども、かなり変わっているです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"人事委員会の勧告なので、品川区云々という話ではないと思うんですけど、ただ本来ならば２３区の区民の皆さんも思っている人事委員会勧告、公務員の給料云々というその平均を見るならば、民間との比較をするならば、本来５０人、１００人、２００人、３００人と、そういうきめ細かいところから抽出されて、そして平均給与を出していくという方法が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"というのは、例えば民間に入って、当たり前ですけれども、サラリーマンになって、一生懸命働いて実績を残せば、給料が上がっていったり、同期で入っても差がついていく、大きな差がつくのも当たり前だと思うんですけれども、一方では人事委員会勧告でこの給料のベースがありますよ、しなさいと来ていて、一方では少数精鋭で簡素で、組織運営に向けたとか、あと多様化に対して有能な人材という形で。","respondent":"榎本人事課長","answer":"その後の配分につきましては、それぞれ勤務実績の評価を入れていきなさいとか、目標管理を入れなさいということで、その配分については実績を上げた者に対しては厚く配分していくという考え方が昨今出てきておりまして、昔に比べれば、同期で入っても。","voiceIndex":37,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"その辺については、やっぱり公務員という意味合いにおいては、よくヘッドハンティングとかがあるじゃないですか、民間で。公務員という意味においてはあり得ないことなんでしょうか。","respondent":"榎本人事課長","answer":"今現在の制度はそこまでは難しいんですけれども、実際上、それに近い制度としては、任期付採用と形で、一定レベル条例を整理すれば、任期付採用で幹部職員を採用できるという形も出てきておりますので、それが若干そういう、ヘッドハンティングというほどではないんですけれども。","voiceIndex":39,"id":"exchange-017"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"初めて質問しますけれども、今まで国家公務員の方とお会いする機会が多かったものですから申し上げちゃいますと、私なりの個人的な意見を申し上げますと、品川区は非常に高い、非常にいろいろな面におきましてレベルが高い。私も品川に住んでいてよかったなと思っています。","respondent":"榎本人事課長","answer":"要は区役所のことを聞かれればだれでも一定レベルは答えられるという形の職員、どこの職場にいても答えられるような職員というのを目指してきちんとやっていく必要があると思いますし、そうしないと恥ずかしい区の職員という形になっちゃうのかなと考えていますので。","voiceIndex":44,"id":"exchange-018"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"もう１点だけ。いいことだなと非常に思っておりますけれども、本当に今、お話しされたように、これはちょっと要望が入るかもわかりませんが、部課署だけではなくて、関連のところのことについても区民の方にぱっぱっとお返事ができるように、今までほかの区に比べれば非常にいいというのはわかっておりますけれども、一層のご努力をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問・要望","question":"この関連の工事、以前にお聞きしたときに、補強の指標が０.６になればいいんだというお話があったんですけれども、耐震診断の際に、この建物というのは実際にどれぐらいの強度を持っていたのかというのを教えていただきたいのと、それと耐震補強のかかわる工事のついでにいろいろな改修工事をしてしまおうという感じのものになっていますけれども、これも以前にお聞きしたときに。","respondent":"宍戸施設担当課長、中島経理課長","answer":"Ｉｓ値ですけれども、目標値としては０.７としております。それと、こちら側にあります関連別途工事、これは１,０００万円前後の工事になりますけれども、この９,０００万円も含めまして、これにつきましてすべて区内業者を条件として入札を行っております。","voiceIndex":51,"id":"exchange-020"},{"speaker":"菊地委員","kind":"意見","question":"Ｉｓ値について公表していないと。確かに不安を呼ぶかもしれないんですけれども、ただこの工事を依頼する業者はその数字を知っていて設計をしていくんですよね。要はどの程度の工事をすれば０.７になるかというのは、実際にこれはどこで決めていくのか。","respondent":"宍戸施設担当課長","answer":"耐震補強設計を依頼している設計会社については、当然全部その辺の数値は把握していないと設計できませんから、耐震診断そのものもその設計会社がやっているわけですから、当然把握していますが、工事会社についてはその辺のところは知らせていないというか。","voiceIndex":54,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、少なくとも耐震診断をした業者のところでは、それぞれに設計を担当するところでは知っていますよという話なんですね。そうすると、その前段にあった不安を招くので公表していないというところでの守秘義務とでもいいましょうか、そういったものも契約の中に入っているということになるんでしょうかね。ちょっとそこだけ教えてください。","respondent":"宍戸施設担当課長","answer":"その辺の守秘義務というのは必ず契約の中で課しております。","voiceIndex":56,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"耐震補強ということで４カ所やられるわけですが、実際に設計図面があるわけじゃないのでよくわかりかねるんですが、でもこれだけ窓が多くて、この４カ所だけで耐えられるんでしょうかという疑問もあったんですが、それは設計会社が大丈夫だということでお墨付きをくれていると思うんですが、これで本当に十分だったのか、さらに設計会社のほうでもう少し補強したかったのか。","respondent":"宍戸施設担当課長","answer":"これで十分だです。次に、工事のそれぞれの金額の割り振りですが、全体の金額の約３分の１が耐震補強工事ということで、ちなみに児童センター部分が約６分の１、保育園の改修工事が６分の１といったような配分です。","voiceIndex":58,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう１点だけ。壁がしっかりした構造だということですけれども、建物自体は、ラーメン構造と違って壁構造ということでつくられているんですか。その辺だけお聞かせいただきたいと思います。","respondent":"宍戸施設担当課長","answer":"今申し上げたのは、壁の配置が非常にバランスがよいということで、今、補強量が非常に大きいのは、壁自体が少ないというよりは、壁の入り方のバランスが悪くて補強するケースが非常に多うございまして、この場合は非常にバランスよくもともと壁が配置されていたので。","voiceIndex":60,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"何で改正されたかなんですけれども、その背景を教えてください。","respondent":"野田口選挙管理委員会事務局長","answer":"それで、昨年１年間ぐらいかけて、この「住民基本台帳の閲覧制度等のあり方に関する検討会」ということで幅広く検討してきた経過があります。","voiceIndex":66,"id":"exchange-025"},{"speaker":"藤原委員","kind":"確認","question":"広がったかわりに違反の場合は３０万円以上の過料という形で出たのかもしれないんですけれども、１１月１日からということなので、きょうは８日ですからお伺いしますが、改正後の義務の中の１番で、防止など必要な措置を講ずることの義務化というのは、具体的にどういうふうにしているのかということが１点と、もう１つは(2)で。","respondent":"野田口選挙管理委員会事務局長","answer":"利用目的以外に利用したということですけれども、これについては事後何かのトラブルが起きたときしか、実際問題とすれば把握できないだろうと考えています。","voiceIndex":68,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1736#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":26079,"voices":71}},{"id":"h18-20061109-11","meetingId":"h18-cm11","date":"2006年11月9日","dateIso":"2006-11-09","committee":"自治制度特別委員会","time":"午後１時０５分～午後４時１８分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"新委員の紹介","agenda":"新委員の紹介","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"自民党の山内晃です。この委員会、よくわかっておりませんが、今日、とりあえず視察をさせていただきまして、何かわからないことがあったら質問をさせていただきたいと考えていますので、ひとつよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5606#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":3278,"voices":30}},{"id":"h18-20061109-16","meetingId":"h18-cm11","date":"2006年11月9日","dateIso":"2006-11-09","committee":"街づくり特別委員会","time":"午後１時０６分～午後６時３４分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":3870,"voices":34}},{"id":"h18-20061110-14","meetingId":"h18-cm11","date":"2006年11月10日","dateIso":"2006-11-10","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時０３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地等の活用に関すること","agenda":"公有地等の活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"大田区全体の中で、この特性がそれぞれあろうかと思うんだけども、そのあたりが、わかればで結構なんですけども、行政として、こういう方向性を、例えば品川区のように第三次品川区長期基本計画とか、そういうものがあって、こういう場所ができてきたんで、それにのっとって動いたんだとか、そういうような考え方があったのかどうか、こういうふうに活用されてきた状況というのがわかれば教えてください。","respondent":"堀越行財政改革担当課長","answer":"つまり、地域の皆さんのご意見ですとか、それからそのときに求められているもの、例えばこういった創業支援施設ですとか、そういったいろいろな庁内検討会の中で、施設の必要性等を勘案してつくったわけですが、もちろん立地ということもございまして。","voiceIndex":30,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日出していただいたこの間の「こらぼ大森」以外のところの運営が、どういうふうになっているのかを教えていただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"区民の利用施設については現在直営ですが、平成１９年度から業務委託をする予定だというふうに聞いております。蓮沼小学校、こちらについては、まだ改修中ですけれども、こちらについては障害者就労対策施設、それから共同作業所については民設民営ということで考えているです。","voiceIndex":33,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"インターネットで調べたら、具体的に運営に当たっての提言なんかもしているところを見ると、ものすごくしっかりとした考えを持っているなと思って見たんですが、その準備協議会から、協議会に移るに当たっての提言が３点、ふれあいの広場としての施設づくりで、地域のみんなの活動の場にしてほしいとか、区民が主役の施設づくり、区民と区の共同を基本に考えてほしいとか。","respondent":"堀越行財政改革担当課長","answer":"一応地元のご意見は伺いながら話を進めていったというように聞いております。それぞれ地元のご意見を伺う前に、先ほども答弁申し上げましたけれども、区としての原案をお示しして、それに対してご意見をいただくような形でいずれの場合も進めてきたというように聞いております。","voiceIndex":35,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"区としての原案を示してというところでは、「こらぼ大森」のところの準備組合のような丁寧さはなかったんですかね、準備段階でのというのは。なくて至ったんでしょうかね、ちょっとその辺を教えてください。","respondent":"堀越行財政改革担当課長","answer":"ただ、原案云々の話については、細かいところまでは承知しておりませんけれども、そのほかの施設についても原案を示して、地元の方からご意見を何回か伺いながら進めてきたという点では、基本的には同じものであろうというふうに認識しております。","voiceIndex":37,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できましたら、その後の活用の方向と、もし区民の声とかを聞かれていたら教えていただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"そこまでは、申しわけありませんが、現在までにおいて、そういった意見というのは特に聞いておりません。","voiceIndex":39,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"先日視察した「こらぼ大森」のことをどこまで伺っていいのかわからないので、わかる範囲で教えていただきたいんですけれども、一つは今お話にもありました当日の資料の「運営協議会の流れ」というところで、「平成１４年の６月に旧大森第六小学校施設活用協議会が発足」、こういう資料をいただいたんですけど、この協議会というのは、区とはどういう関係というのか、どこに位置づけられているのか。","respondent":"堀越行財政改革担当課長","answer":"そこのところは、ちょっとつかんではいないんですけれども、ＰＴＡの関係の方ですとか、地元の町会を中心に組織をされておりまして、その方々から意見を伺っていたというように聞いております。","voiceIndex":41,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"おそらく請願とか陳情とか、そういう形ではなくて、何かの位置づけがあって、意見が求められて、みんなでまとめて提言書という形で、そういう関係があるのかなというふうに思って、もしわかる範囲で結構ですけど、教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"区との関係につきましては、連絡を調整しながらやっていたのではないかと思われます。","voiceIndex":43,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"区のほうから地域へどういう要望があるのかみんなで話し合って、一定まとめてほしいみたいな、そういう形でこの協議会というのは、発足されたのか。もう少しそこを教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"その部分については、申しわけありませんが、承知してございません。","voiceIndex":45,"id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"この四つの学校は全部改修となっているんですが、どのぐらいたった建物なのか、その辺のところを教えてください。","respondent":"堀越行財政改革担当課長","answer":"大森第六小学校と羽田旭小学校と北蒲小学校については昭和４７年から、ちょっと幅があって申しわけないんですが、６１年の間という形です。蓮沼小学校については、いろいろと建物はあるんですけど、一番古いのが昭和３５年と聞いております。","voiceIndex":47,"id":"exchange-009"},{"speaker":"中島委員","kind":"質問","question":"相当年数としてはたっている建物なんですね。改修費用というのは結構かかっているんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"申しわけございません。ちょっと、「活用事例」の「施設の規模」のところの延べ床なんですけれども、資料のほうが間違っていまして、全体をあらわしたものではないと思われますので、申しわけありません。","voiceIndex":49,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"今のお話の続きなんですけど、大田区の学校の耐震に対する長期的な考え方を教えてください。","respondent":"堀越行財政改革担当課長","answer":"長期的な考え方については、ちょっとお聞きしてはいないんですけれども、当面改修で１０年から１５年使用して、その後の社会情勢を見ながら、また活用について考えていくという、今のところはそういう考えだというように聞いております。","voiceIndex":51,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"この中で、蓮沼小学校の消防団の資機材倉庫はどれぐらいの大きさですか。","respondent":"堀越行財政改革担当課長","answer":"約６０m2です。","voiceIndex":53,"id":"exchange-012"},{"speaker":"松澤委員","kind":"意見","question":"大田区は随分この消防団に対して、資機材倉庫に対して協力的なんですよね。例えば、前回行ってきましたよね、「こらぼ大森」。あそこで帰り際にふっと見たら、プールは使用されていないんだけど、プールの隣に大きな建物がありまして、「あれは何でしょう」と聞いたら、消防団の資機材倉庫なのね、２階建てで、すごく大きいんですね。どれぐらいあったろう。感想だけ今述べたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、これは一つの住民自治の成功例だと思って聞いてきました。それを振り返って原小学校を見てみますと、品川区にぜひ確認したいのが、そういう同じような状況にあるわけですね、原小学校が。もちろんインターネットに掲示をする、それから町会長に説明をする、回覧板を回す、これは当然のことですからいいんです。","respondent":"堀越行財政改革担当課長","answer":"今後につきましても、先ほど企画財政課長のほうから説明をさせていただきましたけれども、具体的に地域のほうにもっと入りまして、いろいろどういった形ができるのか、詳細についてきちっと地域センターも中心となって、これから地域の方々の意見を聞きながら。","voiceIndex":63,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうときに、本当にその学校の卒業生とか、地域の町会長の方々が自主的に組織を立ち上げてその学校の跡施設をどうするかという検討組織をつくる誘導施策を考えてみたらどうですかということを今お話ししているわけでありますので、今、原小学校のことについては、既に図面も書かれ始めてきましたので、今からではおそいと思うんですが、ただ、最大限、その地域にオープンする交流拠点。","respondent":"堀越行財政改革担当課長","answer":"原小学校につきましては、今回こういった例が初めてということでございましたので、地域の方々の自主的な取り組み、これから地域との連携、そういった部分についてどういう取り組みができるのか検討して、大田区の例も参考に進めていきたいというふうに考えております。","voiceIndex":65,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"ぜひよろしくお願いします。それからもう一点は、避難所としての機能のところがずっと気になっているんですよ。ケアホームで２階、３階、しかも個室になる、それから、幼保一体施設、シルバーセンター等々で、このスペースが単純に避難所として使えなくなるわけです。ですから、確認したいのが、この原小学校に避難する予定の方々をどこに避難させるような計画をつくったのかということが一つ。","respondent":"日下部企画財政課長","answer":"ただ、その辺は２階、３階が確かに居住のスペースで、実質的に共有スペースなんかはまた別かと思いますが、なかなか難しいということになりますけれども、体育館、それから西側の校舎、それから１階部分のスペースということで、全体で、例えばあわせますと。","voiceIndex":67,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"わざわざ窮屈にすることがわかりながら進めなきゃいけない部分もありますよ、それは理解するんですけれども、言いたいのは、最後に課長答弁があったように、防災計画全体を見直しながら、ここの原小学校に避難する予定の方々が例えば近くの公園なり、それから集会所なりに分散できる上位計画をしっかりつくっていただかないと心配ですということでありますので。","respondent":"日下部企画財政課長","answer":"先ほどご答弁申し上げましたように、当然これから見直しの問題も不可避でありますので、その中で、今まで従来のいろんな経過はもちろん尊重すべきでありますけれども、新しいスペースがまた一方で生まれるとか、地域センターがすぐ近くにあるというようなことも含めまして。","voiceIndex":69,"id":"exchange-017"},{"speaker":"川西委員","kind":"質問","question":"内容については、これまでいろいろ当委員会で出されてきましたので問題はないと思っています。ですから、ハードの交付金とか、適用になる部分もあろうかと思うので、全体の骨格予算と、これは、数字はいいんですよ、動いてね。ただ、聞くだけですから。国から取れる金の割合というのはどういうふうに積算をされているのかというのが一つ。ふろはどうするのか、伺っていきたいと思います。","respondent":"日下部企画財政課長","answer":"３点目のケアホームの入居費の関係ですけれども、これにつきましては、いろいろどのくらいになるかということでありますけど、私ども目安としましては、少なくともやはりご安心して入居いただくということで、例えば２０万円を切るぐらいのところを一定の目安にして。","voiceIndex":71,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問・要望","question":"前回、要望などが５件というところから入りたいんですけど、実際に余りにも少ないんじゃないか、どこまでを明らかにするかというところで、５件ではなくまだあって、形となっているものが５件しかなかったという公表なのかどうなのか、そこのところをもう一度確認をさせていただきたいということと、６月２９日に出された原案との変更点が今説明ありましたけれども。","respondent":"堀越行財政改革担当課長、日下部企画財政課長","answer":"ホームページで意見・要望を募集したところの件数ですけれども、こちらについては５件、８月３０日にご報告させていただいた件数で、これは単純にそのまま集計して出した数です。先ほどご説明申し上げましたけれども、改めましてそのポイントを確認しますと、表のほうの利用内容の(1)の福祉ニーズへの対応ということで、施設の関係の面積が幼保一体施設は変わっておりません。","voiceIndex":73,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"そこがよく理解できないので、お願いしたいことと、先ほど国の補助金の部分で、個室ユニットのケアと優良賃貸住宅などを事業者がつくる場合には３分の２の交付ということでしたけど、これは基本的には建てるのは区ではないかと思っていたんですが、事業者は施設を貸与し一体的な運営を図るということなので、事業委託なのかなというふうに思っていたんですが、そこを整理していただきたいのと。","respondent":"日下部企画財政課長、新美企画部長","answer":"となると、幼保一体施設は逆に２階以上と、そういうようなことを私どもその時点では見込んでおりましたけれども、先ほどご説明させていただきましたように、高齢者向け優良賃貸住宅制度という制度を使えば。ということで、今回はそういう制度導入もあったということと、学校施設でベランダをあらかじめ設置することは大変難しいという建物上の制約もあるので、この制度を使わせていただいて、そうしますと。","voiceIndex":76,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"さっきの民間事業者のところで、土地は区で、改修は事業者の責任という位置づけであるということなんですが、亀田邸跡の施設で言うと、プロポーザルをしている事業者が、自分たちが事業をするためにこういう設計だというようなセットでプロポーザルをされているようですが、今回の場合には、そこのところは区の関与がほとんどなのか。","respondent":"日下部企画財政課長","answer":"スケジュールに、何ゆえに運営者を先に決定するかということになりますと、つまり、今まではどちらかというと、決まった施設を、もう設計もやって、あてがいぶちで、さあこれで運営してくださいというんですが、今事例として亀田邸跡を出されましたけれども。","voiceIndex":79,"id":"exchange-021"},{"speaker":"井上委員","kind":"確認","question":"整理をするということはいいんです、文章だから。民間委託事業者が同一なんですねということを確認したい。","respondent":"日下部企画財政課長","answer":"そうです。","voiceIndex":81,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"それで今回の場合には、亀田邸跡は指定管理者だと思いますけれども、その方たちが設計をした段階で、今回は指定管理ということに触れていないんですが、そこのところはどうなのかということと、デザイン、亀田邸跡でもそうだと思うんですけど、もしその事業者が５年でかわるということになれば、５年契約だと思いますから、何らかのことがあってかわるということになったら、自分たちが設計したものと。","respondent":"新美企画部長","answer":"今回決めて一定の期限を切りますから、期限後に違う事業者、それは本当にハードの付帯の部分ということになりますと、それは一定、次の事業者はそれが一つの所与の条件の中でどうするかということになりますし、備品みたいにもっと償却が短いものであれば。","voiceIndex":83,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"今までの話ですと、収容人数６９７人は、定数が変わらないというお話を聞いていたと僕は思っているんですけれども、その辺が変わっていたのか、もっと言うと、狭くなるということは、何平米から何平米、そこら辺を教えていただけますか。","respondent":"日下部企画財政課長","answer":"防災の倉庫についても、いろいろ今検討しておりますけれども、この辺の防災倉庫の機能をこの中で少し充実していこうとか、そういう意味で受けとめていただきたいというふうに思います。","voiceIndex":85,"id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"今回のこの計画だと２,７００m2だ。今の１,２００m2の考え方は、通常は学校の授業をやっている普通教室、ああいうところを計算に入れていると思って、廊下は入っていないのかなと思うんですけれども、いつ来るかわからない地震に対する対策は繰り返すまでもなく強調されていますので、狭くなるということはあってはいけないと思いますので、そこをもう一度お聞かせいただけますか。","respondent":"日下部企画財政課長","answer":"そういうことを総合的に考えれば、避難人口が増えるというようなことも東京都の想定の中でも言われているわけでありますし、そういうことも含めてトータルで考えていただければ、避難所機能としての維持強化、これを一つのきっかけとして十分確保できる。","voiceIndex":87,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"今の説明だと、いまいち、じゃあ、何が狭くなるのか。広い意味で強化されるんだ、その辺がよくわからないのでもう一度伺いたいのと、それと２点目の質問を一緒にしたいと思うんですけれども、自主管理の話ですね。計画説明会や施設概要説明会は、いつ開くお考えなのか、今後の展望など、お考えがありましたらお示しください。","respondent":"日下部企画財政課長","answer":"ですから、今後どういう形で計画の内容を地域の皆様方にご説明するかと、その辺についてはこれから検討していきたいと、このように考えてあります。","voiceIndex":89,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"この計画をどのような形で地域に説明するかをこれから検討するというお話ですけれども、今日このスケジュールのところで、利用案決定、運営者公募、平成１９年度は４月運営者決定、このスケジュールがありますけど、この中で、地域への説明、施設概要説明会、そこをいつごろ位置づけているのか教えていただけますか。","respondent":"日下部企画財政課長","answer":"基本的に案の骨格自体は変わっていないということもありますけれども、いずれにせよ、これからの全体のスケジュールの中でどういう形でまたお示しをしていくのかということは、今申し上げたようにこれから検討する課題であると、このように考えております。","voiceIndex":91,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"そろそろまとめますけれども、内容を説明する、どのような形なのか検討するというお話ですけれども、先日、都南病院跡地の概要説明会がきゅりあんでございましたよね、１０月２６日。これは新築工事に伴う、条例に伴う説明会というよりも、地域の方々に概要をご理解いただきたいと、そういうある意味積極的な区の姿勢で進めたものだと聞いているんですね。いかがでしょうか。","respondent":"日下部企画財政課長","answer":"今までもきちんと手順を踏んで、計画案につきましても、議会にご報告をまずするということで進めてきたわけでありますし、繰り返すようでありますけれども、その辺については、今後の検討すべき課題であると、このように考えております。","voiceIndex":93,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利用内容についてお伺いをします。増大・多様化する福祉ニーズへの対応ということで、１点目が子育て支援、２点目が高齢者の介護等というところなんですけれども、幼保一体の施設、現在品川区では二葉すこやか園、あとぷりすくーる西五反田がありますけれども、もうちょっとこの辺、イメージがわかったらと思います。","respondent":"日下部企画財政課長","answer":"高齢者向け優良賃貸住宅の制度ですけれども、これは先ほど企画部長からもご説明させていただきましたけれども、高齢者の皆さん方に安心して居住していただけるような、そういう住宅を提供するという趣旨のもとで、住宅に、さらに、これは要するにソフトもセットになるわけですが。","voiceIndex":95,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"優良賃貸住宅のところなんですが、これは新しい制度なんでしょうか。","respondent":"日下部企画財政課長","answer":"高齢者向け優良賃貸住宅の制度でありますけれども、かなり前からある制度です。ただ、これが特徴的なのは、平成１３年に高齢者の居住の安定確保に関する法律というのが国のほうでできまして、ある意味でこの裏づけに基づいて実施をされている、いわば法定事業です。","voiceIndex":97,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園のところは、認可がベースなのでご安心していただきたい。現状の認可保育園の水準が保たれると信じますので、よろしくお願いいたします。高齢者向け優良賃貸住宅というところで、今介護保険の一つとして取り入れられるというところにおいては、特別養護老人ホームなんかをつくる場合にもこれは利用できるんでしょうか。","respondent":"日下部企画財政課長","answer":"この制度は、実は特養自体は対象に入っておりません。有料老人ホームでありますとか、軽費老人ホームが従前からそういう対象になっております。今年の４月から高齢者向け優良賃貸住宅が対象の一つとしてつけ加えられたと、そういうものです。","voiceIndex":99,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ケアホームについては、この辺、ニーズが、要求がどうなのかと、私も総括の質問のところで取り上げさせていただいたんですが、区の発表のところで特別養護老人ホームは４５０名の待機者に対して、ケアホームのところは３０名の待機者というところで、都南病院跡地もケアホーム、続いて原小学校跡施設もケアホームというところにおいては。","respondent":"日下部企画財政課長","answer":"ただ、それだけではなくて、これから高齢化がさらに進行する中で、それこそいろいろなニーズにこたえていく、やはりそういう必要がありますので、今は地域バランスに配慮しながらケアホームの計画的な整備、認知症のグループホームを含めまして。","voiceIndex":101,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"今後の予測というのはたぶんいろいろあると思うんですけれども、その辺の予測をされるところの材料が何なのかというところを特にお伺いしたいのと、私たちとしては、現状においてのさまざまなニーズ、これから団塊の世代が仕事を離れてボランティアとかいろいろされる中で、高齢に向かっていくというところでは、いろいろな考えがあると思うんですけれども、その辺に当たって、ぜひ区民の意見を。","respondent":"新美企画部長","answer":"区民のご理解については、なかなか具体的なサービスが西五反田ケアホームだけですと、ちょっと地域もあれしていまして、今度都南病院跡等もでき、場合によっては原小学校もでき、幾つかのタイプを見ていただければ。","voiceIndex":103,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、いろいろなものをつくるのはもちろんいいと考えていますが、特別養護老人ホームが不足をしているという認識をぜひ持っていただきたいんですが、この点、くどいようですが、お答えをいただきたい。地域活動・交流のところで、幼保一体化施設のところで、園庭を時間外、地域の少年野球とかサッカー等に使うというところがあるんですが、この時間外というとらえ方がどうなのかなと。","respondent":"新美企画部長、日下部企画財政課長","answer":"ただいまの最初のご質問ですが、私どもは企画ということで、先ほどご答弁させていただいたのは、区としての現在の全体的な基本的考え方で、さらにということになりますと、所管の部がもう少し詳細にということもあろうかと思いますので。園庭の関係ですけれども、具体的に何時から何時までとか、これはまた施設運営についての具体的なこれからのさらなる検討、詳細な検討の中で決めていくものですが、いずれにしましても、幼保一体施設として、それはそれで。","voiceIndex":105,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこのところは、少年野球とか、サッカーとか、結構活発にやられているところなので利用者の声を聞いていただきたいなと思います。総合化とか、一体化とかというと、やはり競合して我慢をしなくちゃいけない部分というのがかなり生まれてくるんじゃないかなと思う。日野学園の体育館とか、プールの使い方なんかを見てもいろいろ感じますので、その辺はよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-035"},{"speaker":"須藤委員","kind":"質問","question":"１５０人ぐらい来ていましたよといった場合に、ここは園庭が使えるわけなんで、そうした場合に、やはりニーズにこたえてある程度スペースをつくっていってもできるだろうし、今言った校舎だけでもそういう余裕があるのかどうかということと、それから、ある程度今言ったように、人気が出てきた場合に、グラウンドにそういう新しい施設をつくって対処するような考え方をお持ちなのかどうか。","respondent":"日下部企画財政課長","answer":"ですから、現実問題として、幼保と高齢者の定員の例えばやりくりも含めてとか、あるいはそういうフレキシブルな設定というのができるかどうか、これからちょっとその辺も含めて検討、調整をしてまいりたいと、このように考えてあります。","voiceIndex":109,"id":"exchange-036"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そういうところに建て増しをしていっても受けられるよというような余裕があると思うんですよね。ですから、今の中のスペースでも１００人以上の園児を確保するということができるのかどうか、今お話ししたように、国や都の予算をとるために、今１００名なら１００名となるけども、あと２０人ぐらいはスペース的には入れますよというお考えを持っているのかどうか。","respondent":"日下部企画財政課長","answer":"２点目の園庭、例えばそれだけ人気があれば、園庭の増設とか、そういうことも考えられるのかですけれども、実は今の建物はいろんな法的な制約条件もありまして、増築が難しいという状況でありますので、その辺はちょっと難しいかなと。","voiceIndex":111,"id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"こちらのほうが、民間でそうしたほうがいろんな面でいいですよという形になって、こちらへどんどん皆さんが集まってくるというようなことも考えられてくるわけなんで、本当に長期的に一つつくっていくならば、そういう全体的なところの絵をかいてどうなんだという、そうすると、逆に言って、区立のほうがうんと少なくなっちゃった、じゃあそれ自体が。","respondent":"日下部企画財政課長","answer":"やはり、これは中長期の視点、地域の特性はもちろんですが、中長期の視点、それから、行政サービスに対する区民の皆さんのニーズ、それをどういうふうに受けとめて区として計画をしていくか、あるいは、その一つのポイントだけではなくて、少しやはり広い視野に立って。","voiceIndex":113,"id":"exchange-038"},{"speaker":"藤田委員","kind":"質問","question":"そこで、１点だけちょっと教えてください。大田区にとりましては、精神障害者の共同作業所というふうに銘打っておりますけれども、これまでそうした障害者の皆さんからの声がなかったのか、あったけれども、今回はこういう形で理解してもらうのか、そうした例えば住まいの確保、障害者の住まいの確保とか、そうしたものについては、どういうように今回のこの施設については検討されたのか教えてください。","respondent":"日下部企画財政課長","answer":"一方で、住まいの点につきましては、今回は特に計画としては盛り込んではございませんけれども、今後その辺はニーズ等も受けとめた上で、どのような形で計画として考えていくのか、今後の課題ではないかと、このように考えてあります。","voiceIndex":115,"id":"exchange-039"},{"speaker":"藤田委員","kind":"質問・要望","question":"要望なんですが、区として、やはり声が小さかったから取り入れなかったとか、そういうことじゃなくて、やはりバランスをいろいろ考えて施設については取り組んでもらいたいなと、今後のぜひ要望としておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"一番最初の議論に戻るかと思うんですが、地域の方の声をどう反映させたかというところで、先ほど来前回もそうですが、地元ＰＴＡの方たちのご意見というような言葉がよく出てきたんですが、この方たちはどういう団体なのかひとくくりにおっしゃっていますけれども、ＰＴＡとして声を出しているというものなのか、どういう方たちなんでしょうか。","respondent":"日下部企画財政課長","answer":"今年２月に、実は原小学校のご要望をいただきましたけれども、原小学校のＰＴＡの関係者といいますか、今現在ということだけではなくて、かつて原小学校のＰＴＡ活動に、いろいろＰＴＡの会長として活動されていた方とか、あるいは保護者の方、それから近隣にお住まいの方。","voiceIndex":118,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"私もその中の方たちをよく知っていますけれども、こういう形で地元のＰＴＡという自主的に集まった方々の声をやっぱりそれとは別に、きちんと私はＰＴＡの関係とか、こういったところに声を届けたいと思っている方たちもそこのグループ、グループという言葉は変ですけれども、そういうところではないところの学校関係というか。","respondent":"日下部企画財政課長","answer":"確かに今申し上げました皆さん、有志ということで自主的にご意見をいただいたわけでありますけれども、先ほど冒頭ご説明させていただきましたように、今回はやはり地域の皆さんに非常に愛着の強い学校の跡施設の活用ということで、ホームページでご案内をして、ご意見をいただく。","voiceIndex":120,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"要望でとめておこうと思ったんですけど。そういうことは今回たまたまこんなに頑張りましたというのを私たちはまだまだ不足だと思っていますけれども、取り組んでいただいたことは認めているんです。限られた町会とか、声が上がった人たちから十分聞きましたという姿勢だけは変えていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一体的運営を図るというところなんですけれども、都南病院跡地のときは、高齢者の部分と乳幼児のところと両方はなかなか難しいということで、保育園においては直営ということになったんですが、この辺の一体的運営を図ると一歩踏み込んだ、私は前進とは言いません、後退かなと思っているんですが、この辺の一体的な運営を図るというあたり、ここの判断について、ちょっと中身を教えていただきたいと思います。","respondent":"日下部企画財政課長、新美企画部長","answer":"施設の種類は違いますけれども、新しく新築する場合は、またいろんな配慮ができるかもしれませんが、今回は基本的には従前のものを改修するということも含めまして、そういう構造上の問題も含めまして。今回は、新たにこういう学校跡を使って福祉施設を新しくつくるということで、全国公募を考えておりますので、そういう意味では、全国的には高齢者および保育、両方実績のある社会福祉法人等ありますので、そういった意味では。","voiceIndex":123,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、営利目的がやはり子どもと高齢者のところにふさわしいかどうかというところで、私たちは本当に大きな疑問を持っていますので、今まで「社会福祉法人等」と書いてありますけど、「等」をとっていただいて、ぜひ本当に福祉のところでやっていただきたいなと思いますので、そのことだけは意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"今回、原小学校の跡施設の利用についての議論ということなんですが、校舎を改修して幼保一体施設やケアホームなどで活用するということなんですけれども、先日文教委員会のほうで大井地区の小中一貫校の愛称が決まって、「品川区立小中一貫校伊藤学園」というふうに決まりましたけども、名前も「原小学校」の「原」というのもなくなり、さらに校舎も違う施設が利用されるということで。","respondent":"日下部企画財政課長","answer":"その辺、どういう形がとれるのか、その辺はまた今後、今回はあくまで骨格を固めるということでありますので、その辺は今後の検討課題ということで考えてあります。","voiceIndex":127,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5810#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":37444,"voices":131}},{"id":"h18-20061127-6","meetingId":"h18-cm11","date":"2006年11月27日","dateIso":"2006-11-27","committee":"区民委員会","time":"午前１０時０３分～午後０時０６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１８年請願第２５号 「特定の同族会社の役員に対する報酬の損金算入制限規定」の見直しを求める意見書の提出についての請願","agenda":"平成１８年請願第２５号 「特定の同族会社の役員に対する報酬の損金算入制限規定」の見直しを求める意見書の提出についての請願","exchanges":[{"speaker":"本田委員","kind":"質問・要望","question":"ちょっとよくわからないところが多いものですから説明願いたいんですが、法人税、国税で品川区はタッチしないということが冒頭ありましたけれども、法人税の住民税は都が徴収をして、財調財源に入って国も還元しているということがあるという点を１つ確認をしておきたいと思います。それから、品川区内にはこの法律改正に伴う対象法人というのはどのぐらいあるのかわかれば教えていただきたいと思います。","respondent":"太田税務課長","answer":"これは実質、法人税についての規定ですので、ご指摘の部分については法人住民税のお話になろうかと思います。調整三税のもとといいますか、東京都の部分は法人住民税のお話になろうかと思います。","voiceIndex":6,"id":"exchange-001"},{"speaker":"本田委員","kind":"質問","question":"だから法人住民税で、法人はそういう税金が都に入り、国も還元されているんでしょうということを申し上げたんですが、そうじゃないというんですか。","respondent":"太田税務課長","answer":"そういう趣旨であれば、そのとおりです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"これは大手はどうなんですか。中小法人にはかなり税アップになるのかなと思うんですが、大手はどういうことですか。同じなのか、それからもう１つちょっとお伺いするのは、期末手当なんかの取り扱いについて、それは損益に算入すると、ボーナスですね、かなり大手が有利なというような話もちょっと耳にしたことがあるんですけれども、その辺はどういう扱いなんでしょうか。","respondent":"太田税務課長","answer":"大変申しわけないんですけれども、細かなことは私は把握してございませんけれども、このご質問の趣旨であれば、ここのオーナーおよびその同族関係者が株式の９０％を有して、かつ。","voiceIndex":10,"id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"どうもよくわからないんですけれども、今年の４月からですよね。実際、来年の申告から具体的に動くんだと思うんです。つまり、どのくらいこの改正によって増税になっているのかというのはまだわからない、見込みはわかっているんですか。","respondent":"太田税務課長","answer":"それから中小についても、税理士会も法案改正前にいろいろ要望等を出されてありますので、そういう面では全く１００％ご存じかどうかというのは難しい話ですけれども、そういう動きがあるということはご存じなのかなと。","voiceIndex":12,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"法改正の実態といいますか、状況はよくまだわからないんですけれども、品川の区議会にこういう請願が上がったということは、２３区はじめ都下の税理士関係のところから都に対しても上がっているんじゃないかなと、また全国的にもこういう動きが新たに出てきているんじゃないのかなと思うんですけれども、その辺の掌握はどうなんでしょうか。","respondent":"太田税務課長","answer":"私も東京都の関係は調べたんですけれども、現時点では出ていないようです。２３区については、私の調べた範囲では中央区が３月３０日に採択し意見書を出したと、新宿区が１０月です。それ以外については、各区の状況、都下の様子というのはちょっとつかんではございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"中身のことじゃなくて、制度の話を聞くので恐縮なんですけれども、今のお話でいくと、以前、改正前は法人にすることによってメリットは何だったかといったら、オーナーのこれが経費として落とせたよと、個人事業者じゃ落とせないのが、ここで落とせたよということがなくなっちゃうよという税制改正だと理解してよろしいんですか。","respondent":"太田税務課長","answer":"改正前は６００万円の役員報酬があれば、６００万円損金として算入できた、控除できた、それが先ほど言いましたように給与相当控除ですから、全額じゃなくて１７４万円は控除損金算入しないよということで、繰り返しになりますけれども。","voiceIndex":16,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"なかなか税関係というのは全然わからないところでして、３会派が紹介議員になって、今日はどなたも委員がいらっしゃらないので、その方たちからの説明も聞けないんですけれども、できるだけ早いうちに採択して意見書を上げるということは必要なのかなという気はするんですけれども、私自身としては、今、お二人の方の質疑を伺っていてもなかなか理解しにくい、自分の能力があれしているのも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"特に日本の経済を支えている中小企業、約九十何％ですか、日本の経済を支える、そういう方々がそれだけの負担が増えるということについては、場合によっては経済の動向に大きく影響を与えるようなことも考えて、ただ、もう少しこういう人たちの側に立った考え方も必要かなという意味からいきますと、先ほどおっしゃっておられた日本商工会議所あるいは東京商工会議所や。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"南委員","kind":"意見","question":"私はさっきもう少し時間をと申し上げましたけれども、皆さんがそういうことであれば、別に採択することに否定的な立場ではありませんので、中身をよく知った上で採択をしていきたいという思いから発言したことですので、いいと思います。皆さんがそういうことであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"今、このような税制改正でかなりの大きな影響をそれぞれの人に与えるということになれば、多くの者が、経過措置的なものを最低でもつくるとかというのは往々にある話なんですけれども、例えば３分の１ずつ３年にわたってやるとか、４分の１ずつ４年にわたってやるとか、そういうのがあるのを含めて、何かもし影響がものすごいとなれば、やるべきだというのが１つ思いましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"}]},{"id":"topic-02","title":"しながわの一番店発見プロジェクト","agenda":"しながわの一番店発見プロジェクト","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"先ほど８つのカテゴリーとおっしゃった一部だけ詳細がわかるんですが、そのほかのものはどういうものなのか、店舗の種類によってなのかなと思うんですけれども、教えていただきたいと思います。","respondent":"金子産業振興課長","answer":"８つのカテゴリーについてのお尋ねですけれども、先ほどちょっとご紹介しましたが、それも含めてご紹介しますと、食料品が１つ、それから２番目に飲食店、３番目に生活用品、それから４番目に菓子であるとかパンであるとか、そういった菓子パンのお店、５番目に生花、花ですね。","voiceIndex":40,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"その８つのカテゴリーの中で全体で２９５店なんですが、一番推奨する数の多かった部門というのはどんな状況なのか、絶対おっしゃっていただかなくていいんですけれども、その辺のバランスがわかればなと。品川区の全体の個店だとか商店街の形成との関係で、そういう推奨される、その数字が比例しているのか比例していないのか、その辺の数がもしわかれば教えてください。","respondent":"金子産業振興課長","answer":"ですけれども、例えば一番少ないのはスーパーなど６番目のカテゴリーに関しては４店舗の応募しかありませんでしたので、こういうふうな数です。","voiceIndex":42,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"ですからその辺のところなんかも非常に選んでいく上で苦労されるところなんだろうなと思うんですけれども、あと、きれいさだとか清潔さだとかというのも業種によっていろいろと、幾ら努力してもなかなかそう見えない業種というかしら、商品の扱いの内容で変わってくるというのがあるので、その辺は非常に苦労されるところなんだろうと思うんですけれども、できるだけ商店主の方々へのやりやすいというかしら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"事業目的、事業概要はわかったんですけれども、この事業をこの目的でこんなことをやろうということのアイデア等々がどんな形で出てきて、どうここにつながったのか、そしてこれがこれからの形ではどうなっていくのか、来年同じ店ばかりが応募してこられてもまたどうかなということもあるので。","respondent":"金子産業振興課長","answer":"具体的に今回の一番店発見プロジェクトのアイデアというのは、私どもと商店街連合会でいろいろ意見交換する中で出てきたものですけれども、従来型のコンクールに終わらせないために、１つは単なる人気投票だけに絞り切らないということと。","voiceIndex":45,"id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"やっぱりそれぞれ商店を束ねているところあたりの皆さんのほうからアイデアが出てきてもらわないと、役所で考えたのでは次に続かないような気がしたので、それで伺ったところです。それで、バリューアド大作戦で推奨店が決まるわけですけれども、その推奨店がうだつが上がるようにするには何か方法が必要なんですけれども、そういうのは何かあるんでしょうか。","respondent":"金子産業振興課長","answer":"そのほかホームページ、ＣＡＴＶ等でも取り上げる予定で、特にＣＡＴＶにつきましては１月から、短い時間ですけれども、２週間に８店舗ずつ、計５回にわたりましてＣＡＴＶで取り上げていただけるという予定になってあります。","voiceIndex":47,"id":"exchange-015"},{"speaker":"林（和）副委員長","kind":"質問","question":"このお店を選択するにあたりまして、それぞれ投票箱を設置されまして投票されたわけですけれども、投票者数が１万２,２７０名の方々が投票されたわけですけれども、この投票された方々というのは、１人が５店舗までは投票できるということですけれども、１人の方が何回も投票できるんですか。どういうふうな状況なんですか。","respondent":"金子産業振興課長","answer":"これにつきましては、投票に際しまして住所、氏名等を記載していただくような形になっておりますし、インターネットに関しましてもアドレスでチェックするようになっておりますので、お一人の方が何票もできないような仕組みにしています。","voiceIndex":49,"id":"exchange-016"},{"speaker":"林（和）副委員長","kind":"質問","question":"そうしますと、それはわかったんですけれども、住所、氏名を書いてこられて２票も３票も入れた方って今まであったんですか。","respondent":"金子産業振興課長","answer":"何人かの方はそういうものもございましたけれども、それについてはカウントしないで無効票という格好で取り扱わせていただいております。","voiceIndex":51,"id":"exchange-017"}]},{"id":"topic-03","title":"４番目のしながわ発見お宝探し","agenda":"４番目のしながわ発見お宝探し","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"２つ伺いたいと思いますけれども、ゴールした方へ地域特製の参加賞ということで、海苔、荏原だと、海苔というのはちょっと違うような感じがするんですが、むしろ産業振興で、お金が回るのであれば、単価がどうのこうのというのは別にして、商品券というのも考えられるのではないかなということが１つ、それと、協力店で１商店街・２郵便局となっていますが。","respondent":"金子産業振興課長","answer":"それから２郵便局ですが、これはお茶とキャンディーをサービスしていただくという予定になっておりまして、場所で申しますと荏原町の商店街にある郵便局と、それから中延の商店街の荏原中延駅からすぐ入ったところにある郵便局、この２郵便局です。","voiceIndex":57,"id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"申込状況が１,７２０人、募集人員が３,０００人ということなんですけれども、２１日現在ですから、締め切り分まであと４日あったのでちょっと増えているとは思うんですけれども、募集人員に対する実際の申込人員ということの考えというか、感想はどういうふうに思いますか。","respondent":"金子産業振興課長","answer":"確かに一応設定は３,０００人ということで、多くても少なくても困るなというところがあるんですけれども、この資料をおつくりした時点で１,７２０人でしたが、昨日の夜現在で２,８６５人となっておりますので、ですのであと４日ちょっとありますので。","voiceIndex":59,"id":"exchange-019"},{"speaker":"土井委員","kind":"意見","question":"この種のものの宣伝をうまくすると、区外の方もご参加をいただける手だても含めて、それなりになさっているのではないかと思いますが、東急電鉄あたりだとどこかから運んできてくれるかもしれないので、その辺はどのようになっているかちょっと聞かせてください。","respondent":"金子産業振興課長","answer":"区内と区外のお尋ねですけれども、私ども広報関係あるいはポスター関係は区内中心なんですけれども、東急電鉄が駅にポスターあるいはチラシ、それから電車とバスの車内刷り広告を出す、あるいは東急で出していらっしゃるフリーペーパーで『ＳＡＬＵＳ』とか。","voiceIndex":61,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"今の質問を伺っていて、宣伝効果というか、そういう電車のあれだとかも、ホームページだとかの効果がすごく大きいなと改めて思ったんですけれども、大事なことだなと思うんですけれども、いろいろな準備等の関係で３,０００人ということで応募をしていただくという方式をとったんだろうと思うんですが、やっぱりたまたま土曜日で、午前１０時から午後４時って非常に買い物というか。","respondent":"金子産業振興課長","answer":"ですので当日も受け付けしますよとＰＲしてたくさんの方がお見えになってしまうと、事前の指導にも反することになるので、この辺はちょっと慎重に対応させていただければと考えています。","voiceIndex":63,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"最後にですけれども、数との関係では安全確保というところはわかりましたけれども、私もあまり駅の周辺ってよくわからないんですけれども、旗の台駅南口がそういう意味でスタート地点になっているので、小山台高校の広さと比較すると、スペース的に、空間的にそんなに大きくはないんじゃないかなと思うので、その辺、事前の指導との関係でここを選択したというのは。","respondent":"金子産業振興課長","answer":"ただ、たくさんの人数はそこで待たせることはできないので、１１時スタートとなっておりますけれども、ある程度たまり切らないところでどんどん受け付けして流そうという予定になっております。","voiceIndex":65,"id":"exchange-022"},{"speaker":"山内委員","kind":"質問・要望","question":"簡単な説明で教えていただきたいんですが、今回２回目ということなんですが、前回は何名ほど、何％ゴールしたんですか。","respondent":"金子産業振興課長","answer":"１４番のその他の(1)のところにありますとおり、１回目は９月末に実施しておりまして、こちらは旧東海道の名所めぐりということと屋形船からをポイントにしております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"林（和）副委員長","kind":"意見","question":"今回のこのお宝探しについて、大体これは予算はどのぐらいでやっているのかということと、それから今回の協力店に対して助成が出ているのかどうか、どういうふうになっているのか、協力だけしてもらっているのか、その点を。","respondent":"金子産業振興課長","answer":"予算あるいは経費等々のお尋ねですけれども、私ども、今回のこの事業は３つのまち歩きの事業と、それから３月に観光フォーラムをきゅりあんで実施しようと考えておりまして、その観光フォーラムにはこのまち歩きを３回、モデル事業と申し上げましたけれども。","voiceIndex":69,"id":"exchange-024"}]},{"id":"topic-04","title":"５番目の現在の区内大気状況（しながわの空）システムの稼動","agenda":"５番目の現在の区内大気状況（しながわの空）システムの稼動","exchanges":[{"speaker":"南委員","kind":"質問","question":"資料をお配りいただいている『環境と清掃リサイクル』の測定地点との整合性ってちょっと見ていないからよくわからないんですけれども、あそこに出ているもの全部を一般局、移動局、自排局の何カ所かの地点は全部網羅しているということでいいんでしょうか。それとも一部だけ、高いところだとか、一定程度の基準を設定して、それだけを設定しているということなのか、その辺を。","respondent":"田中環境課長","answer":"すべての測定局になります。","voiceIndex":75,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"それからもう１つですけれども、移動局のところでは先ほど二、三年ごとに移動しているということで今回は上神明小学校になっているようなんですけれども、前回の、数年前のところから上神明小学校に移動したというのと、またさらに数年後にはどこかの地点には移動していくわけですけれども、その辺の地点を特定するというのはどういうところで決めていくんでしょうか。","respondent":"田中環境課長","answer":"一般的な住宅地等で、それなりにさっき立ったところから離れたところで、地区等のバランスを考えて測定局を移動させていくということになります。","voiceIndex":77,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そうすると、たまたま今回は上神明小学校のところとなっているんですが、地区とのバランスというところでは全体的な地図上での住宅地、荏原地域だから、今度は品川地域とか、大井地域とかというふうに次回のところはピックアップしていこうということで決めるんですか。","respondent":"田中環境課長","answer":"過去の経過もありますので、その辺等も含めまして地点を決めていくということです。","voiceIndex":79,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"この数値が出ますよね。これを、例えば改善を求めて、例えば都とかにこの数字とかは言うんですか。報告をしたりしているんですか。","respondent":"田中環境課長","answer":"この大気のデータですが、いろいろ大気汚染の状況を監視するという意味がありますので、これに基づいていろいろな施策の基礎データになっていくということになります。ということで、環境基準等々の関係でどうなのかというところは問題になってくるところだと。","voiceIndex":81,"id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"今、公開されているのがオキシダントを含めた内容なんですけれども、例の光化学スモッグ注意報という場合ですと、専門家のところがお出しになっているものを流しているんだろうと思いますけれども、そことの関連を含めて、例えばこのシステムで基準値を大幅かどうかわからないけれども、オーバーするようになったら警報が出るとか、何かそういう形で知らせるとか、その種のものとの連動はあるんですか。","respondent":"田中環境課長","answer":"当然、一定の状況になると都から解除通報とかが来ますが、このホームページ上でもそういう光化学スモッグ注意報のアナウンスは連動するように考えておりますので、当然、できるだけ都とも連携をとりながら有効に活用していくように工夫していきたいと考えています。","voiceIndex":83,"id":"exchange-029"},{"speaker":"土井委員","kind":"意見","question":"今のでいきますと、今までは光化学スモッグ注意報は都のシステム等で、都で観測されて、トータル的にこちらの地区は出そうよということになったときに品川に連絡が入って、それを広報、アナウンスするという流れだったと。今度このシステムが稼働すると、品川で独自のある種のラインをつくって判断も可能になる、そこら辺も可能ならば、できたらやりたいと、こういうお話ですね。","respondent":"田中環境課長","answer":"そこまではちょっといかないんですが、ただ、観測されたオキシダントの部分について、大田・品川で大くくりでの状況という形ではなくて、品川はこういう濃度になっていますというところが詳しくはわかりますが、システムとしては東京都のシステムと連動したような形で。","voiceIndex":85,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"非常にこの数字というのは、朝の８時ですから当然あまり経済的な活動って進んでいないので、こういう濃度が低いのはこういう状況なんだなとわかるんですけれども、日常的な印象としては、八潮はとても０.０２４ｐｐｍなんていうことはあり得ないと思うので、そういう、例えば、見たときはわかるけれども、一定程度の経過だとか、そういう部分がこれと同時にわかるようになってほしいなと思うんですけれども。","respondent":"田中環境課長","answer":"大気の状況なんですが、先ほどご説明したように、測定データ、環境基準と比較するときに９８％値というのを使うんです。３６５日その日の平均値を並べまして、下から９８％目のところの高い値のところで比較するわけです。","voiceIndex":87,"id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"結構、住民でずっと運動されている方々、私も参加したりもしているんですけれども、毎年１２月の上旬に大気汚染の測定運動というのがあって、測定しているんですけれども、そういう状況の中で、特に八潮の大気汚染に非常に関心が自分の住まいもあるということであるわけなんですが、八潮のところが非常に汚染しているというのを実感するので、この８時の時点はいいけれども、例えばもう少し経済活動が進んで。","respondent":"田中環境課長","answer":"たどっていきまして、これはその画面が出てきますので、表で数字も入っておりますし、折れ線グラフで表示できるようになっておりますので、１週間についてもその後、右側のほうを選択していただければ局ごとに出るようになっています。","voiceIndex":89,"id":"exchange-032"}]},{"id":"topic-05","title":"明治大学との共同研究に関する協定","agenda":"明治大学との共同研究に関する協定","exchanges":[{"speaker":"土井委員","kind":"意見","question":"大学等との共同研究というのはいいことだと思いますけれども、そういう点でも、いわゆるここでは一応共同研究のための一定の費用の負担をすることによって、明治大学でシステム等を開発していただいて、それらを活用しての具体的なものはサーバーをずっと使うという形で区民に提供されると、こういうことになっていくんだと思いますが、一応、当面。","respondent":"中山資源循環推進課長","answer":"したがって研究経費としては、先ほど申し上げた３００万円で基本的なプログラムであったり、システムの研究をやっていくという形になるです。","voiceIndex":99,"id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"わかりました。だからメールサービス等については、もう既に先ほどあった学生との受講にもやっていらっしゃるという形の中でのその改良型ですから、そんなにむちゃくちゃな手間ひまはかからないんだろうなというふうな印象を持っています。これはそのときには費用対効果の問題等々いろいろありますので、また聞かせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-034"}]},{"id":"topic-06","title":"の最後でございますが、品川清掃工場モデル収集可燃ごみの焼却実証確認実施報告","agenda":"の最後でございますが、品川清掃工場モデル収集可燃ごみの焼却実証確認実施報告","exchanges":[{"speaker":"南委員","kind":"質問","question":"測定期間が８月２１日から２８日ということで１週間とったんですけれども、このモデル実施の期間の中での８月２１日から８月２８日はどういう期間に該当するのかというのを改めて伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"３の(1)です。７月からモデル収集をしておりますから、このモデル事業そのものは引き続き現在も分別変更で継続しているものです。","voiceIndex":106,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"それで、基準値が法律と都条例と、協定値というのがこれは品川区としての協定値というふうに思っているんですけれども、それがいいのかどうかと、それから、数値が協定値というところから見ても不検出が大部分なんですが、数字が出ているのは少なくとも協定値をずっと下回っている、半分ぐらいというふうなところがあるわけですが、数字が出ていないところももちろんあるんですけれども、そういう関係で。","respondent":"中山資源循環推進課長","answer":"どうなのかという話ですが、これは少なくともこの分別変更のモデルごみを一定の期間の中でも基準はクリアしたですが、このことと何でも燃やしていいのかという分別の考え方とはちょっと次元の違う話ですので、これはごみをそもそも減らしましょうとか。","voiceIndex":108,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"確かに先ほどの説明のようにさまざまな数値、とりわけダイオキシンの数値が予想を大幅に下回って１,０００兆分の１.２ｇというふうな説明でしたけれども、確かに数値的には少ないとは思いますけれども、でもいろいろな外国の考え方というのは、限りなくゼロに近づけるということで、できるだけ害のあるものはゼロにしていくんだと。","respondent":"中山資源循環推進課長","answer":"繰り返しになりますが、環境基準ははるかに下回っているということですが、今申し上げたように、そもそもごみを減らすということ自体は、これは当然資源循環型社会、都市を目指していくという観点から必要ですので、これは焼却の安全性とごみを減らしていこうということは。","voiceIndex":110,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2476#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":33649,"voices":117}}]);
